  Future<void> load() async {
    _prefs = await SharedPreferences.getInstance();
    final p = _prefs!;
    lang = p.getString(_kLang) ?? lang;
    weather = p.getBool(_kWeather) ?? weather;
    skyAnim = p.getBool(_kSkyAnim) ?? skyAnim;
    notifications = p.getBool(_kNotif) ?? notifications;
    profileName = p.getString(_kName) ?? '';
    profileCity = p.getString(_kCity) ?? '';
    setupComplete = p.getBool(_kSetupDone) ?? false;
    eveningLampReminder = p.getBool(_kEveningLamp) ?? false;
    isPremium = p.getBool(_kPremium) ?? false;
    final expiryMs = p.getInt(_kPremiumExpiry);
    premiumExpiry = expiryMs != null
        ? DateTime.fromMillisecondsSinceEpoch(expiryMs)
        : null;
    memberId = p.getString(_kMemberId) ?? '';
    profileAddress = p.getString(_kAddress) ?? '';
    final dobMs = p.getInt(_kDob);
    profileDob = dobMs != null
        ? DateTime.fromMillisecondsSinceEpoch(dobMs)
        : null;
    // à¦à¦•à¦¬à¦¾à¦°à¦‡ à¦¤à§ˆà¦°à¦¿ à¦¹à¦¯à¦¼ â€” à¦à¦°à¦ªà¦° à¦¯à¦¤à¦¬à¦¾à¦° à¦…à§à¦¯à¦¾à¦ª à¦–à§‹à¦²à¦¾ à¦¹à§‹à¦•, à¦à¦•à¦‡ à¦†à¦‡à¦¡à¦¿ à¦¥à¦¾à¦•à§‡, à¦¤à¦¾à¦‡
    // backend-à¦ à¦à¦‡ à¦«à§‹à¦¨à§‡à¦° à¦¸à¦¾à¦¬à¦¸à§à¦•à§à¦°à¦¿à¦ªà¦¶à¦¨ à¦¸à¦¬à¦¸à¦®à¦¯à¦¼ à¦šà§‡à¦¨à¦¾ à¦¯à¦¾à¦¬à§‡
    deviceId = p.getString(_kDeviceId) ?? '';
    if (deviceId.isEmpty) {
      deviceId = _generateDeviceId();
      await p.setString(_kDeviceId, deviceId);
    }
    // à¦«à§à¦°à¦¿-à¦Ÿà§à¦°à¦¾à¦¯à¦¼à¦¾à¦² à¦«à¦°à§à¦® à¦†à¦—à§‡ à¦¥à§‡à¦•à§‡ à¦ªà§‚à¦°à¦£ à¦•à¦°à¦¾ à¦¥à¦¾à¦•à¦²à§‡ (activateTrial() à¦†à¦—à§‡
    // à¦¡à¦¾à¦•à¦¾ à¦¹à¦¯à¦¼à§‡ à¦¥à¦¾à¦•à¦²à§‡) à¦¸à§‡à¦‡ à¦¸à¦®à¦¯à¦¼à¦Ÿà¦¾à¦‡ à¦²à§‹à¦¡ à¦¹à¦¯à¦¼ â€” à¦…à§à¦¯à¦¾à¦ª à¦šà¦¾à¦²à§ à¦•à¦°à¦²à§‡à¦‡ à¦à¦–à¦¾à¦¨à§‡
    // à¦¨à¦¿à¦œà§‡ à¦¥à§‡à¦•à§‡ à¦•à¦¿à¦›à§ à¦¸à§‡à¦Ÿ à¦•à¦°à¦¾ à¦¹à¦¯à¦¼ à¦¨à¦¾, à¦«à¦°à§à¦® à¦ªà§‚à¦°à¦£ à¦¨à¦¾ à¦•à¦°à¦²à§‡ à¦Ÿà§à¦°à¦¾à¦¯à¦¼à¦¾à¦² à¦¶à§à¦°à§à¦‡ à¦¹à¦¯à¦¼ à¦¨à¦¾
    final installMs = p.getInt(_kFirstInstall);
    if (installMs != null) {
      firstInstallDate = DateTime.fromMillisecondsSinceEpoch(installMs);
    }
    final d = p.getString(_kDistrict);
    if (d != null) AppLocation.district = d;
    notifyListeners();
    // à¦†à¦—à§‡ à¦¥à§‡à¦•à§‡ à¦…à¦¨ à¦•à¦°à¦¾ à¦¥à¦¾à¦•à¦²à§‡ à¦…à§à¦¯à¦¾à¦ª à¦šà¦¾à¦²à§ à¦¹à¦“à¦¯à¦¼à¦¾à¦° à¦¸à¦¾à¦¥à§‡ à¦¸à¦¾à¦¥à§‡à¦‡ à¦†à¦—à¦¾à¦®à§€ à¦•à¦¿à¦›à§à¦¦à¦¿à¦¨à§‡à¦°
    // à¦¸à¦¨à§à¦§à§à¦¯à¦¾ à¦ªà§à¦°à¦¦à§€à¦ª à¦¨à§‹à¦Ÿà¦¿à¦«à¦¿à¦•à§‡à¦¶à¦¨ (real à¦¸à§‚à¦°à§à¦¯à¦¾à¦¸à§à¦¤ à¦¸à¦®à¦¯à¦¼ à¦¦à¦¿à¦¯à¦¼à§‡) à¦¨à¦¤à§à¦¨ à¦•à¦°à§‡ à¦¸à§‡à¦Ÿ
    // à¦•à¦°à¦¾ à¦¹à¦¯à¦¼, à¦¯à¦¾à¦¤à§‡ à¦¤à¦¾à¦²à¦¿à¦•à¦¾ à¦•à¦–à¦¨à§‹ à¦¶à§‡à¦·/à¦ªà§à¦°à¦¨à§‹ à¦¹à¦¯à¦¼à§‡ à¦¨à¦¾ à¦¯à¦¾à¦¯à¦¼
    if (eveningLampReminder && notifications) {
      await NotificationService.instance.scheduleEveningLampReminders();
    }
  }

  /// à¦Ÿà¦¾à¦‡à¦®à¦¸à§à¦Ÿà§à¦¯à¦¾à¦®à§à¦ª + à¦°â€à§à¦¯à¦¾à¦¨à§à¦¡à¦® à¦¸à¦‚à¦–à§à¦¯à¦¾ à¦®à¦¿à¦¶à¦¿à¦¯à¦¼à§‡ à¦à¦•à¦Ÿà¦¾ à¦®à§‹à¦Ÿà¦¾à¦®à§à¦Ÿà¦¿-à¦‡à¦‰à¦¨à¦¿à¦• à¦†à¦‡à¦¡à¦¿
  /// à¦¬à¦¾à¦¨à¦¾à¦¯à¦¼ â€” à¦•à§à¦°à¦¿à¦ªà§à¦Ÿà§‹à¦—à§à¦°à¦¾à¦«à¦¿à¦• UUID à¦¨à¦¯à¦¼, à¦•à¦¿à¦¨à§à¦¤à§ à¦à¦‡ à¦…à§à¦¯à¦¾à¦ªà§‡à¦° à¦œà¦¨à§à¦¯ (à¦à¦•à¦Ÿà¦¾
  /// à¦«à§‹à¦¨à¦•à§‡ backend-à¦ à¦šà§‡à¦¨à¦¾) à¦à¦Ÿà¦¾à¦‡ à¦¯à¦¥à§‡à¦·à§à¦Ÿ
  String _generateDeviceId() {
    final rnd = math.Random();
    final ts = DateTime.now().millisecondsSinceEpoch.toRadixString(36);
    final rand = List.generate(
      8,
      (_) => '0123456789abcdefghijklmnopqrstuvwxyz'[rnd.nextInt(36)],
    ).join();
    return '$ts$rand';
  }

  /// à¦«à§à¦°à¦¿-à¦Ÿà§à¦°à¦¾à¦¯à¦¼à¦¾à¦² à¦«à¦°à§à¦®à§‡ à¦¨à¦¾à¦®/à¦œà¦¨à§à¦® à¦¤à¦¾à¦°à¦¿à¦–-à¦¸à¦®à¦¯à¦¼/à¦ à¦¿à¦•à¦¾à¦¨à¦¾ à¦¦à¦¿à¦¯à¦¼à§‡ "à¦«à§à¦°à¦¿ à¦Ÿà§à¦°à¦¾à¦¯à¦¼à¦¾à¦² à¦¶à§à¦°à§
  /// à¦•à¦°à§à¦¨" à¦šà¦¾à¦ªà¦²à§‡ à¦¡à¦¾à¦•à¦¾ à¦¹à¦¯à¦¼ â€” à¦à¦–à¦¾à¦¨ à¦¥à§‡à¦•à§‡à¦‡ à§©à§¦ à¦¦à¦¿à¦¨à§‡à¦° à¦—à§‹à¦¨à¦¾ à¦¶à§à¦°à§ à¦¹à¦¯à¦¼ à¦†à¦° à¦¸à¦¾à¦¥à§‡
  /// à¦¸à¦¾à¦¥à§‡à¦‡ à¦à¦•à¦Ÿà¦¾ à¦¸à¦¦à¦¸à§à¦¯ à¦†à¦‡à¦¡à¦¿ à¦œà§‡à¦¨à¦¾à¦°à§‡à¦Ÿ à¦¹à¦¯à¦¼ (à¦ªà§à¦²à§à¦¯à¦¾à¦¨ à¦•à§‡à¦¨à¦¾à¦° à¦œà¦¨à§à¦¯ à¦…à¦ªà§‡à¦•à§à¦·à¦¾ à¦•à¦°à¦¤à§‡
  /// à¦¹à¦¯à¦¼ à¦¨à¦¾)à¥¤ à¦à¦•à¦¬à¦¾à¦° à¦…à§à¦¯à¦¾à¦•à§à¦Ÿà¦¿à¦­ à¦¹à¦¯à¦¼à§‡ à¦—à§‡à¦²à§‡ à¦†à¦¬à¦¾à¦° à¦¡à¦¾à¦•à¦²à§‡à¦“ à¦ªà§à¦°à¦¨à§‹ à¦¤à¦¾à¦°à¦¿à¦–/à¦†à¦‡à¦¡à¦¿à¦‡
  /// à¦¥à§‡à¦•à§‡ à¦¯à¦¾à¦¯à¦¼ â€” à¦¬à¦¾à¦°à¦¬à¦¾à¦° à¦°à¦¿à¦¸à§‡à¦Ÿ à¦•à¦°à¦¾ à¦¯à¦¾à¦¯à¦¼ à¦¨à¦¾à¥¤
  Future<void> activateTrial({
    required String name,
    required DateTime dob,
    required String address,
  }) async {
    profileName = name;
    profileDob = dob;
    profileAddress = address;
    final p = _prefs ??= await SharedPreferences.getInstance();
    await p.setString(_kName, name);
    await p.setInt(_kDob, dob.millisecondsSinceEpoch);
    await p.setString(_kAddress, address);
    if (firstInstallDate == null) {
      firstInstallDate = DateTime.now();
      await p.setInt(_kFirstInstall, firstInstallDate!.millisecondsSinceEpoch);
    }
    if (memberId.isEmpty) {
      memberId = _generateMemberId();
      await p.setString(_kMemberId, memberId);
    }
    notifyListeners();
  }

  /// à¦ªà§‡à¦®à§‡à¦¨à§à¦Ÿ backend à¦¥à§‡à¦•à§‡ verify à¦¹à¦¯à¦¼à§‡ "à¦¸à¦«à¦²" à¦«à¦¿à¦°à§‡ à¦à¦²à§‡ à¦¡à¦¾à¦•à¦¾ à¦¹à¦¯à¦¼ â€” à¦²à§‹à¦•à¦¾à¦²à¦¿
  /// à¦ªà§à¦°à¦¿à¦®à¦¿à¦¯à¦¼à¦¾à¦® à¦šà¦¿à¦¹à§à¦¨à¦¿à¦¤ à¦•à¦°à§‡ à¦¸à§‡à¦­ à¦•à¦°à§‡ à¦°à¦¾à¦–à§‡ (backend-à¦à¦° status à¦à¦¨à§à¦¡à¦ªà¦¯à¦¼à§‡à¦¨à§à¦Ÿ
  /// à¦¦à¦¿à¦¯à¦¼à§‡à¦“ à¦ªà¦°à§‡ à¦¯à¦¾à¦šà¦¾à¦‡ à¦•à¦°à¦¾ à¦¯à¦¾à¦¯à¦¼, à¦¨à§‡à¦Ÿà¦“à¦¯à¦¼à¦¾à¦°à§à¦• à¦¨à¦¾ à¦¥à¦¾à¦•à¦²à§‡ à¦à¦‡ à¦²à§‹à¦•à¦¾à¦² à¦•à¦ªà¦¿à¦Ÿà¦¾à¦‡ à¦¬à§à¦¯à¦¬à¦¹à¦¾à¦° à¦¹à¦¯à¦¼)
  Future<void> activatePremium(DateTime expiresAt) async {
    isPremium = true;
    premiumExpiry = expiresAt;
    final p = _prefs ??= await SharedPreferences.getInstance();
    await p.setBool(_kPremium, true);
    await p.setInt(_kPremiumExpiry, expiresAt.millisecondsSinceEpoch);
    // à¦ªà§à¦°à¦¥à¦®à¦¬à¦¾à¦° à¦ªà§à¦²à§à¦¯à¦¾à¦¨ à¦•à§‡à¦¨à¦¾à¦° à¦¸à¦®à¦¯à¦¼à¦‡ à¦à¦•à¦¬à¦¾à¦° à¦®à§‡à¦®à§à¦¬à¦¾à¦° à¦†à¦‡à¦¡à¦¿ à¦œà§‡à¦¨à¦¾à¦°à§‡à¦Ÿ à¦¹à¦¯à¦¼ â€” à¦à¦°à¦ªà¦°
    // à¦®à§‡à¦¯à¦¼à¦¾à¦¦ à¦¬à¦¾à¦¡à¦¼à¦¾à¦²à§‡/à¦°à¦¿à¦¨à¦¿à¦‰ à¦•à¦°à¦²à§‡à¦“ à¦à¦•à¦‡ à¦†à¦‡à¦¡à¦¿ à¦¥à§‡à¦•à§‡ à¦¯à¦¾à¦¯à¦¼, à¦¨à¦¤à§à¦¨ à¦•à¦°à§‡ à¦¬à¦¦à¦²à¦¾à¦¯à¦¼ à¦¨à¦¾
    if (memberId.isEmpty) {
      memberId = _generateMemberId();
      await p.setString(_kMemberId, memberId);
    }
    notifyListeners();
  }

  /// "BP-YYYY-XXXXXX" à¦«à¦°à¦®à§à¦¯à¦¾à¦Ÿà§‡ à¦ªà§à¦°à¦¤à¦¿à¦Ÿà¦¾ à¦ªà§à¦°à¦¿à¦®à¦¿à¦¯à¦¼à¦¾à¦® à¦‡à¦‰à¦œà¦¾à¦°à§‡à¦° à¦œà¦¨à§à¦¯ à¦†à¦²à¦¾à¦¦à¦¾ à¦à¦•à¦Ÿà¦¾
  /// à¦°à§‡à¦«à¦¾à¦°à§‡à¦¨à§à¦¸ à¦†à¦‡à¦¡à¦¿ â€” à¦¸à¦¾à¦ªà§‹à¦°à§à¦Ÿ/à¦ªà§à¦°à§‹à¦«à¦¾à¦‡à¦²à§‡ à¦¦à§‡à¦–à¦¾à¦¨à§‹à¦° à¦œà¦¨à§à¦¯, backend-à¦à¦° à¦•à§‹à¦¨à§‹
  /// à¦†à¦¸à¦² à¦¸à¦¾à¦¬à¦¸à§à¦•à§à¦°à¦¿à¦ªà¦¶à¦¨ à¦°à§‡à¦•à¦°à§à¦¡à§‡à¦° à¦¬à¦¦à¦²à¦¿ à¦¨à¦¯à¦¼ (à¦¸à§‡à¦Ÿà¦¾ device_id à¦¦à¦¿à¦¯à¦¼à§‡à¦‡ à¦¹à¦¯à¦¼)
  String _generateMemberId() {
    final rnd = math.Random();
    final year = DateTime.now().year;
    final code = List.generate(
      6,
      (_) => '0123456789ABCDEFGHJKLMNPQRSTUVWXYZ'[rnd.nextInt(35)],
    ).join();
    return 'BP-$year-$code';
  }

  /// backend à¦¥à§‡à¦•à§‡ status à¦šà§‡à¦• à¦•à¦°à§‡ à¦²à§‹à¦•à¦¾à¦² à¦…à¦¬à¦¸à§à¦¥à¦¾ à¦†à¦ªà¦¡à§‡à¦Ÿ à¦•à¦°à§‡ (à¦®à§‡à¦¯à¦¼à¦¾à¦¦ à¦¶à§‡à¦· à¦¹à¦¯à¦¼à§‡
  /// à¦—à§‡à¦²à§‡ à¦à¦–à¦¾à¦¨à§‡à¦‡ à¦§à¦°à¦¾ à¦ªà¦¡à¦¼à¦¬à§‡)
  Future<void> applyPremiumStatus({
    required bool active,
    DateTime? expiresAt,
  }) async {
    isPremium = active;
    premiumExpiry = expiresAt;
    final p = _prefs ??= await SharedPreferences.getInstance();
    await p.setBool(_kPremium, active);
    if (expiresAt != null) {
      await p.setInt(_kPremiumExpiry, expiresAt.millisecondsSinceEpoch);
    }
    if (active && memberId.isEmpty) {
      memberId = _generateMemberId();
      await p.setString(_kMemberId, memberId);
    }
    notifyListeners();
  }

  /// "à¦¸à¦¨à§à¦§à§à¦¯à¦¾ à¦ªà§à¦°à¦¦à§€à¦ª" à¦…à¦Ÿà§‹-à¦°à¦¿à¦®à¦¾à¦‡à¦¨à§à¦¡à¦¾à¦° à¦…à¦¨/à¦…à¦« â€” à¦…à¦¨ à¦•à¦°à¦²à§‡à¦‡ à¦ªà§à¦°à¦¤à¦¿à¦¦à¦¿à¦¨ real à¦¸à§‚à¦°à§à¦¯à¦¾à¦¸à§à¦¤à§‡à¦°
  /// à¦¸à¦®à¦¯à¦¼à§‡ (à¦®à¦¾à¦¨à§à¦· à¦šà¦¿à¦°à¦¾à¦šà¦°à¦¿à¦¤à¦­à¦¾à¦¬à§‡ à¦¯à§‡ à¦¸à¦®à¦¯à¦¼ à¦¸à¦¨à§à¦§à§à¦¯à¦¾ à¦¦à§‡à¦¯à¦¼) à¦¨à§‹à¦Ÿà¦¿à¦«à¦¿à¦•à§‡à¦¶à¦¨ à¦¯à¦¾à¦¬à§‡, à¦…à¦«
  /// à¦•à¦°à¦²à§‡ à¦¸à¦¬ à¦¬à¦¾à¦¤à¦¿à¦² à¦¹à¦¯à¦¼à§‡ à¦¯à¦¾à¦¬à§‡
  Future<void> saveEveningLampReminder(bool value) async {
    eveningLampReminder = value;
    final p = _prefs ??= await SharedPreferences.getInstance();
    await p.setBool(_kEveningLamp, value);
    if (value) {
      await NotificationService.instance.scheduleEveningLampReminders();
    } else {
      await NotificationService.instance.cancelEveningLampReminders();
    }
    notifyListeners();
  }

  /// Onboarding à¦¶à§‡à¦·à§‡ ("à¦¶à§à¦°à§ à¦•à¦°à§à¦¨" à¦¬à¦¾à¦Ÿà¦¨à§‡) à¦¡à¦¾à¦•à¦¾ à¦¹à¦¯à¦¼ â€” à¦à¦°à¦ªà¦° à¦¥à§‡à¦•à§‡ à¦…à§à¦¯à¦¾à¦ª à¦–à§à¦²à¦²à§‡à¦‡
  /// à¦¸à¦°à¦¾à¦¸à¦°à¦¿ à¦¹à§‹à¦® à¦¸à§à¦•à§à¦°à¦¿à¦¨à§‡ à¦¯à¦¾à¦¬à§‡, à¦­à¦¾à¦·à¦¾/à¦œà§‡à¦²à¦¾/à¦ªà¦¾à¦°à¦®à¦¿à¦¶à¦¨ à¦¸à§à¦•à§à¦°à¦¿à¦¨ à¦†à¦° à¦¦à§‡à¦–à¦¾à¦¬à§‡ à¦¨à¦¾
  Future<void> markSetupComplete() async {
    setupComplete = true;
    final p = _prefs ??= await SharedPreferences.getInstance();
    await p.setBool(_kSetupDone, true);
  }

  Future<void> save({
    String? lang,
    bool? weather,
    bool? skyAnim,
    bool? notifications,
  }) async {
    if (lang != null) this.lang = lang;
    if (weather != null) this.weather = weather;
    if (skyAnim != null) this.skyAnim = skyAnim;
    if (notifications != null) this.notifications = notifications;
    final p = _prefs ??= await SharedPreferences.getInstance();
    await p.setString(_kLang, this.lang);
    await p.setBool(_kWeather, this.weather);
    await p.setBool(_kSkyAnim, this.skyAnim);
    await p.setBool(_kNotif, this.notifications);
    // à¦¨à§‹à¦Ÿà¦¿à¦«à¦¿à¦•à§‡à¦¶à¦¨ à¦¬à¦¨à§à¦§ à¦•à¦°à¦²à§‡ à¦†à¦—à§‡ à¦¥à§‡à¦•à§‡ à¦¸à§‡à¦Ÿ à¦•à¦°à¦¾ à¦¸à¦¬ à¦°à¦¿à¦®à¦¾à¦‡à¦¨à§à¦¡à¦¾à¦°à¦“ à¦¬à¦¾à¦¤à¦¿à¦² à¦¹à¦¬à§‡
    if (!this.notifications) {
      await NotificationService.instance.cancelAll();
    } else {
      await ReminderStore.instance.rescheduleAll();
      if (eveningLampReminder) {
        await NotificationService.instance.scheduleEveningLampReminders();
      }
    }
    notifyListeners();
  }

  Future<void> saveDistrict(String district) async {
    AppLocation.select(district);
    final p = _prefs ??= await SharedPreferences.getInstance();
    await p.setString(_kDistrict, AppLocation.district);
    notifyListeners();
  }

  Future<void> saveProfile({
    required String name,
    required String city,
    DateTime? dob,
    String? address,
  }) async {
    profileName = name;
    profileCity = city;
    profileDob = dob;
    if (address != null) profileAddress = address;
    final p = _prefs ??= await SharedPreferences.getInstance();
    await p.setString(_kName, name);
    await p.setString(_kCity, city);
    if (address != null) await p.setString(_kAddress, address);
    if (dob != null) {
      await p.setInt(_kDob, dob.millisecondsSinceEpoch);
    } else {
      await p.remove(_kDob);
    }
    notifyListeners();
  }
}

/// à¦°à¦¿à¦®à¦¾à¦‡à¦¨à§à¦¡à¦¾à¦° â€” à¦«à§‹à¦¨à§‡ à¦¸à§‡à¦­ à¦¥à¦¾à¦•à§‡ à¦à¦¬à¦‚ à¦¨à¦¿à¦°à§à¦§à¦¾à¦°à¦¿à¦¤ à¦¸à¦®à¦¯à¦¼à§‡ à¦¨à§‹à¦Ÿà¦¿à¦«à¦¿à¦•à§‡à¦¶à¦¨ à¦¬à¦¾à¦œà§‡
class ReminderStore {
  ReminderStore._();
  static final ReminderStore instance = ReminderStore._();
  static const _key = 'reminders';

  final List<ReminderItem> items = [];

  Future<void> load() async {
    final p = await SharedPreferences.getInstance();
    final raw = p.getStringList(_key) ?? const [];
    items
      ..clear()
      ..addAll(
        raw.map((e) {
          final m = jsonDecode(e) as Map<String, dynamic>;
          return ReminderItem(
            m['text'] as String,
            DateTime.fromMillisecondsSinceEpoch(m['when'] as int),
            id: m['id'] as int,
          );
        }),
      );
    items.sort((a, b) => b.when.compareTo(a.when));
  }

  Future<void> _persist() async {
    final p = await SharedPreferences.getInstance();
    await p.setStringList(
      _key,
      items
          .map(
            (r) => jsonEncode({
              'id': r.id,
              'text': r.text,
              'when': r.when.millisecondsSinceEpoch,
            }),
          )
          .toList(),
    );
  }

  Future<void> add(ReminderItem item) async {
    items.insert(0, item);
    await _persist();
    if (AppSettings.instance.notifications) {
      await NotificationService.instance.schedule(item);
    }
  }

  Future<void> remove(ReminderItem item) async {
    items.remove(item);
    await _persist();
    await NotificationService.instance.cancel(item.id);
  }

  /// à¦¨à§‹à¦Ÿà¦¿à¦«à¦¿à¦•à§‡à¦¶à¦¨ à¦†à¦¬à¦¾à¦° à¦šà¦¾à¦²à§ à¦•à¦°à¦²à§‡ à¦­à¦¬à¦¿à¦·à§à¦¯à¦¤à§‡à¦° à¦¸à¦¬ à¦°à¦¿à¦®à¦¾à¦‡à¦¨à§à¦¡à¦¾à¦° à¦ªà§à¦¨à¦°à¦¾à¦¯à¦¼ à¦¸à§‡à¦Ÿ à¦¹à¦¯à¦¼
  Future<void> rescheduleAll() async {
    if (items.isEmpty) await load();
    for (final r in items) {
      if (r.when.isAfter(DateTime.now())) {
        await NotificationService.instance.schedule(r);
      }
    }
  }
}

/// à¦¨à§‹à¦Ÿà¦¸ â€” à¦«à§‹à¦¨à§‡ à¦¸à§‡à¦­ à¦¥à¦¾à¦•à§‡
class NotesStore {
  NotesStore._();
  static final NotesStore instance = NotesStore._();
  static const _key = 'notes';

  final List<String> items = [];

  Future<void> load() async {
    final p = await SharedPreferences.getInstance();
    items
      ..clear()
      ..addAll(p.getStringList(_key) ?? const []);
  }

  Future<void> _persist() async {
    final p = await SharedPreferences.getInstance();
    await p.setStringList(_key, items);
  }

  Future<void> add(String note) async {
    items.insert(0, note);
    await _persist();
  }

  Future<void> removeAt(int index) async {
    items.removeAt(index);
    await _persist();
  }
}

/// à¦¸à§à¦¥à¦¾à¦¨à§€à¦¯à¦¼ à¦®à¦¨à§à¦¦à¦¿à¦°/à¦ªà§‚à¦œà¦¾à¦° à¦¸à¦®à¦¯à¦¼à¦¸à§‚à¦šà¦¿ â€” à¦¬à§à¦¯à¦¬à¦¹à¦¾à¦°à¦•à¦¾à¦°à§€ à¦¨à¦¿à¦œà§‡ à¦¯à§‹à¦— à¦•à¦°à§‡à¦¨, à¦«à§‹à¦¨à§‡ à¦¸à§‡à¦­
/// à¦¥à¦¾à¦•à§‡ à¦à¦¬à¦‚ à¦šà¦¾à¦‡à¦²à§‡ à¦¨à¦¿à¦°à§à¦§à¦¾à¦°à¦¿à¦¤ à¦¸à¦®à¦¯à¦¼à§‡ à¦¨à§‹à¦Ÿà¦¿à¦«à¦¿à¦•à§‡à¦¶à¦¨ à¦°à¦¿à¦®à¦¾à¦‡à¦¨à§à¦¡à¦¾à¦°à¦“ à¦¸à§‡à¦Ÿ à¦¹à¦¯à¦¼
class TempleEvent {
  String temple; // à¦®à¦¨à§à¦¦à¦¿à¦°/à¦¸à§à¦¥à¦¾à¦¨à§‡à¦° à¦¨à¦¾à¦®
  String pujaName; // à¦ªà§‚à¦œà¦¾à¦° à¦¨à¦¾à¦®
  DateTime when;
  bool reminderOn;
  final int id;
  TempleEvent({
    required this.temple,
    required this.pujaName,
    required this.when,
    this.reminderOn = true,
    int? id,
  }) : id = id ?? DateTime.now().microsecondsSinceEpoch.remainder(0x7FFFFFFF);
}

class TempleStore {
  TempleStore._();
  static final TempleStore instance = TempleStore._();
  static const _key = 'temple_events';

  final List<TempleEvent> items = [];

  Future<void> load() async {
    final p = await SharedPreferences.getInstance();
    final raw = p.getStringList(_key) ?? const [];
    items
      ..clear()
      ..addAll(
        raw.map((e) {
          final m = jsonDecode(e) as Map<String, dynamic>;
          return TempleEvent(
            temple: m['temple'] as String,
            pujaName: m['pujaName'] as String,
            when: DateTime.fromMillisecondsSinceEpoch(m['when'] as int),
            reminderOn: (m['reminderOn'] as bool?) ?? true,
            id: m['id'] as int,
          );
        }),
      );
    items.sort((a, b) => a.when.compareTo(b.when));
  }

  Future<void> _persist() async {
    final p = await SharedPreferences.getInstance();
    await p.setStringList(
      _key,
      items
          .map(
            (e) => jsonEncode({
              'id': e.id,
              'temple': e.temple,
              'pujaName': e.pujaName,
              'when': e.when.millisecondsSinceEpoch,
              'reminderOn': e.reminderOn,
            }),
          )
          .toList(),
    );
  }

  Future<void> add(TempleEvent event) async {
    items.add(event);
    items.sort((a, b) => a.when.compareTo(b.when));
    await _persist();
    if (event.reminderOn) {
      await NotificationService.instance.scheduleGeneric(
        event.id,
        'ðŸ›• ${event.temple}',
        '${event.pujaName} â€” à¦†à¦œ',
        event.when.subtract(const Duration(hours: 1)),
      );
    }
  }

  Future<void> remove(TempleEvent event) async {
    items.remove(event);
    await _persist();
    await NotificationService.instance.cancel(event.id);
  }
}

/// à¦¸à¦¤à§à¦¯à¦¿à¦•à¦¾à¦°à§‡à¦° à¦²à§‹à¦•à¦¾à¦² à¦¨à§‹à¦Ÿà¦¿à¦«à¦¿à¦•à§‡à¦¶à¦¨ â€” à¦¨à¦¿à¦°à§à¦§à¦¾à¦°à¦¿à¦¤ à¦¸à¦®à¦¯à¦¼à§‡ à¦«à§‹à¦¨à§‡ à¦…à§à¦¯à¦¾à¦²à¦¾à¦°à§à¦Ÿ à¦†à¦¸à¦¬à§‡
class NotificationService {
  NotificationService._();
  static final NotificationService instance = NotificationService._();

  final FlutterLocalNotificationsPlugin _plugin =
      FlutterLocalNotificationsPlugin();
  bool _ready = false;

  static const AndroidNotificationDetails
  _androidDetails = AndroidNotificationDetails(
    'panjika_reminders',
    'à¦ªà¦žà§à¦œà¦¿à¦•à¦¾ à¦°à¦¿à¦®à¦¾à¦‡à¦¨à§à¦¡à¦¾à¦°',
    channelDescription:
        'à¦†à¦ªà¦¨à¦¾à¦° à¦¸à§‡à¦Ÿ à¦•à¦°à¦¾ à¦°à¦¿à¦®à¦¾à¦‡à¦¨à§à¦¡à¦¾à¦°à§‡à¦° à¦¨à§‹à¦Ÿà¦¿à¦«à¦¿à¦•à§‡à¦¶à¦¨',
    importance: Importance.max,
    priority: Priority.high,
  );

  Future<void> init() async {
    if (_ready) return;
    // à¦“à¦¯à¦¼à§‡à¦¬ à¦­à¦¾à¦°à§à¦¸à¦¨à§‡ local notification à¦ªà§à¦²à¦¾à¦—à¦‡à¦¨à¦Ÿà¦¾ à¦•à¦¾à¦œ à¦•à¦°à§‡ à¦¨à¦¾ (à¦•à§‹à¦¨à§‹ à¦¬à§à¦°à¦¾à¦‰à¦œà¦¾à¦°
    // à¦‡à¦®à¦ªà§à¦²à¦¿à¦®à§‡à¦¨à§à¦Ÿà§‡à¦¶à¦¨ à¦¨à§‡à¦‡) â€” à¦šà§‡à¦·à§à¦Ÿà¦¾ à¦•à¦°à¦²à§‡ à¦…à§à¦¯à¦¾à¦ªà¦Ÿà¦¾à¦‡ à¦•à§à¦°à§à¦¯à¦¾à¦¶ à¦•à¦°à¦¤à¥¤ à¦¤à¦¾à¦‡ à¦“à¦¯à¦¼à§‡à¦¬à§‡
    // à¦à¦‡ à¦«à¦¿à¦šà¦¾à¦°à¦Ÿà¦¾ à¦šà§à¦ªà¦šà¦¾à¦ª à¦¬à¦¾à¦¦ à¦¦à§‡à¦“à¦¯à¦¼à¦¾ à¦¹à¦šà§à¦›à§‡, à¦¬à¦¾à¦•à¦¿ à¦¸à¦¬ à¦«à¦¿à¦šà¦¾à¦° à¦¸à§à¦¬à¦¾à¦­à¦¾à¦¬à¦¿à¦• à¦šà¦²à¦¬à§‡à¥¤
    if (kIsWeb) {
      _ready = true;
      return;
    }
    tzdata.initializeTimeZones();
    tz.setLocalLocation(tz.getLocation('Asia/Kolkata'));

    const settings = InitializationSettings(
      android: AndroidInitializationSettings('@mipmap/ic_launcher'),
      iOS: DarwinInitializationSettings(),
    );
    await _plugin.initialize(settings);

    // Android 13+ à¦ à¦¨à§‹à¦Ÿà¦¿à¦«à¦¿à¦•à§‡à¦¶à¦¨à§‡à¦° à¦…à¦¨à§à¦®à¦¤à¦¿ à¦šà¦¾à¦‡à¦¤à§‡ à¦¹à¦¯à¦¼
    final android = _plugin
        .resolvePlatformSpecificImplementation<
          AndroidFlutterLocalNotificationsPlugin
        >();
    await android?.requestNotificationsPermission();

    _ready = true;
  }

  Future<void> schedule(ReminderItem item) async {
    await init();
    if (kIsWeb) return;
    if (!item.when.isAfter(DateTime.now())) return;
    await _plugin.zonedSchedule(
      item.id,
      'à¦ªà¦žà§à¦œà¦¿à¦•à¦¾ à¦°à¦¿à¦®à¦¾à¦‡à¦¨à§à¦¡à¦¾à¦°',
      item.text,
      tz.TZDateTime.from(item.when, tz.local),
      const NotificationDetails(
        android: _androidDetails,
        iOS: DarwinNotificationDetails(),
      ),
      androidScheduleMode: AndroidScheduleMode.inexactAllowWhileIdle,
      // iOS-à¦ à¦¸à¦®à¦¯à¦¼à¦Ÿà¦¾ à¦ à¦¿à¦• à¦“à¦‡ à¦®à§à¦¹à§‚à¦°à§à¦¤ à¦¹à¦¿à¦¸à§‡à¦¬à§‡à¦‡ à¦§à¦°à¦¾ à¦¹à¦¬à§‡ (à¦Ÿà¦¾à¦‡à¦®à¦œà§‹à¦¨ à¦…à¦¨à§à¦¯à¦¾à¦¯à¦¼à§€ à¦¨à¦¯à¦¼)
      uiLocalNotificationDateInterpretation:
