  }

  Future<void> cancel(int id) async {
    await init();
    if (kIsWeb) return;
    await _plugin.cancel(id);
  }

  Future<void> cancelAll() async {
    await init();
    if (kIsWeb) return;
    await _plugin.cancelAll();
  }

  // "à¦¸à¦¨à§à¦§à§à¦¯à¦¾ à¦ªà§à¦°à¦¦à§€à¦ª" à¦°à¦¿à¦®à¦¾à¦‡à¦¨à§à¦¡à¦¾à¦°à§‡à¦° à¦œà¦¨à§à¦¯ à¦†à¦²à¦¾à¦¦à¦¾ reserved id à¦°à§‡à¦žà§à¦œ, à¦¯à¦¾à¦¤à§‡
  // à¦¬à§à¦¯à¦¬à¦¹à¦¾à¦°à¦•à¦¾à¦°à§€à¦° à¦¹à¦¾à¦¤à§‡-à¦¬à¦¸à¦¾à¦¨à§‹ à¦°à¦¿à¦®à¦¾à¦‡à¦¨à§à¦¡à¦¾à¦°à§‡à¦° id-à¦° à¦¸à¦¾à¦¥à§‡ à¦•à¦–à¦¨à§‹ à¦¸à¦‚à¦˜à¦°à§à¦· à¦¨à¦¾ à¦¹à¦¯à¦¼
  static const int _eveningLampBaseId = 900000;
  static const int _eveningLampDays = 30;

  /// à¦ªà§à¦°à¦¤à¦¿à¦¦à¦¿à¦¨ real à¦¸à§‚à¦°à§à¦¯à¦¾à¦¸à§à¦¤à§‡à¦° à¦¸à¦®à¦¯à¦¼ à¦…à¦¨à§à¦¯à¦¾à¦¯à¦¼à§€ (à¦®à¦¾à¦¨à§à¦· à¦šà¦¿à¦°à¦¾à¦šà¦°à¦¿à¦¤à¦­à¦¾à¦¬à§‡ à¦¯à§‡ à¦¸à¦®à¦¯à¦¼
  /// à¦¸à¦¨à§à¦§à§à¦¯à¦¾ à¦ªà§à¦°à¦¦à§€à¦ª à¦œà§à¦¬à¦¾à¦²à¦¾à¦¯à¦¼) à¦†à¦—à¦¾à¦®à§€ à§©à§¦ à¦¦à¦¿à¦¨à§‡à¦° à¦¨à§‹à¦Ÿà¦¿à¦«à¦¿à¦•à§‡à¦¶à¦¨ à¦¶à¦¿à¦¡à¦¿à¦‰à¦² à¦•à¦°à§‡à¥¤ à¦ªà§à¦°à¦¤à¦¿à¦¦à¦¿à¦¨
  /// à¦¸à§‚à¦°à§à¦¯à¦¾à¦¸à§à¦¤à§‡à¦° à¦ªà§à¦°à¦•à§ƒà¦¤ à¦¸à¦®à¦¯à¦¼ à¦†à¦²à¦¾à¦¦à¦¾ à¦¹à¦¯à¦¼ à¦¬à¦²à§‡ à¦•à§‹à¦¨à§‹ à¦«à¦¿à¦•à§à¦¸à¦¡ à¦˜à¦¡à¦¼à¦¿à¦° à¦¸à¦®à¦¯à¦¼ à¦¨à¦¯à¦¼ â€”
  /// à¦ªà§à¦°à¦¤à¦¿à¦Ÿà¦¾ à¦¦à¦¿à¦¨à§‡à¦° à¦œà¦¨à§à¦¯ à¦†à¦²à¦¾à¦¦à¦¾à¦­à¦¾à¦¬à§‡ à¦œà§à¦¯à§‹à¦¤à¦¿à¦°à§à¦¬à¦¿à¦¦à§à¦¯à¦¾ à¦¹à¦¿à¦¸à§‡à¦¬ à¦¥à§‡à¦•à§‡ à¦¬à§‡à¦° à¦•à¦°à¦¾ à¦¹à¦¯à¦¼
  /// (à¦¬à§à¦¯à¦¬à¦¹à¦¾à¦°à¦•à¦¾à¦°à§€à¦° à¦¬à§‡à¦›à§‡ à¦¨à§‡à¦“à¦¯à¦¼à¦¾/GPS à¦²à§‹à¦•à§‡à¦¶à¦¨ à¦…à¦¨à§à¦¯à¦¾à¦¯à¦¼à§€)à¥¤
  Future<void> scheduleEveningLampReminders() async {
    await init();
    if (kIsWeb) return;
    await cancelEveningLampReminders();
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    for (int i = 0; i < _eveningLampDays; i++) {
      final day = today.add(Duration(days: i));
      DateTime sunset;
      try {
        sunset = PanchangCalculator.sunTimes(
          day,
          lat: AppLocation.lat,
          lon: AppLocation.lon,
        ).sunset;
      } catch (_) {
        continue;
      }
      if (!sunset.isAfter(now)) continue;
      await _plugin.zonedSchedule(
        _eveningLampBaseId + i,
        'ðŸª” à¦¸à¦¨à§à¦§à§à¦¯à¦¾ à¦ªà§à¦°à¦¦à§€à¦ª',
        'à¦¸à¦¨à§à¦§à§à¦¯à¦¾ à¦¨à§‡à¦®à§‡ à¦à¦¸à§‡à¦›à§‡ â€” à¦ªà§à¦°à¦¦à§€à¦ª à¦œà§à¦¬à¦¾à¦²à¦¾à¦¨à§‹à¦° à¦¸à¦®à¦¯à¦¼ à¦¹à¦¯à¦¼à§‡à¦›à§‡',
        tz.TZDateTime.from(sunset, tz.local),
        const NotificationDetails(
          android: _androidDetails,
          iOS: DarwinNotificationDetails(),
        ),
        androidScheduleMode: AndroidScheduleMode.inexactAllowWhileIdle,
        uiLocalNotificationDateInterpretation:
            UILocalNotificationDateInterpretation.absoluteTime,
      );
    }
  }

  /// à¦®à¦¨à§à¦¦à¦¿à¦°/à¦ªà§‚à¦œà¦¾à¦° à¦¸à¦®à¦¯à¦¼à¦¸à§‚à¦šà¦¿à¦° à¦®à¦¤à§‹ à¦•à¦¾à¦¸à§à¦Ÿà¦® à¦Ÿà¦¾à¦‡à¦Ÿà§‡à¦²-à¦¸à¦¹ à¦¨à§‹à¦Ÿà¦¿à¦«à¦¿à¦•à§‡à¦¶à¦¨à§‡à¦° à¦œà¦¨à§à¦¯ â€”
  /// à¦°à¦¿à¦®à¦¾à¦‡à¦¨à§à¦¡à¦¾à¦°à§‡à¦° à¦®à¦¤à§‹ à¦à¦•à¦‡ à¦¸à¦¾à¦§à¦¾à¦°à¦£ à¦®à§‡à¦•à¦¾à¦¨à¦¿à¦œà¦®, à¦¶à§à¦§à§ à¦¨à¦¿à¦œà¦¸à§à¦¬ à¦¶à¦¿à¦°à§‹à¦¨à¦¾à¦® à¦¦à§‡à¦“à¦¯à¦¼à¦¾ à¦¯à¦¾à¦¯à¦¼
  Future<void> scheduleGeneric(
    int id,
    String title,
    String body,
    DateTime when,
  ) async {
    await init();
    if (kIsWeb) return;
    if (!when.isAfter(DateTime.now())) return;
    await _plugin.zonedSchedule(
      id,
      title,
      body,
      tz.TZDateTime.from(when, tz.local),
      const NotificationDetails(
        android: _androidDetails,
        iOS: DarwinNotificationDetails(),
      ),
      androidScheduleMode: AndroidScheduleMode.inexactAllowWhileIdle,
      uiLocalNotificationDateInterpretation:
          UILocalNotificationDateInterpretation.absoluteTime,
    );
  }

  Future<void> cancelEveningLampReminders() async {
    await init();
    if (kIsWeb) return;
    for (int i = 0; i < _eveningLampDays; i++) {
      await _plugin.cancel(_eveningLampBaseId + i);
    }
  }
}

