// =====================================================================

class TtsService {
  TtsService._();
  static final TtsService instance = TtsService._();

  final FlutterTts _tts = FlutterTts();
  bool _ready = false;
  bool isSpeaking = false;

  Future<void> _ensureReady() async {
    if (_ready) return;
    try {
      // à¦¬à¦¾à¦‚à¦²à¦¾ à¦­à¦¯à¦¼à§‡à¦¸ à¦¨à¦¾ à¦¥à¦¾à¦•à¦²à§‡ à¦¡à¦¿à¦­à¦¾à¦‡à¦¸ à¦¸à§à¦¬à¦¯à¦¼à¦‚à¦•à§à¦°à¦¿à¦¯à¦¼à¦­à¦¾à¦¬à§‡ à¦•à¦¾à¦›à¦¾à¦•à¦¾à¦›à¦¿ à¦à¦•à¦Ÿà¦¾ à¦­à¦¾à¦·à¦¾
      // à¦¬à§‡à¦›à§‡ à¦¨à§‡à¦¯à¦¼ (à¦¯à§‡à¦®à¦¨ à¦¹à¦¿à¦¨à§à¦¦à¦¿/à¦‡à¦‚à¦°à§‡à¦œà¦¿ à¦‰à¦šà§à¦šà¦¾à¦°à¦£à§‡ à¦¬à¦¾à¦‚à¦²à¦¾ à¦²à§‡à¦–à¦¾ à¦ªà¦¡à¦¼à¦¾)
      await _tts.setLanguage('bn-BD');
      await _tts.setSpeechRate(0.42);
      await _tts.setPitch(1.0);
      await _tts.setVolume(1.0);
    } catch (_) {
      // à¦­à¦¾à¦·à¦¾ à¦¸à§‡à¦Ÿ à¦¨à¦¾ à¦¹à¦²à§‡à¦“ à¦¡à¦¿à¦«à¦²à§à¦Ÿ à¦­à¦¯à¦¼à§‡à¦¸ à¦¦à¦¿à¦¯à¦¼à§‡ à¦ªà¦¡à¦¼à¦¾à¦° à¦šà§‡à¦·à§à¦Ÿà¦¾ à¦šà¦²à¦¬à§‡
    }
    _ready = true;
  }

  Future<void> speak(String text) async {
    await _ensureReady();
    isSpeaking = true;
    try {
      // à¦“à¦¯à¦¼à§‡à¦¬à§‡ à¦¬à§à¦°à¦¾à¦‰à¦œà¦¾à¦°à§‡à¦° à¦¨à¦¿à¦œà¦¸à§à¦¬ Web Speech API à¦¬à§à¦¯à¦¬à¦¹à¦¾à¦° à¦¹à¦¯à¦¼ â€” à¦¸à¦¬ à¦¬à§à¦°à¦¾à¦‰à¦œà¦¾à¦°à§‡
      // à¦¬à¦¾à¦‚à¦²à¦¾ à¦­à¦¯à¦¼à§‡à¦¸ à¦¨à¦¾-à¦“ à¦¥à¦¾à¦•à¦¤à§‡ à¦ªà¦¾à¦°à§‡, à¦¤à¦–à¦¨ à¦¬à§à¦°à¦¾à¦‰à¦œà¦¾à¦° à¦¯à¦¾ à¦ªà¦¾à¦¯à¦¼ à¦¸à§‡à¦‡ à¦­à¦¯à¦¼à§‡à¦¸ à¦¦à¦¿à¦¯à¦¼à§‡à¦‡
      // à¦ªà¦¡à¦¼à¦¾à¦° à¦šà§‡à¦·à§à¦Ÿà¦¾ à¦•à¦°à§‡, à¦à¦•à¦¦à¦® à¦šà§à¦ª à¦¥à¦¾à¦•à§‡ à¦¨à¦¾
      await _tts.speak(text);
    } catch (_) {
      isSpeaking = false;
    }
  }

  Future<void> stop() async {
    isSpeaking = false;
    try {
      await _tts.stop();
    } catch (_) {}
  }
}

