class AdService {
  AdService._();
  static final AdService instance = AdService._();
  bool _initialized = false;

  // à¦à¦—à§à¦²à§‹ Google-à¦à¦° à¦…à¦«à¦¿à¦¸à¦¿à¦¯à¦¼à¦¾à¦² à¦Ÿà§‡à¦¸à§à¦Ÿ Ad Unit ID â€” à¦¸à¦¬à¦¸à¦®à¦¯à¦¼ à¦¨à¦¿à¦°à¦¾à¦ªà¦¦à§‡ à¦Ÿà§‡à¦¸à§à¦Ÿ
  // à¦¬à¦¿à¦œà§à¦žà¦¾à¦ªà¦¨ à¦¦à§‡à¦–à¦¾à¦¬à§‡, à¦•à§‹à¦¨à§‹ à¦Ÿà¦¾à¦•à¦¾ à¦¤à§ˆà¦°à¦¿ à¦•à¦°à§‡ à¦¨à¦¾à¥¤ à¦¨à¦¿à¦œà§‡à¦° AdMob à¦à¦•à¦¾à¦‰à¦¨à§à¦Ÿ à¦¥à§‡à¦•à§‡ à¦†à¦¸à¦²
  // ID à¦¬à¦¸à¦¾à¦²à§‡ à¦¤à¦–à¦¨ à¦¥à§‡à¦•à§‡ à¦†à¦¸à¦² à¦¬à¦¿à¦œà§à¦žà¦¾à¦ªà¦¨ à¦“ à¦†à¦¸à¦² à¦†à¦¯à¦¼ à¦¶à§à¦°à§ à¦¹à¦¬à§‡ (README.md à¦¦à§‡à¦–à§à¦¨)
  static const String bannerAdUnitId = 'ca-app-pub-3940256099942544/6300978111';
  static const String interstitialAdUnitId =
      'ca-app-pub-3940256099942544/1033173712';

  Future<void> init() async {
    if (_initialized || kIsWeb) return;
    try {
      await MobileAds.instance.initialize();
      _initialized = true;
    } catch (_) {
      // à¦¬à¦¿à¦œà§à¦žà¦¾à¦ªà¦¨ SDK à¦¶à§à¦°à§ à¦¨à¦¾ à¦¹à¦²à§‡à¦“ à¦¬à¦¾à¦•à¦¿ à¦…à§à¦¯à¦¾à¦ª à¦¸à§à¦¬à¦¾à¦­à¦¾à¦¬à¦¿à¦• à¦šà¦²à¦¬à§‡
    }
  }

  /// à¦ªà§à¦°à¦¿à¦®à¦¿à¦¯à¦¼à¦¾à¦® à¦‡à¦‰à¦œà¦¾à¦° à¦¬à¦¾ à¦“à¦¯à¦¼à§‡à¦¬à§‡ à¦¬à¦¿à¦œà§à¦žà¦¾à¦ªà¦¨ à¦¦à§‡à¦–à¦¾à¦¨à§‹ à¦¹à¦¯à¦¼ à¦¨à¦¾
  bool get shouldShowAds => !kIsWeb && !AppSettings.instance.isPremium;
}

/// à¦¹à§‹à¦® à¦¸à§à¦•à§à¦°à¦¿à¦¨à§‡ à¦¦à§‡à¦–à¦¾à¦¨à§‹à¦° à¦œà¦¨à§à¦¯ à¦¬à§à¦¯à¦¾à¦¨à¦¾à¦° à¦¬à¦¿à¦œà§à¦žà¦¾à¦ªà¦¨ â€” à¦²à§‹à¦¡ à¦¨à¦¾ à¦¹à¦²à§‡ à¦¬à¦¾ à¦ªà§à¦°à¦¿à¦®à¦¿à¦¯à¦¼à¦¾à¦®
/// à¦¥à¦¾à¦•à¦²à§‡ à¦•à¦¿à¦›à§à¦‡ à¦¦à§‡à¦–à¦¾à¦¯à¦¼ à¦¨à¦¾, à¦•à§‹à¦¨à§‹ à¦œà¦¾à¦¯à¦¼à¦—à¦¾ à¦¨à§‡à¦¯à¦¼ à¦¨à¦¾
class AdBannerWidget extends StatefulWidget {
  const AdBannerWidget({super.key});
  @override
  State<AdBannerWidget> createState() => _AdBannerWidgetState();
}

class _AdBannerWidgetState extends State<AdBannerWidget> {
  BannerAd? _banner;
  bool _loaded = false;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    if (!AdService.instance.shouldShowAds) return;
    await AdService.instance.init();
    if (!mounted || kIsWeb) return;
    final ad = BannerAd(
      adUnitId: AdService.bannerAdUnitId,
      size: AdSize.banner,
      request: const AdRequest(),
      listener: BannerAdListener(
        onAdLoaded: (_) {
          if (mounted) setState(() => _loaded = true);
        },
        onAdFailedToLoad: (ad, error) => ad.dispose(),
      ),
    );
    _banner = ad;
    await ad.load();
  }

  @override
  void dispose() {
    _banner?.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (!AdService.instance.shouldShowAds || !_loaded || _banner == null) {
      return const SizedBox.shrink();
    }
    return Container(
      alignment: Alignment.center,
      width: _banner!.size.width.toDouble(),
      height: _banner!.size.height.toDouble(),
      margin: const EdgeInsets.symmetric(vertical: 4),
      child: AdWidget(ad: _banner!),
    );
  }
}

