/// à¦•à§à¦²à¦¾à¦‰à¦¡ à¦¬à§à¦¯à¦¾à¦•à¦†à¦ª â€” à¦°à¦¿à¦®à¦¾à¦‡à¦¨à§à¦¡à¦¾à¦° à¦“ à¦¨à§‹à¦Ÿà¦¸ à¦¨à¦¿à¦œà¦¸à§à¦¬ Laravel + MySQL backend-à¦
/// à¦¸à§‡à¦­ à¦°à¦¾à¦–à§‡ (à¦•à§‹à¦¨à§‹ Firebase/à¦¥à¦¾à¦°à§à¦¡-à¦ªà¦¾à¦°à§à¦Ÿà¦¿ à¦à¦•à¦¾à¦‰à¦¨à§à¦Ÿ à¦²à¦¾à¦—à§‡ à¦¨à¦¾, backend à¦šà¦¾à¦²à§
/// à¦¥à¦¾à¦•à¦²à§‡à¦‡ à¦•à¦¾à¦œ à¦•à¦°à¦¬à§‡)à¥¤
class CloudBackupService {
  CloudBackupService._();
  static final CloudBackupService instance = CloudBackupService._();

  /// null à¦®à¦¾à¦¨à§‡ à¦¸à¦«à¦² à¦¹à¦¯à¦¼à§‡à¦›à§‡, à¦¨à¦¾à¦¹à¦²à§‡ à¦¦à§‡à¦–à¦¾à¦¨à§‹à¦° à¦œà¦¨à§à¦¯ à¦à¦°à¦° à¦®à§‡à¦¸à§‡à¦œ à¦«à§‡à¦°à¦¤ à¦¦à§‡à¦¯à¦¼
  Future<String?> backupNow() async {
    try {
      final deviceId = AppSettings.instance.deviceId;
      final res = await http
          .post(
            Uri.parse('${BackendConfig.baseUrl}/api/backup'),
            headers: {'Content-Type': 'application/json'},
            body: jsonEncode({
              'device_id': deviceId,
              'data': {
                'reminders': ReminderStore.instance.items
                    .map(
                      (r) => {
                        'id': r.id,
                        'text': r.text,
                        'when': r.when.millisecondsSinceEpoch,
                      },
                    )
                    .toList(),
                'notes': NotesStore.instance.items,
              },
            }),
          )
          .timeout(const Duration(seconds: 15));
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      if (res.statusCode != 200 || data['success'] != true) {
        return data['message']?.toString() ??
            'à¦¬à§à¦¯à¦¾à¦•à¦†à¦ª à¦¬à§à¦¯à¦°à§à¦¥ à¦¹à¦¯à¦¼à§‡à¦›à§‡';
      }
      final p = await SharedPreferences.getInstance();
      await p.setInt(
        'last_cloud_backup',
        DateTime.now().millisecondsSinceEpoch,
      );
      return null;
    } catch (e) {
      return 'à¦¬à§à¦¯à¦¾à¦•à¦†à¦ª à¦¸à¦¾à¦°à§à¦­à¦¾à¦°à§‡à¦° à¦¸à¦¾à¦¥à§‡ à¦¯à§‹à¦—à¦¾à¦¯à§‹à¦— à¦•à¦°à¦¾ à¦¯à¦¾à¦¯à¦¼à¦¨à¦¿ â€” à¦‡à¦¨à§à¦Ÿà¦¾à¦°à¦¨à§‡à¦Ÿ/à¦¸à¦¾à¦°à§à¦­à¦¾à¦° à¦šà§‡à¦• à¦•à¦°à§à¦¨';
    }
  }

  Future<String?> restoreNow() async {
    try {
      final deviceId = AppSettings.instance.deviceId;
      final res = await http
          .get(Uri.parse('${BackendConfig.baseUrl}/api/backup/$deviceId'))
          .timeout(const Duration(seconds: 15));
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      if (res.statusCode != 200 || data['success'] != true) {
        return data['message']?.toString() ??
            'à¦•à§‹à¦¨à§‹ à¦¬à§à¦¯à¦¾à¦•à¦†à¦ª à¦ªà¦¾à¦“à¦¯à¦¼à¦¾ à¦¯à¦¾à¦¯à¦¼à¦¨à¦¿';
      }
      final backupData = data['data'] as Map<String, dynamic>;
      final remindersRaw = (backupData['reminders'] as List?) ?? const [];
      ReminderStore.instance.items
        ..clear()
        ..addAll(
          remindersRaw.map(
            (m) => ReminderItem(
              m['text'] as String,
              DateTime.fromMillisecondsSinceEpoch(m['when'] as int),
              id: m['id'] as int,
            ),
          ),
        );
      await ReminderStore.instance._persist();
      final notesRaw = ((backupData['notes'] as List?) ?? const [])
          .cast<String>();
      NotesStore.instance.items
        ..clear()
        ..addAll(notesRaw);
      await NotesStore.instance._persist();
      return null;
    } catch (e) {
      return 'à¦¬à§à¦¯à¦¾à¦•à¦†à¦ª à¦¸à¦¾à¦°à§à¦­à¦¾à¦°à§‡à¦° à¦¸à¦¾à¦¥à§‡ à¦¯à§‹à¦—à¦¾à¦¯à§‹à¦— à¦•à¦°à¦¾ à¦¯à¦¾à¦¯à¦¼à¦¨à¦¿ â€” à¦‡à¦¨à§à¦Ÿà¦¾à¦°à¦¨à§‡à¦Ÿ/à¦¸à¦¾à¦°à§à¦­à¦¾à¦° à¦šà§‡à¦• à¦•à¦°à§à¦¨';
    }
  }

  Future<DateTime?> lastBackupAt() async {
    final p = await SharedPreferences.getInstance();
    final ms = p.getInt('last_cloud_backup');
    return ms == null ? null : DateTime.fromMillisecondsSinceEpoch(ms);
  }
}

