/// Laravel backend-à¦à¦° à¦¸à¦¾à¦¥à§‡ à¦ªà§‡à¦®à§‡à¦¨à§à¦Ÿ flow-à¦à¦° à¦¨à§‡à¦Ÿà¦“à¦¯à¦¼à¦¾à¦°à§à¦• à¦•à¦² â€” à¦…à¦°à§à¦¡à¦¾à¦° à¦¤à§ˆà¦°à¦¿,
/// à¦­à§‡à¦°à¦¿à¦«à¦¾à¦‡ à¦“ à¦¸à§à¦Ÿà§à¦¯à¦¾à¦Ÿà¦¾à¦¸ à¦šà§‡à¦•à¥¤ backend à¦à¦–à¦¨à§‹ à¦¹à§‹à¦¸à§à¦Ÿ à¦¨à¦¾ à¦¹à¦²à§‡ [baseUrl] à¦–à¦¾à¦²à¦¿
/// à¦¥à¦¾à¦•à¦¬à§‡ à¦à¦¬à¦‚ à¦ªà§à¦°à¦¤à¦¿à¦Ÿà¦¾ à¦•à¦² à¦¸à§à¦ªà¦·à§à¦Ÿ à¦à¦°à¦° à¦®à§‡à¦¸à§‡à¦œ à¦¦à§‡à¦¬à§‡ (à¦¨à§€à¦°à¦¬à§‡ à¦•à§à¦°à§à¦¯à¦¾à¦¶ à¦•à¦°à¦¬à§‡ à¦¨à¦¾)à¥¤
class PaymentService {
  PaymentService._();
  static final PaymentService instance = PaymentService._();

  static String get baseUrl => BackendConfig.baseUrl;

  bool get isConfigured => baseUrl.isNotEmpty;

  Future<Map<String, dynamic>> createOrder(String plan) async {
    if (!isConfigured) {
      throw Exception(
        'Backend à¦à¦–à¦¨à§‹ à¦¸à§‡à¦Ÿ à¦•à¦°à¦¾ à¦¹à¦¯à¦¼à¦¨à¦¿ â€” PaymentService.baseUrl à¦ à¦†à¦ªà¦¨à¦¾à¦° '
        'Laravel à¦¸à¦¾à¦°à§à¦­à¦¾à¦°à§‡à¦° URL à¦¬à¦¸à¦¾à¦¨',
      );
    }
    final res = await http
        .post(
          Uri.parse('$baseUrl/api/payment/create-order'),
          headers: {'Content-Type': 'application/json'},
          body: jsonEncode({
            'device_id': AppSettings.instance.deviceId,
            'plan': plan,
          }),
        )
        .timeout(const Duration(seconds: 15));
    final data = jsonDecode(res.body) as Map<String, dynamic>;
    if (res.statusCode != 200 || data['success'] != true) {
      throw Exception(
        data['message']?.toString() ??
            'à¦…à¦°à§à¦¡à¦¾à¦° à¦¤à§ˆà¦°à¦¿ à¦¬à§à¦¯à¦°à§à¦¥ à¦¹à¦¯à¦¼à§‡à¦›à§‡',
      );
    }
    return data;
  }

  Future<DateTime> verify({
    required String orderId,
    required String paymentId,
    required String signature,
  }) async {
    final res = await http
        .post(
          Uri.parse('$baseUrl/api/payment/verify'),
          headers: {'Content-Type': 'application/json'},
          body: jsonEncode({
            'device_id': AppSettings.instance.deviceId,
            'razorpay_order_id': orderId,
            'razorpay_payment_id': paymentId,
            'razorpay_signature': signature,
          }),
        )
        .timeout(const Duration(seconds: 15));
    final data = jsonDecode(res.body) as Map<String, dynamic>;
    if (res.statusCode != 200 || data['success'] != true) {
      throw Exception(
        data['message']?.toString() ??
            'à¦¯à¦¾à¦šà¦¾à¦‡ à¦¬à§à¦¯à¦°à§à¦¥ à¦¹à¦¯à¦¼à§‡à¦›à§‡',
      );
    }
    return DateTime.parse(data['expires_at'].toString());
  }

  Future<void> refreshStatus() async {
    if (!isConfigured || AppSettings.instance.deviceId.isEmpty) return;
    try {
      final res = await http
          .get(
            Uri.parse(
              '$baseUrl/api/subscription/status?device_id=${AppSettings.instance.deviceId}',
            ),
          )
          .timeout(const Duration(seconds: 10));
      if (res.statusCode != 200) return;
      final data = jsonDecode(res.body) as Map<String, dynamic>;
      if (data['success'] != true) return;
      await AppSettings.instance.applyPremiumStatus(
        active: data['is_premium'] == true,
        expiresAt: data['expires_at'] != null
            ? DateTime.tryParse(data['expires_at'].toString())
            : null,
      );
    } catch (_) {
      // à¦¨à§‡à¦Ÿà¦“à¦¯à¦¼à¦¾à¦°à§à¦• à¦¨à¦¾ à¦¥à¦¾à¦•à¦²à§‡ à¦¯à¦¾ à¦²à§‹à¦•à¦¾à¦²à¦¿ à¦¸à§‡à¦­ à¦†à¦›à§‡ à¦¤à¦¾à¦‡ à¦¬à§à¦¯à¦¬à¦¹à¦¾à¦° à¦¹à¦¬à§‡
    }
  }
}

class BanglaPanjikaApp extends StatelessWidget {
  const BanglaPanjikaApp({super.key});

  @override
  Widget build(BuildContext context) {
    // à¦¸à§‡à¦Ÿà¦¿à¦‚à¦¸ à¦¬à¦¦à¦²à¦¾à¦²à§‡ (à¦¯à§‡à¦®à¦¨ à¦­à¦¾à¦·à¦¾) à¦ªà§à¦°à§‹ à¦…à§à¦¯à¦¾à¦ª à¦¨à¦¤à§à¦¨ à¦•à¦°à§‡ à¦†à¦à¦•à¦¾ à¦¹à¦¯à¦¼
    return AnimatedBuilder(
      animation: AppSettings.instance,
      builder: (context, _) => MaterialApp(
        debugShowCheckedModeBanner: false,
        title: 'à¦¬à¦¾à¦‚à¦²à¦¾ à¦ªà¦žà§à¦œà¦¿à¦•à¦¾',
        // readability à¦†à¦ªà¦¡à§‡à¦Ÿ: à¦ªà§à¦°à§‹ à¦…à§à¦¯à¦¾à¦ªà§‡ à¦à¦–à¦¨ Noto Sans Bengali à¦«à¦¨à§à¦Ÿ
        // à¦¬à§à¦¯à¦¬à¦¹à¦¾à¦° à¦¹à¦šà§à¦›à§‡ (à¦«à§‹à¦¨à¦­à§‡à¦¦à§‡ à¦¡à¦¿à¦«à¦²à§à¦Ÿ à¦¬à¦¾à¦‚à¦²à¦¾ à¦«à¦¨à§à¦Ÿ à¦†à¦²à¦¾à¦¦à¦¾/à¦…à¦¸à§à¦ªà¦·à§à¦Ÿ à¦¦à§‡à¦–à¦¾à¦¤à§‡
        // à¦ªà¦¾à¦°à¦¤, à¦à¦Ÿà¦¾ à¦¸à¦¬ à¦«à§‹à¦¨à§‡ à¦à¦•à¦‡ à¦°à¦•à¦® à¦ªà¦°à¦¿à¦·à§à¦•à¦¾à¦° à¦“ à¦®à§‹à¦Ÿà¦¾ à¦¦à§‡à¦–à¦¾à¦¬à§‡)
        theme: ThemeData(
          useMaterial3: true,
          fontFamily: 'NotoSansBengali',
          scaffoldBackgroundColor: Colors.transparent,
          canvasColor: Colors.transparent,
          appBarTheme: const AppBarTheme(
            backgroundColor: Colors.transparent,
            surfaceTintColor: Colors.transparent,
            elevation: 0,
            scrolledUnderElevation: 0,
          ),
        ),
        // à¦«à§‹à¦¨à§‡à¦° à¦¸à¦¿à¦¸à§à¦Ÿà§‡à¦® à¦«à¦¨à§à¦Ÿ-à¦¸à¦¾à¦‡à¦œ à¦¯à¦¤à¦‡ à¦›à§‹à¦Ÿ à¦¸à§‡à¦Ÿ à¦•à¦°à¦¾ à¦¥à¦¾à¦•à§à¦• (à¦•à¦® à¦¬à¦¯à¦¼à¦¸à§€à¦¦à§‡à¦° à¦«à§‹à¦¨à§‡
        // à¦à¦®à¦¨ à¦¥à¦¾à¦•à¦¤à§‡ à¦ªà¦¾à¦°à§‡), à¦…à§à¦¯à¦¾à¦ªà§‡à¦° à¦²à§‡à¦–à¦¾ à¦•à¦–à¦¨à§‹ à¦¡à¦¿à¦œà¦¾à¦‡à¦¨ à¦•à¦°à¦¾ à¦¸à¦¾à¦‡à¦œà§‡à¦° à¦šà§‡à¦¯à¦¼à§‡ à¦›à§‹à¦Ÿ
        // à¦¦à§‡à¦–à¦¾à¦¬à§‡ à¦¨à¦¾ (readability floor) â€” à¦†à¦¬à¦¾à¦° à¦•à§‡à¦‰ à¦¸à¦¿à¦¸à§à¦Ÿà§‡à¦® à¦«à¦¨à§à¦Ÿ à¦…à¦¨à§‡à¦• à¦¬à¦¡à¦¼
        // à¦•à¦°à§‡ à¦°à¦¾à¦–à¦²à§‡à¦“ à§§.à§© à¦—à§à¦£à§‡à¦° à¦¬à§‡à¦¶à¦¿ à¦¬à¦¡à¦¼ à¦¹à¦¬à§‡ à¦¨à¦¾, à¦¯à¦¾à¦¤à§‡ à¦•à¦¾à¦°à§à¦¡/à¦¬à¦¾à¦Ÿà¦¨à§‡à¦° à¦²à§‡à¦†à¦‰à¦Ÿ
        // à¦­à§‡à¦™à§‡ à¦¨à¦¾ à¦¯à¦¾à¦¯à¦¼
        builder: (context, child) {
          final mq = MediaQuery.of(context);
          return MediaQuery(
            data: mq.copyWith(
              textScaler: mq.textScaler.clamp(
                minScaleFactor: Phase14Prefs.elderMode ? 1.14 : 1.0,
                maxScaleFactor: Phase14Prefs.elderMode ? 1.55 : 1.3,
              ),
            ),
            child: child!,
          );
        },
        initialRoute: '/splash',
        navigatorObservers: [routeObserver],
        routes: {
          '/splash': (context) => const SplashScreen(),
          '/language': (context) => const LanguageScreen(),
          '/onboarding': (context) => const OnboardingScreen(),
          '/location': (context) => const LocationSelectScreen(),
          '/permission': (context) => const PermissionScreen(),
          '/theme_select': (context) => const ThemeSelectScreen(),
          '/home': (context) => const HomeDashboardScreen(),
        },
      ),
    );
  }
}

/// à¦¦à¦¿à¦¨à§‡à¦° à¦•à§‹à¦¨ à¦®à§à¦¹à§‚à¦°à§à¦¤à§‡ à¦†à¦•à¦¾à¦¶ à¦•à§‡à¦®à¦¨ à¦¦à§‡à¦–à¦¾à¦¬à§‡ (à¦°à¦‚, à¦¤à¦¾à¦°à¦¾, à¦¸à§‚à¦°à§à¦¯/à¦šà¦¾à¦à¦¦à§‡à¦° à¦…à¦¬à¦¸à§à¦¥à¦¾à¦¨) â€”
/// à¦ªà§à¦°à¦•à§ƒà¦¤ à¦¸à§‚à¦°à§à¦¯à§‹à¦¦à¦¯à¦¼/à¦…à¦¸à§à¦¤à§‡à¦° à¦¸à¦®à¦¯à¦¼à§‡à¦° à¦­à¦¿à¦¤à§à¦¤à¦¿à¦¤à§‡ (à¦°à¦¿à¦¯à¦¼à§‡à¦²-à¦Ÿà¦¾à¦‡à¦®) à¦¹à¦¿à¦¸à§‡à¦¬ à¦•à¦°à¦¾ à¦¹à¦¯à¦¼à¥¤
class SkyPhase {
  final List<Color> gradientColors;
  final List<double> gradientStops;
  final double starOpacity;
  final bool isDay;
  // à¦ªà§à¦°à¦•à§ƒà¦¤ à¦šà¦¾à¦à¦¦à§‡à¦° à¦¦à¦¶à¦¾ â€” moonIllumination: à§¦ (à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾) .. à§§ (à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾)
  final double moonIllumination;
  final bool
  moonWaxing; // true = à¦¶à§à¦•à§à¦²à¦ªà¦•à§à¦· (à¦¬à¦¾à¦¡à¦¼à¦›à§‡), false = à¦•à§ƒà¦·à§à¦£à¦ªà¦•à§à¦· (à¦•à¦®à¦›à§‡)
  final bool
  isAmavasya; // à¦†à¦œ à¦ªà§à¦°à¦¾à¦¯à¦¼ à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾ â€” à¦°à¦¾à¦¤à§‡à¦° à¦†à¦•à¦¾à¦¶ à¦ªà§à¦°à§‹ à¦•à¦¾à¦²à§‹ à¦¦à§‡à¦–à¦¾à¦¬à§‡

  const SkyPhase({
    required this.gradientColors,
    required this.gradientStops,
    required this.starOpacity,
    required this.isDay,
    required this.moonIllumination,
    required this.moonWaxing,
    required this.isAmavasya,
  });

  // à¦®à¦¹à¦¾à¦•à¦¾à¦¶ à¦¥à§‡à¦•à§‡ à¦¦à§‡à¦–à¦¾ à¦†à¦•à¦¾à¦¶: à¦‰à¦ªà¦°à§‡à¦° à¦¦à¦¿à¦• à¦¸à¦¬à¦¸à¦®à¦¯à¦¼ à¦—à¦­à§€à¦° à¦…à¦¨à§à¦§à¦•à¦¾à¦° à¦®à¦¹à¦¾à¦¶à§‚à¦¨à§à¦¯,
  // à¦¶à§à¦§à§ à¦¨à¦¿à¦šà§‡à¦° à¦¦à¦¿à¦—à¦¨à§à¦¤à§‡ à¦¬à¦¾à¦¯à¦¼à§à¦®à¦£à§à¦¡à¦²à§‡à¦° à¦†à¦­à¦¾ à¦¸à¦®à¦¯à¦¼ à¦…à¦¨à§à¦¯à¦¾à¦¯à¦¼à§€ à¦°à¦‚ à¦¬à¦¦à¦²à¦¾à¦¯à¦¼à¥¤
  // à¦à¦¤à§‡ à¦¬à§à¦°à¦¹à§à¦®à¦¾à¦£à§à¦¡à§‡à¦° à¦šà§‡à¦¹à¦¾à¦°à¦¾ à¦¦à¦¿à¦¨à§‡-à¦°à¦¾à¦¤à§‡ à¦¸à¦¬à¦¸à¦®à¦¯à¦¼ à¦¬à¦œà¦¾à¦¯à¦¼ à¦¥à¦¾à¦•à§‡à¥¤
  static const List<Color> _night = [
    Color(0xFF01030A),
    Color(0xFF050D1E),
    Color(0xFF071228),
    Color(0xFF03060F),
  ];
  // à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾à¦° à¦°à¦¾à¦¤ â€” à¦šà¦¾à¦à¦¦à§‡à¦° à¦†à¦²à§‹ à¦à¦•à¦¦à¦®à¦‡ à¦¨à§‡à¦‡ à¦¬à¦²à§‡ à¦¬à¦¾à¦¸à§à¦¤à¦¬à§‡ à¦†à¦•à¦¾à¦¶ à¦¸à¦¬à¦šà§‡à¦¯à¦¼à§‡ à¦—à¦¾à¦¢à¦¼/à¦•à¦¾à¦²à§‹
  // à¦¦à§‡à¦–à¦¾à¦¯à¦¼, à¦¶à§à¦§à§ à¦¤à¦¾à¦°à¦¾à¦—à§à¦²à§‹ à¦«à§à¦Ÿà§‡ à¦¥à¦¾à¦•à§‡
  static const List<Color> _amavasyaNight = [
    Color(0xFF000000),
    Color(0xFF010103),
    Color(0xFF020208),
    Color(0xFF000000),
  ];
  static const List<Color> _dawnDusk = [
    Color(0xFF030718),
    Color(0xFF0B1430),
    Color(0xFF4A2F5E),
    Color(0xFF10142A),
  ];
  static const List<Color> _sunriseSunset = [
    Color(0xFF040A1C),
    Color(0xFF0E1E42),
    Color(0xFFC2603A),
    Color(0xFF2A1428),
  ];
  static const List<Color> _morningEvening = [
    Color(0xFF04091A),
    Color(0xFF0C1B3C),
    Color(0xFF6E86B8),
    Color(0xFF14203A),
  ];
  static const List<Color> _midday = [
    Color(0xFF04081A),
    Color(0xFF0A1735),
    Color(0xFF2E5F96),
    Color(0xFF0C1730),
  ];
  static const List<double> _stops = [0.0, 0.45, 0.82, 1.0];

  static List<Color> _lerpColors(List<Color> a, List<Color> b, double t) =>
      List.generate(a.length, (i) => Color.lerp(a[i], b[i], t)!);

  static SkyPhase forTime(DateTime now, {double? lat, double? lon}) {
    final today = PanchangCalculator.sunTimes(now, lat: lat, lon: lon);
    final sunrise = today.sunrise;
    final sunset = today.sunset;
    // sunTimes() à¦¯à¦¾ à¦°à¦¿à¦Ÿà¦¾à¦°à§à¦¨ à¦•à¦°à§‡ à¦¤à¦¾ "IST-marked" (à¦¦à§‡à¦–à§à¦¨
    // PanchangCalculator._toTrueUtc-à¦à¦° à¦®à¦¨à§à¦¤à¦¬à§à¦¯) â€” DateTime.now() à¦¸à¦°à¦¾à¦¸à¦°à¦¿
    // à¦à¦° à¦¸à¦¾à¦¥à§‡ à¦¤à§à¦²à¦¨à¦¾ à¦•à¦°à¦²à§‡ à§«:à§©à§¦ à¦˜à¦¨à§à¦Ÿà¦¾à¦° à¦­à§à¦² à¦¹à¦¤à§‹, à¦¤à¦¾à¦‡ à¦à¦•à¦‡ à¦«à¦°à¦®à§à¦¯à¦¾à¦Ÿà§‡ à¦†à¦¨à¦¾ à¦¹à¦²à§‹à¥¤
    final nowMarked = now.toUtc().add(const Duration(hours: 5, minutes: 30));

    // --- à¦ªà§à¦°à¦•à§ƒà¦¤ à¦šà¦¾à¦à¦¦à§‡à¦° à¦¦à¦¶à¦¾ (real-time) ---
    // moonAgeDays: à§¦ = à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾ à¦®à§à¦¹à§‚à¦°à§à¦¤, ~à§§à§ª.à§­à§­ = à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾, ~à§¨à§¯.à§«à§© = à¦ªà¦°à§‡à¦° à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾
    const synodic = 29.530588853;
    final moonAge = PanchangCalculator.moonAgeDays(now) % synodic;
    final phaseAngle = moonAge / synodic * 2 * math.pi;
    final moonIllumination = (1 - math.cos(phaseAngle)) / 2; // à§¦..à§§
    final moonWaxing = moonAge < synodic / 2;
    // à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾à¦° ~à§§ à¦¦à¦¿à¦¨à§‡à¦° à¦®à¦§à§à¦¯à§‡ à¦¥à¦¾à¦•à¦²à§‡ "à¦†à¦œ à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾" à¦§à¦°à¦¾ à¦¹à¦šà§à¦›à§‡
    final isAmavasya = moonAge < 1.0 || moonAge > synodic - 1.0;
    final nightColors = isAmavasya ? _amavasyaNight : _night;

    if (nowMarked.isAfter(sunrise) && nowMarked.isBefore(sunset)) {
      // --- à¦¦à¦¿à¦¨ ---
      final total = sunset.difference(sunrise).inSeconds;
      final elapsed = nowMarked.difference(sunrise).inSeconds;
      final p = total <= 0 ? 0.5 : (elapsed / total).clamp(0.0, 1.0);

      List<Color> colors;
      if (p < 0.12) {
        colors = _lerpColors(_sunriseSunset, _morningEvening, p / 0.12);
      } else if (p < 0.4) {
        colors = _lerpColors(_morningEvening, _midday, (p - 0.12) / 0.28);
      } else if (p < 0.6) {
        colors = _midday;
      } else if (p < 0.88) {
        colors = _lerpColors(_midday, _morningEvening, (p - 0.6) / 0.28);
      } else {
        colors = _lerpColors(
          _morningEvening,
          _sunriseSunset,
          (p - 0.88) / 0.12,
        );
      }

      return SkyPhase(
        gradientColors: colors,
        gradientStops: _stops,
        starOpacity: 0.55,
        isDay: true,
        moonIllumination: moonIllumination,
        moonWaxing: moonWaxing,
        isAmavasya: isAmavasya,
      );
    }

    // --- à¦°à¦¾à¦¤ (à¦¸à§‚à¦°à§à¦¯à¦¾à¦¸à§à¦¤ à¦¥à§‡à¦•à§‡ à¦ªà¦°à§‡à¦° à¦¸à§‚à¦°à§à¦¯à§‹à¦¦à¦¯à¦¼ à¦ªà¦°à§à¦¯à¦¨à§à¦¤) ---
    late DateTime nightStart;
    late DateTime nightEnd;
    if (nowMarked.isAfter(sunset)) {
      nightStart = sunset;
      nightEnd = PanchangCalculator.sunTimes(
        now.add(const Duration(days: 1)),
        lat: lat,
        lon: lon,
      ).sunrise;
    } else {
      nightStart = PanchangCalculator.sunTimes(
        now.subtract(const Duration(days: 1)),
        lat: lat,
        lon: lon,
      ).sunset;
      nightEnd = sunrise;
    }
    final total = nightEnd.difference(nightStart).inSeconds;
    final elapsed = nowMarked.difference(nightStart).inSeconds;
    final p = total <= 0 ? 0.5 : (elapsed / total).clamp(0.0, 1.0);

    List<Color> colors;
    double starOpacity;
    // à¦¤à¦¾à¦°à¦¾à¦° à¦‰à¦œà§à¦œà§à¦¬à¦²à¦¤à¦¾ à¦•à¦–à¦¨à¦“ à§¦ à¦¹à¦¯à¦¼ à¦¨à¦¾ â€” à¦¦à¦¿à¦¨à§‡à¦“ à¦®à§à¦²à¦¾à¦¨à¦­à¦¾à¦¬à§‡ à¦¬à§à¦°à¦¹à§à¦®à¦¾à¦£à§à¦¡ à¦¦à§‡à¦–à¦¾ à¦¯à¦¾à¦¯à¦¼,
    // à¦—à¦­à§€à¦° à¦°à¦¾à¦¤à§‡ à¦¸à¦¬à¦šà§‡à¦¯à¦¼à§‡ à¦‰à¦œà§à¦œà§à¦¬à¦²à¥¤
    if (p < 0.08) {
      colors = _lerpColors(_sunriseSunset, _dawnDusk, p / 0.08);
      starOpacity = 0.55 + p / 0.08 * 0.30;
    } else if (p < 0.22) {
      colors = _lerpColors(_dawnDusk, nightColors, (p - 0.08) / 0.14);
      starOpacity = 0.85 + (p - 0.08) / 0.14 * 0.15;
    } else if (p < 0.78) {
      colors = nightColors;
      starOpacity = 1.0;
    } else if (p < 0.92) {
      colors = _lerpColors(nightColors, _dawnDusk, (p - 0.78) / 0.14);
      starOpacity = 1.0 - (p - 0.78) / 0.14 * 0.15;
    } else {
      colors = _lerpColors(_dawnDusk, _sunriseSunset, (p - 0.92) / 0.08);
      starOpacity = 0.85 - (p - 0.92) / 0.08 * 0.30;
    }

    return SkyPhase(
      gradientColors: colors,
      gradientStops: _stops,
      starOpacity: starOpacity.clamp(0.0, 1.0),
      isDay: false,
      moonIllumination: moonIllumination,
      moonWaxing: moonWaxing,
      isAmavasya: isAmavasya,
    );
  }
}

/// à¦¸à§Œà¦°à¦œà¦—à¦¤à§‡à¦° à¦—à§à¦°à¦¹ â€” à¦¸à§‚à¦°à§à¦¯/à¦ªà§ƒà¦¥à¦¿à¦¬à§€ à¦¬à¦¾à¦¦à§‡ à¦¬à¦¾à¦•à¦¿ à§­à¦Ÿà¦¿ â€” à¦®à¦¹à¦¾à¦•à¦¾à¦¶ à¦¬à§à¦¯à¦¾à¦•à¦—à§à¦°à¦¾à¦‰à¦¨à§à¦¡à§‡
/// à¦¦à§‡à¦–à¦¾à¦¨à§‹à¦° à¦œà¦¨à§à¦¯ à¦ªà§à¦°à¦¤à¦¿à¦Ÿà¦¿à¦° à¦¬à¦¾à¦¸à§à¦¤à¦¬ à¦°à¦‚ (à¦†à¦¨à§à¦®à¦¾à¦¨à¦¿à¦•) à¦“ à¦—à¦¡à¦¼ à¦†à¦ªà¦¾à¦¤ à¦‰à¦œà§à¦œà§à¦¬à¦²à¦¤à¦¾
/// (mean apparent magnitude â€” à¦•à¦® à¦®à¦¾à¦¨ = à¦¬à§‡à¦¶à¦¿ à¦‰à¦œà§à¦œà§à¦¬à¦²)à¥¤ à¦‰à¦œà§à¦œà§à¦¬à¦²à¦¤à¦¾ real-time
/// phase-angle à¦¹à¦¿à¦¸à§‡à¦¬ à¦•à¦°à§‡ à¦¬à¦¦à¦²à¦¾à¦¯à¦¼ à¦¨à¦¾ (à¦¤à¦¾à¦° à¦œà¦¨à§à¦¯ à¦…à¦¤à¦¿à¦°à¦¿à¦•à§à¦¤ à¦œà¦Ÿà¦¿à¦² à¦¸à§‚à¦¤à§à¦° à¦²à¦¾à¦—à¦¤),
/// à¦¶à§à¦§à§ à¦¡à¦Ÿà§‡à¦° à¦†à¦•à¦¾à¦°/à¦†à¦­à¦¾ à¦•à¦¤à¦Ÿà¦¾ à¦ªà§à¦°à¦•à¦Ÿ à¦¹à¦¬à§‡ à¦¤à¦¾à¦° à¦à¦•à¦Ÿà¦¾ à¦¸à§‚à¦•à§à¦·à§à¦® à¦‡à¦™à§à¦—à¦¿à¦¤ à¦¦à¦¿à¦¤à§‡
/// à¦¬à§à¦¯à¦¬à¦¹à§ƒà¦¤ à¦¹à¦¯à¦¼ â€” à¦•à§‹à¦¨à§‹ à¦—à§à¦°à¦¹à¦‡ à¦¬à¦¾à¦¸à§à¦¤à¦¬ à¦¸à§à¦•à§‡à¦²à§‡ à¦†à¦à¦•à¦¾ à¦¹à¦¯à¦¼ à¦¨à¦¾, à¦¶à§à¦§à§ readability-à¦°
/// à¦œà¦¨à§à¦¯ subtle à¦ªà¦¾à¦°à§à¦¥à¦•à§à¦¯ à¦°à¦¾à¦–à¦¾ à¦¹à¦¯à¦¼à§‡à¦›à§‡à¥¤
