  // à¦à¦–à¦¾à¦¨à§‡ à¦¦à§‡à¦–à¦¾à¦¤à§‡ à¦²à¦¾à¦—à¦¬à§‡ ~à§¬ à¦®à¦¿à¦¨à¦¿à¦Ÿ â€” à¦¤à¦¬à§à¦“ à¦ªà§à¦°à¦¤à¦¿à¦Ÿà¦¾ à¦®à§à¦¹à§‚à¦°à§à¦¤à§‡à¦° à¦…à¦¬à¦¸à§à¦¥à¦¾à¦¨ à¦†à¦¸à¦²
  // astronomical à¦¸à§‚à¦¤à§à¦° à¦¦à¦¿à¦¯à¦¼à§‡à¦‡ à¦¬à§‡à¦° à¦•à¦°à¦¾, à¦•à§‹à¦¨à§‹ à¦à¦²à§‹à¦®à§‡à¦²à§‹/à¦•à¦¾à¦²à§à¦ªà¦¨à¦¿à¦• à¦—à¦¤à¦¿ à¦¨à¦¯à¦¼
  static const double _planetTimeAcceleration = 240.0;
  Timer? _clockTimer;
  SkyPhase _phase = SkyPhase.forTime(DateTime.now());
  bool _isRaining = false;
  bool _routeVisible = true;

  static const Map<String, double> _planetRingDiameter = {
    'mercury': 66,
    'venus': 88,
    'mars': 112,
    'jupiter': 136,
    'saturn': 160,
    'uranus': 184,
    'neptune': 208,
  };

  @override
  void initState() {
    super.initState();
    _rainController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1100),
    );
    _planetClock = AnimationController(
      vsync: this,
      duration: const Duration(seconds: 1),
    );
    _planetSimAnchor = DateTime.now();
    _refreshPhase();
    // à¦¨à¦¿à¦°à§à¦¬à¦¾à¦šà¦¿à¦¤ à¦œà§‡à¦²à¦¾à¦¯à¦¼ à¦¸à¦¤à§à¦¯à¦¿à¦‡ à¦à¦–à¦¨ à¦¬à§ƒà¦·à§à¦Ÿà¦¿ à¦¹à¦šà§à¦›à§‡ à¦•à¦¿à¦¨à¦¾ â€” à¦²à¦¾à¦‡à¦­, à¦²à§‹à¦•à§‡à¦¶à¦¨-à¦­à¦¿à¦¤à§à¦¤à¦¿à¦•
    _isRaining = WeatherService.instance.isRaining;
    _syncRainAnim();
    WeatherService.instance.addListener(_onWeatherChanged);
    WeatherService.instance.refresh();
    // à¦«à§‹à¦¨à§‡à¦°/à¦¬à§à¦°à¦¾à¦‰à¦œà¦¾à¦°à§‡à¦° real-time GPS à¦²à§‹à¦•à§‡à¦¶à¦¨ â€” à¦…à¦¨à§à¦®à¦¤à¦¿ à¦ªà§‡à¦²à§‡ à¦¸à§‚à¦°à§à¦¯à§‹à¦¦à¦¯à¦¼/à¦…à¦¸à§à¦¤ à¦“
    // à¦†à¦¬à¦¹à¦¾à¦“à¦¯à¦¼à¦¾ à¦¬à§à¦¯à¦¬à¦¹à¦¾à¦°à¦•à¦¾à¦°à§€à¦° à¦ªà§à¦°à¦•à§ƒà¦¤ à¦œà¦¾à¦¯à¦¼à¦—à¦¾ à¦§à¦°à§‡ à¦¹à¦¿à¦¸à§‡à¦¬ à¦¹à¦¬à§‡, à¦¨à¦¾ à¦ªà§‡à¦²à§‡ à¦®à§à¦¯à¦¾à¦¨à§à¦¯à¦¼à¦¾à¦²
    // à¦œà§‡à¦²à¦¾à¦¤à§‡à¦‡ à¦šà§à¦ªà¦šà¦¾à¦ª à¦¥à¦¾à¦•à¦¬à§‡
    LocationService.instance.addListener(_onLocationChanged);
    LocationService.instance.refresh();
    // à¦ªà§à¦°à¦¤à¦¿ à¦®à¦¿à¦¨à¦¿à¦Ÿà§‡ à¦†à¦•à¦¾à¦¶à§‡à¦° à¦°à¦‚/à¦¸à§‚à¦°à§à¦¯-à¦šà¦¾à¦à¦¦à§‡à¦° à¦…à¦¬à¦¸à§à¦¥à¦¾à¦¨ à¦°à¦¿à¦¯à¦¼à§‡à¦² à¦Ÿà¦¾à¦‡à¦®à§‡ à¦†à¦ªà¦¡à§‡à¦Ÿ à¦¹à¦¬à§‡;
    // WeatherService à¦¨à¦¿à¦œà§‡ à§§à§« à¦®à¦¿à¦¨à¦¿à¦Ÿà§‡à¦° à¦¬à§‡à¦¶à¦¿ à¦ªà§à¦°à¦¨à§‹ à¦¨à¦¾ à¦¹à¦²à§‡ à¦†à¦¬à¦¾à¦° à¦•à¦² à¦•à¦°à§‡ à¦¨à¦¾, à¦¤à¦¾à¦‡
    // à¦à¦–à¦¾à¦¨à§‡ refresh() à¦¡à¦¾à¦•à¦²à§‡à¦“ à¦¬à¦¾à¦¡à¦¼à¦¤à¦¿ à¦¨à§‡à¦Ÿà¦“à¦¯à¦¼à¦¾à¦°à§à¦• à¦²à§‹à¦¡ à¦¹à¦¯à¦¼ à¦¨à¦¾
    _clockTimer = Timer.periodic(const Duration(seconds: 60), (_) {
      _refreshPhase();
      WeatherService.instance.refresh();
    });
  }

  void _onWeatherChanged() {
    if (!mounted) return;
    setState(() {
      _isRaining = WeatherService.instance.isRaining;
      _syncRainAnim();
    });
  }

  void _onLocationChanged() {
    if (!mounted) return;
    // GPS à¦²à§‹à¦•à§‡à¦¶à¦¨ à¦à¦‡à¦®à¦¾à¦¤à§à¦° à¦ªà¦¾à¦“à¦¯à¦¼à¦¾ à¦—à§‡à¦² â€” à¦¸à§‚à¦°à§à¦¯à§‹à¦¦à¦¯à¦¼/à¦…à¦¸à§à¦¤ à¦“ à¦†à¦¬à¦¹à¦¾à¦“à¦¯à¦¼à¦¾ à¦¨à¦¤à§à¦¨ à¦•à¦°à§‡
    // à¦¹à¦¿à¦¸à§‡à¦¬ à¦¹à¦¬à§‡ à¦¸à§‡à¦‡ real à¦œà¦¾à¦¯à¦¼à¦—à¦¾ à¦§à¦°à§‡
    _refreshPhase();
    WeatherService.instance.refresh(force: true);
  }

  void _syncRainAnim() {
    if (_isRaining && AppSettings.instance.skyAnim) {
      if (!_rainController.isAnimating) _rainController.repeat();
    } else {
      _rainController.stop();
    }
  }

  void _refreshPhase() {
    if (!mounted) return;
    final now = DateTime.now();
    final phase = SkyPhase.forTime(
      now,
      lat: AppLocation.lat,
      lon: AppLocation.lon,
    );

    setState(() {
      _phase = phase;
    });
    // à¦—à§à¦°à¦¹à§‡à¦° à¦˜à¦¡à¦¼à¦¿ (accelerated virtual time) à¦šà¦¾à¦²à§/à¦¬à¦¨à§à¦§ â€” à¦¸à§‡à¦Ÿà¦¿à¦‚à¦¸à§‡ Live Sky
    // Animation à¦¬à¦¨à§à¦§ à¦¥à¦¾à¦•à¦²à§‡ à¦¥à§‡à¦®à§‡ à¦¯à¦¾à¦¬à§‡, à¦¤à¦–à¦¨ à¦—à§à¦°à¦¹ à¦¶à§‡à¦· à¦«à§à¦°à§‡à¦®à§‡à¦° à¦…à¦¬à¦¸à§à¦¥à¦¾à¦¨à§‡à¦‡ à¦¸à§à¦¥à¦¿à¦°
    // à¦¥à¦¾à¦•à¦¬à§‡ (à¦†à¦•à¦¾à¦¶à§‡à¦° à¦°à¦‚/à¦¸à§‚à¦°à§à¦¯à§‹à¦¦à¦¯à¦¼-à¦…à¦¸à§à¦¤ à¦‡à¦¤à§à¦¯à¦¾à¦¦à¦¿à¦° à¦“à¦ªà¦° à¦à¦° à¦•à§‹à¦¨à§‹ à¦ªà§à¦°à¦­à¦¾à¦¬ à¦¨à§‡à¦‡)
    if (AppSettings.instance.skyAnim) {
      if (!_planetClock.isAnimating) _planetClock.repeat();
    } else {
      _planetClock.stop();
    }
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    routeObserver.subscribe(this, ModalRoute.of(context)!);
  }

  @override
  void didPush() {
    _syncRainAnim();
  }

  @override
  void didPopNext() {
    setState(() => _routeVisible = true);
    _refreshPhase();
    WeatherService.instance.refresh();
    _syncRainAnim();
  }

  @override
  void didPushNext() {
    _rainController.stop();
    _planetClock.stop();
    setState(() => _routeVisible = false);
  }

  @override
  void dispose() {
    routeObserver.unsubscribe(this);
    _rainController.dispose();
    _planetClock.dispose();
    WeatherService.instance.removeListener(_onWeatherChanged);
    LocationService.instance.removeListener(_onLocationChanged);
    _clockTimer?.cancel();
    super.dispose();
  }

