// à¦¬à¦¾à¦¸à§à¦¤à¦¬ à¦¬à§à¦°à¦¹à§à¦®à¦¾à¦£à§à¦¡ â€” à¦¤à¦¾à¦°à¦¾, à¦›à¦¾à¦¯à¦¼à¦¾à¦ªà¦¥ (Milky Way) à¦“ à¦¨à§€à¦¹à¦¾à¦°à¦¿à¦•à¦¾
// =====================================================================

/// à¦à¦•à¦Ÿà¦¿ à¦¤à¦¾à¦°à¦¾à¦° à¦¬à§ˆà¦¶à¦¿à¦·à§à¦Ÿà§à¦¯à¥¤ à¦ªà§à¦°à¦•à§ƒà¦¤ à¦¨à¦•à§à¦·à¦¤à§à¦°à§‡à¦° à¦®à¦¤à§‹ à¦°à¦‚, à¦‰à¦œà§à¦œà§à¦¬à¦²à¦¤à¦¾ à¦“ à¦®à¦¿à¦Ÿà¦®à¦¿à¦Ÿ à¦•à¦°à¦¾à¦°
/// à¦¨à¦¿à¦œà¦¸à§à¦¬ à¦›à¦¨à§à¦¦ à¦¥à¦¾à¦•à§‡ â€” à¦¤à¦¾à¦‡ à¦ªà§à¦°à¦¤à¦¿à¦Ÿà¦¿ à¦¤à¦¾à¦°à¦¾à¦° à¦†à¦²à¦¾à¦¦à¦¾ speed/phase à¦°à¦¾à¦–à¦¾ à¦¹à¦¯à¦¼à§‡à¦›à§‡à¥¤
class _StarSpec {
  final Offset pos; // 0..1 à¦†à¦ªà§‡à¦•à§à¦·à¦¿à¦• à¦…à¦¬à¦¸à§à¦¥à¦¾à¦¨
  final double radius;
  final double baseAlpha;
  final Color color;
  final double twinkleSpeed;
  final double twinklePhase;
  final bool
  bright; // à¦‰à¦œà§à¦œà§à¦¬à¦² à¦¤à¦¾à¦°à¦¾ â€” à¦¬à¦¾à¦¡à¦¼à¦¤à¦¿ à¦†à¦­à¦¾ à¦“ à¦°à¦¶à§à¦®à¦¿ à¦ªà¦¾à¦¬à§‡
  const _StarSpec(
    this.pos,
    this.radius,
    this.baseAlpha,
    this.color,
    this.twinkleSpeed,
    this.twinklePhase,
    this.bright,
  );
}

/// à¦ªà§à¦°à¦•à§ƒà¦¤ à¦¨à¦•à§à¦·à¦¤à§à¦°à§‡à¦° à¦¬à¦°à§à¦£à¦¾à¦²à§€ à¦¶à§à¦°à§‡à¦£à¦¿ à¦…à¦¨à§à¦¯à¦¾à¦¯à¦¼à§€ à¦°à¦‚ (O/B à¦¨à§€à¦²à¦¾à¦­ â†’ M à¦²à¦¾à¦²à¦šà§‡)
const List<Color> _stellarColors = [
  Color(0xFFC8D8FF), // à¦¨à§€à¦²à¦¾à¦­-à¦¸à¦¾à¦¦à¦¾ (à¦—à¦°à¦® à¦¤à¦¾à¦°à¦¾)
  Color(0xFFDCE6FF),
  Color(0xFFFFFFFF), // à¦¸à¦¾à¦¦à¦¾
  Color(0xFFFFFFFF),
  Color(
    0xFFFFF6E8,
  ), // à¦¹à¦²à¦¦à§‡-à¦¸à¦¾à¦¦à¦¾ (à¦¸à§‚à¦°à§à¦¯à§‡à¦° à¦®à¦¤à§‹)
  Color(0xFFFFF0D0),
  Color(0xFFFFD9A8), // à¦•à¦®à¦²à¦¾
  Color(0xFFFFC6A0), // à¦²à¦¾à¦²à¦šà§‡ (à¦ à¦¾à¦¨à§à¦¡à¦¾ à¦¤à¦¾à¦°à¦¾)
];

class StarsLayer extends StatefulWidget {
  const StarsLayer({super.key});
  @override
  State<StarsLayer> createState() => _StarsLayerState();
}

class _StarsLayerState extends State<StarsLayer> with TickerProviderStateMixin {
  late final AnimationController _twinkle;
  // à¦ªà§ƒà¦¥à¦¿à¦¬à§€à¦° à¦˜à§‚à¦°à§à¦£à¦¨à§‡à¦° à¦•à¦¾à¦°à¦£à§‡ à¦¬à¦¾à¦¸à§à¦¤à¦¬à§‡ à¦¤à¦¾à¦°à¦¾ à¦†à¦•à¦¾à¦¶à§‡ à¦–à§à¦¬ à¦§à§€à¦°à§‡ à¦§à§€à¦°à§‡ à¦¸à¦°à§‡ à¦¬à¦²à§‡ à¦®à¦¨à§‡
  // à¦¹à¦¯à¦¼ â€” à¦ªà§à¦°à§‹ dome-projection à¦›à¦¾à¦¡à¦¼à¦¾à¦‡ à¦¸à§‡à¦‡ à¦…à¦¨à§à¦­à§‚à¦¤à¦¿ à¦†à¦¨à¦¤à§‡ à¦¸à¦®à§à¦ªà§‚à¦°à§à¦£ à¦¤à¦¾à¦°à¦¾à¦°
  // à¦¸à§à¦¤à¦°à§‡ à¦…à¦¤à§à¦¯à¦¨à§à¦¤ à¦¸à§‚à¦•à§à¦·à§à¦®, à¦§à§€à¦° à¦˜à§‚à¦°à§à¦£à¦¨ (à¦®à¦¾à¦¤à§à¦° ~à§¦.à§¬Â° à¦¦à§‹à¦²à§‡)
  late final AnimationController _drift;
  late final List<_StarSpec> _stars;
  late final List<_DustPuff> _milkyWay;
  late final List<_NebulaBlob> _nebulae;

  @override
  void initState() {
    super.initState();
    final rnd = math.Random(42);

    // --- à¦¤à¦¾à¦°à¦¾: à¦¬à§‡à¦¶à¦¿à¦°à¦­à¦¾à¦— à¦•à§à¦·à§€à¦£, à¦…à¦²à§à¦ª à¦•à¦¿à¦›à§ à¦‰à¦œà§à¦œà§à¦¬à¦² (à¦ªà§à¦°à¦•à§ƒà¦¤ à¦†à¦•à¦¾à¦¶à§‡à¦° à¦®à¦¤à§‹ à¦¬à¦£à§à¦Ÿà¦¨) ---
    _stars = List.generate(190, (i) {
      // r^3 à¦¬à¦£à§à¦Ÿà¦¨ â€” à¦…à¦§à¦¿à¦•à¦¾à¦‚à¦¶ à¦¤à¦¾à¦°à¦¾ à¦›à§‹à¦Ÿ, à¦¹à¦¾à¦¤à§‡à¦—à§‹à¦¨à¦¾ à¦•à¦¯à¦¼à§‡à¦•à¦Ÿà¦¾ à¦¬à¦¡à¦¼
      final t = rnd.nextDouble();
      final sizeFactor = t * t * t;
      final radius = 0.35 + sizeFactor * 2.1;
      final bright = radius > 1.7;
      return _StarSpec(
        Offset(rnd.nextDouble(), rnd.nextDouble()),
        radius,
        0.35 + rnd.nextDouble() * 0.65,
        _stellarColors[rnd.nextInt(_stellarColors.length)],
        0.4 + rnd.nextDouble() * 1.4,
        rnd.nextDouble(),
        bright,
      );
    });

    // --- à¦›à¦¾à¦¯à¦¼à¦¾à¦ªà¦¥: à¦¤à¦¿à¦°à§à¦¯à¦• à¦¬à§à¦¯à¦¾à¦¨à§à¦¡ à¦¬à¦°à¦¾à¦¬à¦° à¦§à§à¦²à§‹à¦° à¦®à§‡à¦˜ ---
    _milkyWay = List.generate(90, (i) {
      final along = rnd.nextDouble();
      // à¦¬à§à¦¯à¦¾à¦¨à§à¦¡à§‡à¦° à¦•à§‡à¦¨à§à¦¦à§à¦° à¦¥à§‡à¦•à§‡ à¦²à¦®à§à¦¬à¦­à¦¾à¦¬à§‡ à¦—à¦¾à¦‰à¦¸à§€à¦¯à¦¼ à¦¬à¦¿à¦¸à§à¦¤à¦¾à¦°
      final spread =
          (rnd.nextDouble() + rnd.nextDouble() + rnd.nextDouble()) / 3.0 - 0.5;
      final perp = spread * 0.42;
      // à¦¤à¦¿à¦°à§à¦¯à¦• à¦°à§‡à¦–à¦¾: à¦‰à¦ªà¦°à§‡-à¦¬à¦¾à¦ à¦¥à§‡à¦•à§‡ à¦¨à¦¿à¦šà§‡-à¦¡à¦¾à¦¨
      final x = along;
      final y = 0.18 + along * 0.62 + perp;
      return _DustPuff(
        Offset(x, y),
        0.05 + rnd.nextDouble() * 0.11,
        0.030 + rnd.nextDouble() * 0.055,
        rnd.nextBool() ? const Color(0xFFB9C7F0) : const Color(0xFFE6D5F5),
      );
    });

    // --- à¦¨à§€à¦¹à¦¾à¦°à¦¿à¦•à¦¾: à¦•à¦¯à¦¼à§‡à¦•à¦Ÿà¦¿ à¦¬à¦¡à¦¼ à¦°à¦™à¦¿à¦¨ à¦—à§à¦¯à¦¾à¦¸à§‡à¦° à¦®à§‡à¦˜ ---
    _nebulae = const [
      _NebulaBlob(Offset(0.18, 0.22), 0.38, Color(0xFF5B3FA8), 0.15),
      _NebulaBlob(Offset(0.78, 0.34), 0.34, Color(0xFF2E6FA8), 0.13),
      _NebulaBlob(Offset(0.52, 0.68), 0.42, Color(0xFF8A3B7A), 0.10),
      _NebulaBlob(Offset(0.30, 0.82), 0.30, Color(0xFF2B5C93), 0.11),
    ];

    _twinkle = AnimationController(
      vsync: this,
      duration: const Duration(seconds: 6),
    );
    if (AppSettings.instance.skyAnim) _twinkle.repeat();
    _drift = AnimationController(
      vsync: this,
      duration: const Duration(minutes: 9),
    );
    if (AppSettings.instance.skyAnim) _drift.repeat();
  }

  @override
  void dispose() {
    _twinkle.dispose();
    _drift.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final content = Stack(
      children: [
        // à¦¸à§à¦¥à¦¿à¦° à¦¸à§à¦¤à¦° (à¦¨à§€à¦¹à¦¾à¦°à¦¿à¦•à¦¾ + à¦›à¦¾à¦¯à¦¼à¦¾à¦ªà¦¥) â€” à¦ªà§à¦°à¦¤à¦¿ à¦«à§à¦°à§‡à¦®à§‡ à¦†à¦à¦•à¦¾à¦° à¦¦à¦°à¦•à¦¾à¦° à¦¨à§‡à¦‡
        Positioned.fill(
          child: RepaintBoundary(
            child: CustomPaint(painter: DeepSkyPainter(_nebulae, _milkyWay)),
          ),
        ),
        // à¦•à¦¯à¦¼à§‡à¦•à¦Ÿà¦¿ à¦ªà¦°à¦¿à¦šà¦¿à¦¤ à¦¤à¦¾à¦°à¦¾à¦®à¦£à§à¦¡à¦²à§‡à¦° stylized à¦†à¦­à¦¾à¦¸ (à¦¸à¦°à¦²à§€à¦•à§ƒà¦¤, à¦¨à¦¿à¦–à§à¦à¦¤ dome
        // à¦…à¦¬à¦¸à§à¦¥à¦¾à¦¨ à¦¨à¦¯à¦¼ â€” à¦¶à§à¦§à§ à¦°à¦¾à¦¤à§‡à¦° à¦†à¦•à¦¾à¦¶à§‡ à¦ªà¦°à¦¿à¦šà¦¿à¦¤ à¦†à¦•à§ƒà¦¤à¦¿à¦° à¦‡à¦™à§à¦—à¦¿à¦¤)
        Positioned.fill(
          child: RepaintBoundary(
            child: CustomPaint(painter: const _ConstellationsPainter()),
          ),
        ),
        // à¦®à¦¿à¦Ÿà¦®à¦¿à¦Ÿ à¦•à¦°à¦¾ à¦¤à¦¾à¦°à¦¾
        Positioned.fill(
          child: RepaintBoundary(
            child: CustomPaint(painter: StarsPainter(_stars, _twinkle)),
          ),
        ),
      ],
    );
    return AnimatedBuilder(
      animation: _drift,
      builder: (context, child) {
        final angle = (_drift.value - 0.5) * 0.02;
        return Transform.rotate(angle: angle, child: child);
      },
      child: content,
    );
  }
}

/// à¦ªà¦°à¦¿à¦šà¦¿à¦¤ à¦•à¦¯à¦¼à§‡à¦•à¦Ÿà¦¿ à¦¤à¦¾à¦°à¦¾à¦®à¦£à§à¦¡à¦²à§‡à¦° à¦¸à¦°à¦²à§€à¦•à§ƒà¦¤, stylized à¦ªà§à¦¯à¦¾à¦Ÿà¦¾à¦°à§à¦¨ â€” à¦¬à¦¾à¦¸à§à¦¤à¦¬ à¦†à¦•à¦¾à¦¶à§‡
/// à¦à¦‡ à¦®à§à¦¹à§‚à¦°à§à¦¤à§‡ à¦ à¦¿à¦• à¦à¦‡ à¦…à¦¬à¦¸à§à¦¥à¦¾à¦¨à§‡ à¦¦à§‡à¦–à¦¾ à¦¯à¦¾à¦¬à§‡ à¦à¦®à¦¨ à¦¨à¦¿à¦–à§à¦à¦¤ à¦œà§à¦¯à§‹à¦¤à¦¿à¦°à§à¦¬à¦¿à¦¦à§à¦¯à¦¾-à¦¸à¦®à§à¦®à¦¤
/// dome projection à¦¨à¦¯à¦¼ (à¦¤à¦¾à¦° à¦œà¦¨à§à¦¯ à¦ªà§‚à¦°à§à¦£ RA/Dec à¦®à§à¦¯à¦¾à¦ªà¦¿à¦‚ à¦²à¦¾à¦—à¦¤), à¦¬à¦°à¦‚ à¦°à¦¾à¦¤à§‡à¦°
/// à¦†à¦•à¦¾à¦¶à§‡à¦° à¦ªà¦Ÿà¦­à§‚à¦®à¦¿à¦¤à§‡ à¦ªà¦°à¦¿à¦šà¦¿à¦¤ à¦†à¦•à§ƒà¦¤à¦¿à¦° subtle à¦‡à¦™à§à¦—à¦¿à¦¤ à¦¦à§‡à¦“à¦¯à¦¼à¦¾à¦° à¦œà¦¨à§à¦¯ à¦¸à¦¾à¦œà¦¸à¦œà§à¦œà¦¾
class _ConstellationsPainter extends CustomPainter {
  const _ConstellationsPainter();

  static const List<List<Offset>> _patterns = [
    // à¦¸à¦ªà§à¦¤à¦°à§à¦·à¦¿à¦®à¦£à§à¦¡à¦² (Ursa Major) â€” à¦¸à¦°à¦²à§€à¦•à§ƒà¦¤ "saucepan" à¦†à¦•à§ƒà¦¤à¦¿
    [
      Offset(0.12, 0.14),
      Offset(0.17, 0.12),
      Offset(0.22, 0.135),
      Offset(0.27, 0.155),
      Offset(0.27, 0.19),
      Offset(0.22, 0.20),
      Offset(0.19, 0.175),
    ],
    // à¦•à¦¾à¦²à¦ªà§à¦°à§à¦· (Orion) â€” à¦¸à¦°à¦²à§€à¦•à§ƒà¦¤ à¦¬à§‡à¦²à§à¦Ÿ à¦“ à¦•à¦¾à¦à¦§/à¦ªà¦¾
    [
      Offset(0.68, 0.10),
      Offset(0.80, 0.09),
      Offset(0.72, 0.155),
      Offset(0.76, 0.155),
      Offset(0.80, 0.155),
      Offset(0.70, 0.22),
      Offset(0.82, 0.22),
    ],
  ];

  @override
  void paint(Canvas canvas, Size size) {
    final dot = Paint()..color = Colors.white.withValues(alpha: 0.75);
    final line = Paint()
      ..color = Colors.white.withValues(alpha: 0.16)
      ..strokeWidth = 0.8;
    for (final pattern in _patterns) {
      for (int i = 0; i < pattern.length; i++) {
        final p = Offset(
          pattern[i].dx * size.width,
          pattern[i].dy * size.height,
        );
        canvas.drawCircle(p, 1.4, dot);
        if (i > 0) {
          final prev = Offset(
            pattern[i - 1].dx * size.width,
            pattern[i - 1].dy * size.height,
          );
          canvas.drawLine(prev, p, line);
        }
      }
    }
  }

  @override
  bool shouldRepaint(covariant _ConstellationsPainter old) => false;
}

class _DustPuff {
  final Offset pos;
  final double radius;
  final double alpha;
  final Color color;
  const _DustPuff(this.pos, this.radius, this.alpha, this.color);
}

class _NebulaBlob {
  final Offset pos;
  final double radius;
  final Color color;
  final double alpha;
  const _NebulaBlob(this.pos, this.radius, this.color, this.alpha);
}

/// à¦¨à§€à¦¹à¦¾à¦°à¦¿à¦•à¦¾ à¦“ à¦›à¦¾à¦¯à¦¼à¦¾à¦ªà¦¥ â€” à¦¨à¦°à¦®, à¦›à¦¡à¦¼à¦¾à¦¨à§‹ à¦†à¦²à§‹à¦° à¦®à§‡à¦˜
class DeepSkyPainter extends CustomPainter {
  final List<_NebulaBlob> nebulae;
  final List<_DustPuff> milkyWay;
  DeepSkyPainter(this.nebulae, this.milkyWay);

  @override
  void paint(Canvas canvas, Size size) {
    final minSide = math.min(size.width, size.height);

    for (final n in nebulae) {
      final center = Offset(n.pos.dx * size.width, n.pos.dy * size.height);
      final r = n.radius * minSide;
      final rect = Rect.fromCircle(center: center, radius: r);
      final paint = Paint()
        ..shader = RadialGradient(
          colors: [
            n.color.withValues(alpha: n.alpha),
            n.color.withValues(alpha: n.alpha * 0.45),
            n.color.withValues(alpha: 0.0),
          ],
          stops: const [0.0, 0.45, 1.0],
        ).createShader(rect);
      canvas.drawCircle(center, r, paint);
    }

    for (final d in milkyWay) {
      final center = Offset(d.pos.dx * size.width, d.pos.dy * size.height);
      final r = d.radius * minSide;
      final rect = Rect.fromCircle(center: center, radius: r);
      final paint = Paint()
        ..shader = RadialGradient(
          colors: [
            d.color.withValues(alpha: d.alpha),
            d.color.withValues(alpha: 0.0),
          ],
        ).createShader(rect);
      canvas.drawCircle(center, r, paint);
    }
  }

  @override
  bool shouldRepaint(covariant DeepSkyPainter oldDelegate) => false;
}

/// à¦¤à¦¾à¦°à¦¾ â€” à¦ªà§à¦°à¦¤à¦¿à¦Ÿà¦¿ à¦¨à¦¿à¦œà¦¸à§à¦¬ à¦›à¦¨à§à¦¦à§‡ à¦®à¦¿à¦Ÿà¦®à¦¿à¦Ÿ à¦•à¦°à§‡; à¦‰à¦œà§à¦œà§à¦¬à¦²à¦—à§à¦²à§‹ à¦†à¦­à¦¾ à¦“ à¦°à¦¶à§à¦®à¦¿ à¦›à¦¡à¦¼à¦¾à¦¯à¦¼
class StarsPainter extends CustomPainter {
  final List<_StarSpec> stars;
  final Animation<double> twinkle;
  StarsPainter(this.stars, this.twinkle) : super(repaint: twinkle);

  @override
  void paint(Canvas canvas, Size size) {
    final t = twinkle.value;
    final dot = Paint();
    final spike = Paint()..strokeCap = StrokeCap.round;

    for (final s in stars) {
      final center = Offset(s.pos.dx * size.width, s.pos.dy * size.height);
      // à¦®à¦¿à¦Ÿà¦®à¦¿à¦Ÿ: à¦ªà§à¦°à¦¤à¦¿à¦Ÿà¦¿ à¦¤à¦¾à¦°à¦¾à¦° à¦¨à¦¿à¦œà¦¸à§à¦¬ à¦—à¦¤à¦¿ à¦“ à¦¶à§à¦°à§à¦° à¦…à¦¬à¦¸à§à¦¥à¦¾à¦¨
      final wave = math.sin(
        (t * s.twinkleSpeed + s.twinklePhase) * 2 * math.pi,
      );
      final alpha = (s.baseAlpha * (0.72 + 0.28 * wave)).clamp(0.0, 1.0);

      // à¦‰à¦œà§à¦œà§à¦¬à¦² à¦¤à¦¾à¦°à¦¾à¦° à¦šà¦¾à¦°à¦ªà¦¾à¦¶à§‡ à¦¨à¦°à¦® à¦†à¦­à¦¾
      if (s.bright) {
        final glowR = s.radius * 5.5;
        final rect = Rect.fromCircle(center: center, radius: glowR);
        canvas.drawCircle(
          center,
          glowR,
          Paint()
            ..shader = RadialGradient(
              colors: [
                s.color.withValues(alpha: alpha * 0.32),
                s.color.withValues(alpha: 0.0),
              ],
            ).createShader(rect),
        );
      }

      dot.color = s.color.withValues(alpha: alpha);
      canvas.drawCircle(center, s.radius, dot);

      // à¦¸à¦¬à¦šà§‡à¦¯à¦¼à§‡ à¦‰à¦œà§à¦œà§à¦¬à¦² à¦¤à¦¾à¦°à¦¾à¦¯à¦¼ à¦•à§à¦¯à¦¾à¦®à§‡à¦°à¦¾à¦° à¦®à¦¤à§‹ à¦¸à§‚à¦•à§à¦·à§à¦® à¦°à¦¶à§à¦®à¦¿
      if (s.bright && s.radius > 2.0) {
        spike
          ..color = s.color.withValues(alpha: alpha * 0.5)
          ..strokeWidth = 0.7;
        final len = s.radius * 4.2;
        canvas.drawLine(
          center.translate(-len, 0),
          center.translate(len, 0),
          spike,
        );
        canvas.drawLine(
          center.translate(0, -len),
          center.translate(0, len),
          spike,
        );
      }
    }
  }

  @override
  bool shouldRepaint(covariant StarsPainter oldDelegate) => false;
}

