// =====================================================================
// PHASE-10: HOME LIVE PANCHANG TIMING SYSTEM
// à¦¬à¦°à§à¦¤à¦®à¦¾à¦¨ à¦¸à¦®à§Ÿ à¦…à¦¨à§à¦¯à¦¾à§Ÿà§€ à¦‰à§Žà¦¸à¦¬/à¦¤à¦¿à¦¥à¦¿/à¦°à¦¾à¦¹à§à¦•à¦¾à¦²/à¦…à¦­à¦¿à¦œà¦¿à§Ž/à¦¯à¦®à¦—à¦£à§à¦¡/à¦—à§à¦²à¦¿à¦•à§‡à¦°
// active/next timing live countdown-à¦¸à¦¹ à¦¦à§‡à¦–à¦¾à§Ÿà¥¤ à¦¸à¦®à§Ÿ à¦¶à§‡à¦· à¦¹à¦²à§‡à¦‡ à¦ªà¦°à§‡à¦° timing
// à¦¨à¦¿à¦œà§‡ à¦¥à§‡à¦•à§‡ à¦¸à¦¾à¦®à¦¨à§‡ à¦†à¦¸à§‡à¥¤ à¦¤à¦¿à¦¥à¦¿à¦° start/end existing tithiTiming() à¦¹à¦¿à¦¸à§‡à¦¬ à¦¥à§‡à¦•à§‡à¦‡à¥¤
// =====================================================================

class _LivePanchangWindow {
  final String icon;
  final String name;
  final DateTime start;
  final DateTime end;
  final bool caution;

  const _LivePanchangWindow({
    required this.icon,
    required this.name,
    required this.start,
    required this.end,
    this.caution = false,
  });
}

class _HomeLiveTimingSystem extends StatefulWidget {
  const _HomeLiveTimingSystem();

  @override
  State<_HomeLiveTimingSystem> createState() => _HomeLiveTimingSystemState();
}

class _HomeLiveTimingSystemState extends State<_HomeLiveTimingSystem> {
  Timer? _timer;
  DateTime _now = DateTime.now();

  @override
  void initState() {
    super.initState();
    _timer = Timer.periodic(const Duration(seconds: 1), (_) {
      if (!mounted) return;
      setState(() => _now = DateTime.now());
    });
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  // sunTimes()/rahuKalam() à¦¥à§‡à¦•à§‡ à¦†à¦¸à¦¾ DateTime-à¦—à§à¦²à§‹ IST clock-value à¦§à¦°à§‡
  // UTC-marked à¦¹à¦¤à§‡ à¦ªà¦¾à¦°à§‡à¥¤ Countdown-à¦à¦° à¦œà¦¨à§à¦¯ actual local instant-à¦ à¦†à¦¨à¦¾ à¦¹à§Ÿà¥¤
  DateTime _actual(DateTime value) {
    if (!value.isUtc) return value;
    return value.subtract(const Duration(hours: 5, minutes: 30)).toLocal();
  }

  String _countdown(Duration d) {
    if (d.isNegative) d = Duration.zero;
    final total = d.inSeconds;
    final days = total ~/ 86400;
    final hours = (total % 86400) ~/ 3600;
    final minutes = (total % 3600) ~/ 60;
    final seconds = total % 60;
    if (days > 0) {
      return '${bnNum(days)} à¦¦à¦¿à¦¨ ${bnNum(hours)} à¦˜ ${bnNum(minutes)} à¦®à¦¿';
    }
    if (hours > 0) {
      return '${bnNum(hours)} à¦˜ ${bnNum(minutes)} à¦®à¦¿ ${bnNum(seconds)} à¦¸à§‡';
    }
    return '${bnNum(minutes)} à¦®à¦¿ ${bnNum(seconds)} à¦¸à§‡';
  }

  String _dateLabel(DateTime d) {
    final info = BengaliDateUtil.monthInfoFor(d);
    final bnDay = d.difference(info.start).inDays + 1;
    return '${bnNum(bnDay)} ${info.name} â€¢ ${bnNum(d.day)} ${gregMonthBn(d.month)}';
  }

  bool _isTithiFestival(CalendarEvent e) {
    if (const {'ekadashi', 'purnima', 'amabasya'}.contains(e.category)) {
      return true;
    }
    const keys = [
      'à¦¦à§à¦°à§à¦—à¦¾',
      'à¦·à¦·à§à¦ à§€',
      'à¦¸à¦ªà§à¦¤à¦®à§€',
      'à¦…à¦·à§à¦Ÿà¦®à§€',
      'à¦¨à¦¬à¦®à§€',
      'à¦¦à¦¶à¦®à§€',
      'à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾',
      'à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾',
      'à¦à¦•à¦¾à¦¦à¦¶à§€',
      'à¦œà¦¨à§à¦®à¦¾à¦·à§à¦Ÿà¦®à§€',
      'à¦•à¦¾à¦²à§€à¦ªà§‚à¦œà¦¾',
      'à¦¦à§€à¦ªà¦¾à¦¬à¦²à¦¿',
      'à¦²à¦•à§à¦·à§à¦®à§€à¦ªà§‚à¦œà¦¾',
      'à¦¸à¦°à¦¸à§à¦¬à¦¤à§€',
      'à¦¶à¦¿à¦¬à¦°à¦¾à¦¤à§à¦°à¦¿',
      'à¦°à¦¾à¦® à¦¨à¦¬à¦®à§€',
      'à¦¦à§‹à¦²',
      'à¦®à¦¹à¦¾à¦²à¦¯à¦¼à¦¾',
      'à¦§à¦¨à¦¤à§‡à¦°à¦¾à¦¸',
      'à¦­à¦¾à¦‡à¦«à§‹à¦à¦Ÿà¦¾',
      'à¦—à¦£à§‡à¦¶',
      'à¦°à¦¥à¦¯à¦¾à¦¤à§à¦°à¦¾',
      'à¦‰à¦²à§à¦Ÿà§‹à¦°à¦¥',
    ];
    return keys.any(e.label.contains);
  }

  (DateTime start, DateTime end) _festivalTithiTiming(
    DateTime day,
    CalendarEvent event,
  ) {
    final sun = PanchangCalculator.sunTimes(
      day,
      lat: AppLocation.lat,
      lon: AppLocation.lon,
    );

    DateTime ref;
    if (event.label.contains('à¦•à¦¾à¦²à§€à¦ªà§‚à¦œà¦¾') ||
        event.label.contains('à¦¶à¦¿à¦¬à¦°à¦¾à¦¤à§à¦°à¦¿')) {
      ref = DateTime(day.year, day.month, day.day, 23, 59);
    } else if (event.label.contains('à¦§à¦¨à¦¤à§‡à¦°à¦¾à¦¸')) {
      ref = _actual(sun.sunset);
    } else {
      ref = _actual(sun.sunrise);
    }

    final timing = PanchangCalculator.tithiTiming(ref);
    return (_actual(timing.$1), _actual(timing.$2));
  }

  List<_LivePanchangWindow> _todayWindows(DateTime now) {
    final rahu = PanchangCalculator.rahuKalam(
      now,
      lat: AppLocation.lat,
      lon: AppLocation.lon,
    );
    final yama = PanchangCalculator.yamagandaKalam(
      now,
      lat: AppLocation.lat,
      lon: AppLocation.lon,
    );
    final gulika = PanchangCalculator.gulikaKalam(
      now,
      lat: AppLocation.lat,
      lon: AppLocation.lon,
    );
    final abhijit = PanchangCalculator.abhijitMuhurta(
      now,
      lat: AppLocation.lat,
      lon: AppLocation.lon,
    );

    final result = <_LivePanchangWindow>[
      _LivePanchangWindow(
        icon: 'â³',
        name: 'à¦°à¦¾à¦¹à§à¦•à¦¾à¦²',
        start: _actual(rahu['start']!),
        end: _actual(rahu['end']!),
        caution: true,
      ),
      _LivePanchangWindow(
        icon: 'âš ï¸',
        name: 'à¦¯à¦®à¦—à¦£à§à¦¡',
        start: _actual(yama['start']!),
        end: _actual(yama['end']!),
        caution: true,
      ),
      _LivePanchangWindow(
        icon: 'ðŸª',
        name: 'à¦—à§à¦²à¦¿à¦• à¦•à¦¾à¦²',
        start: _actual(gulika['start']!),
        end: _actual(gulika['end']!),
        caution: true,
      ),
    ];

    if (abhijit['applicable'] == true) {
      result.add(
        _LivePanchangWindow(
          icon: 'â˜€ï¸',
          name: 'à¦…à¦­à¦¿à¦œà¦¿à§Ž à¦®à§à¦¹à§‚à¦°à§à¦¤',
          start: _actual(abhijit['start'] as DateTime),
          end: _actual(abhijit['end'] as DateTime),
        ),
      );
    }

    result.sort((a, b) => a.start.compareTo(b.start));
    return result;
  }

  CalendarEvent? _nextSpecialEvent(DateTime now) {
    for (int i = 0; i <= 60; i++) {
      final day = DateTime(now.year, now.month, now.day).add(Duration(days: i));
      final events = BengaliCalendarData.eventsFor(
        day,
      ).where((e) => e.category == 'general' || _isTithiFestival(e)).toList();
      if (events.isNotEmpty) return events.first;
    }
    return null;
  }

  (DateTime date, CalendarEvent event)? _nextSpecialWithDate(DateTime now) {
    for (int i = 0; i <= 60; i++) {
      final day = DateTime(now.year, now.month, now.day).add(Duration(days: i));
      final events = BengaliCalendarData.eventsFor(
        day,
      ).where((e) => e.category == 'general' || _isTithiFestival(e)).toList();
      if (events.isNotEmpty) return (day, events.first);
    }
    return null;
  }

  Widget _smallTimeChip(
    String icon,
    String title,
    DateTime start,
    DateTime end, {
    bool caution = false,
  }) {
    final active = !_now.isBefore(start) && _now.isBefore(end);
    final upcoming = _now.isBefore(start);
    final color = caution ? const Color(0xFFFF9C6B) : const Color(0xFFFFD36E);

    return Container(
      margin: const EdgeInsets.only(right: 8),
      padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 6),
      decoration: BoxDecoration(
        color: active
            ? color.withValues(alpha: 0.18)
            : Colors.white.withValues(alpha: 0.06),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(
          color: active
              ? color.withValues(alpha: 0.65)
              : Colors.white.withValues(alpha: 0.12),
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            '$icon $title${active ? ' â€¢ à¦šà¦²à¦›à§‡' : ''}',
            style: TextStyle(
              color: active ? color : Colors.white,
              fontSize: 10.5,
              fontWeight: FontWeight.w800,
            ),
          ),
          const SizedBox(height: 2),
          Text(
            active
                ? 'à¦¶à§‡à¦· ${_countdown(end.difference(_now))} à¦ªà¦°à§‡'
                : upcoming
                ? '${bnTime12(start)}â€“${bnTime12(end)}'
                : 'à¦†à¦œ à¦¶à§‡à¦·',
            style: const TextStyle(color: Colors.white60, fontSize: 9.5),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final now = _now;
    final tithi = PanchangCalculator.tithiFor(now);
    final tithiTiming = PanchangCalculator.tithiTiming(now);
    final tithiStart = _actual(tithiTiming.$1);
    final tithiEnd = _actual(tithiTiming.$2);
    final nextTithi = PanchangCalculator.tithiFor(
      tithiEnd.add(const Duration(minutes: 2)),
    );

    final todayEvents = BengaliCalendarData.eventsFor(now);
    CalendarEvent? festival;
    for (final e in todayEvents) {
      if (_isTithiFestival(e)) {
        festival = e;
        break;
      }
    }

    (DateTime start, DateTime end)? festivalTiming;
    if (festival != null) {
      festivalTiming = _festivalTithiTiming(now, festival);
    }

    DateTime? sandhiStart;
    DateTime? sandhiEnd;
    if (festival != null &&
        festival.label.contains('à¦®à¦¹à¦¾à¦·à§à¦Ÿà¦®à§€')) {
      final transition = festivalTiming!.$2;
      sandhiStart = transition.subtract(const Duration(minutes: 24));
      sandhiEnd = transition.add(const Duration(minutes: 24));
    }

    final windows = _todayWindows(now);
    _LivePanchangWindow? activeWindow;
    for (final w in windows) {
      if (!now.isBefore(w.start) && now.isBefore(w.end)) {
        activeWindow = w;
        break;
      }
    }
    _LivePanchangWindow? nextWindow;
    for (final w in windows) {
      if (now.isBefore(w.start)) {
        nextWindow = w;
        break;
      }
    }

    String mainIcon = 'ðŸ•‰';
    String mainTitle;
    String mainSubtitle;
    DateTime mainTarget;
    bool mainCaution = false;

    if (sandhiStart != null && sandhiEnd != null && now.isBefore(sandhiEnd)) {
      mainIcon = 'ðŸ”±';
      if (now.isBefore(sandhiStart)) {
        mainTitle = 'à¦¸à¦¨à§à¦§à¦¿à¦ªà§‚à¦œà¦¾ à¦¶à§à¦°à§ à¦¹à¦¤à§‡';
        mainTarget = sandhiStart;
      } else {
        mainTitle =
            'à¦¸à¦¨à§à¦§à¦¿à¦ªà§‚à¦œà¦¾ à¦šà¦²à¦›à§‡ â€¢ à¦¶à§‡à¦· à¦¹à¦¤à§‡';
        mainTarget = sandhiEnd;
      }
      mainSubtitle =
          '${bnTime12(sandhiStart)}â€“${bnTime12(sandhiEnd)} â€¢ à¦®à¦¹à¦¾à¦·à§à¦Ÿà¦®à§€â†’à¦¨à¦¬à¦®à§€ à¦¸à¦¨à§à¦§à¦¿à¦•à§à¦·à¦£';
    } else if (festival != null &&
        festivalTiming != null &&
        !now.isBefore(festivalTiming.$1) &&
        now.isBefore(festivalTiming.$2)) {
      mainIcon = festival.icon;
      mainTitle =
          '${festival.label} à¦¤à¦¿à¦¥à¦¿ à¦šà¦²à¦›à§‡ â€¢ à¦¶à§‡à¦· à¦¹à¦¤à§‡';
      mainTarget = festivalTiming.$2;
      mainSubtitle =
          '${bnTime12(festivalTiming.$1)}â€“${bnTime12(festivalTiming.$2)}';
    } else if (activeWindow != null) {
      mainIcon = activeWindow.icon;
      mainTitle = '${activeWindow.name} à¦šà¦²à¦›à§‡ â€¢ à¦¶à§‡à¦· à¦¹à¦¤à§‡';
      mainTarget = activeWindow.end;
      mainSubtitle =
          '${bnTime12(activeWindow.start)}â€“${bnTime12(activeWindow.end)}';
      mainCaution = activeWindow.caution;
    } else if (nextWindow != null) {
      mainIcon = nextWindow.icon;
      mainTitle = '${nextWindow.name} à¦¶à§à¦°à§ à¦¹à¦¤à§‡';
      mainTarget = nextWindow.start;
      mainSubtitle =
          '${bnTime12(nextWindow.start)}â€“${bnTime12(nextWindow.end)}';
      mainCaution = nextWindow.caution;
    } else {
      mainIcon = 'ðŸŒ™';
      mainTitle = '${tithi.name} à¦¤à¦¿à¦¥à¦¿ à¦¶à§‡à¦· à¦¹à¦¤à§‡';
      mainTarget = tithiEnd;
      mainSubtitle =
          'à¦ªà¦°à§‡à¦° à¦¤à¦¿à¦¥à¦¿: ${nextTithi.paksha} ${nextTithi.name} â€¢ ${bnTime12(tithiEnd)} à¦¥à§‡à¦•à§‡';
    }

    final nextSpecial = _nextSpecialWithDate(now);
    final accent = mainCaution
        ? const Color(0xFFFF9C6B)
        : const Color(0xFFFFD36E);

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: const Color(0xFF06152D).withValues(alpha: 0.58),
        borderRadius: BorderRadius.circular(20),
        border: Border.all(color: accent.withValues(alpha: 0.35)),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: 0.16),
            blurRadius: 16,
            offset: const Offset(0, 8),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Expanded(
                child: Text(
                  'â±ï¸ à¦²à¦¾à¦‡à¦­ à¦ªà¦žà§à¦œà¦¿à¦•à¦¾ à¦Ÿà¦¾à¦‡à¦®à¦¿à¦‚',
                  style: TextStyle(
                    color: Colors.white,
                    fontSize: 14,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 3),
                decoration: BoxDecoration(
                  color: const Color(0xFFE53935).withValues(alpha: 0.18),
                  borderRadius: BorderRadius.circular(999),
                  border: Border.all(
                    color: const Color(0xFFE53935).withValues(alpha: 0.5),
