class _TickerBar extends StatefulWidget {
  @override
  State<_TickerBar> createState() => _TickerBarState();
}

class _TickerBarState extends State<_TickerBar>
    with SingleTickerProviderStateMixin {
  late final ScrollController _controller;

  String _buildText() {
    final now = DateTime.now();
    final sun = PanchangCalculator.sunTimes(now);
    final tithi = PanchangCalculator.tithiFor(now);
    final nakIdx = PanchangCalculator.nakshatraIndexFor(now);
    final rahu = PanchangCalculator.rahuKalam(now);
    final abhijit = PanchangCalculator.abhijitMuhurta(now);
    final abhijitText = abhijit['applicable'] == true
        ? 'â˜€ï¸ à¦…à¦­à¦¿à¦œà¦¿à§Ž à¦®à§à¦¹à§‚à¦°à§à¦¤ ${bnTime12(abhijit['start'] as DateTime)}â€“${bnTime12(abhijit['end'] as DateTime)} â€¢ '
        : '';
    return 'â˜€ï¸ à¦¸à§‚à¦°à§à¦¯à§‹à¦¦à¦¯à¦¼ ${bnTime12(sun.sunrise)} â€¢ '
        'ðŸŒ‡ à¦¸à§‚à¦°à§à¦¯à¦¾à¦¸à§à¦¤ ${bnTime12(sun.sunset)} â€¢ '
        'â³ à¦°à¦¾à¦¹à§à¦•à¦¾à¦² ${bnTime12(rahu['start']!)}â€“${bnTime12(rahu['end']!)} â€¢ '
        '${abhijitText}à¦†à¦œ ${tithi.name} à¦¤à¦¿à¦¥à¦¿ â€¢ '
        'à¦¨à¦•à§à¦·à¦¤à§à¦°: ${PanchangCalculator.nakshatraNames[nakIdx]}';
  }

  @override
  void initState() {
    super.initState();
    _controller = ScrollController();
    WidgetsBinding.instance.addPostFrameCallback((_) => _beginScroll());
  }

  void _beginScroll() {
    if (!mounted || !_controller.hasClients) return;
    final max = _controller.position.maxScrollExtent;
    _controller
        .animateTo(
          max,
          duration: const Duration(seconds: 14),
          curve: Curves.linear,
        )
        .then((_) {
          if (!mounted) return;
          _controller.jumpTo(0);
          Future.delayed(const Duration(milliseconds: 300), () {
            if (mounted) _beginScroll();
          });
        });
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Container(
      height: 40,
      alignment: Alignment.centerLeft,
      padding: const EdgeInsets.symmetric(horizontal: 12),
      decoration: BoxDecoration(
        color: const Color(0xFF061226).withValues(alpha: 0.8),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: Colors.white.withValues(alpha: 0.13)),
      ),
      child: SingleChildScrollView(
        controller: _controller,
        scrollDirection: Axis.horizontal,
        physics: const NeverScrollableScrollPhysics(),
        child: Text(
          _buildText(),
          style: const TextStyle(color: Colors.white70, fontSize: 13),
        ),
      ),
    );
  }
}

