/// "à¦†à¦œ" / "à¦•à¦¾à¦²" / "X à¦¦à¦¿à¦¨ à¦¬à¦¾à¦•à¦¿" à¦•à¦¾à¦‰à¦¨à§à¦Ÿà¦¡à¦¾à¦‰à¦¨ à¦†à¦° à¦à¦•à¦Ÿà¦¾ à¦¶à§‡à¦¯à¦¼à¦¾à¦°-à¦¬à¦¾à¦Ÿà¦¨à¦“ à¦¦à§‡à¦–à¦¾à¦¯à¦¼à¥¤
class _UpcomingFestivalsCard extends StatelessWidget {
  final int count;
  const _UpcomingFestivalsCard({this.count = 3});

  String _countdownLabel(int daysLeft) {
    if (daysLeft <= 0) return 'à¦†à¦œ';
    if (daysLeft == 1) return 'à¦•à¦¾à¦²';
    return '${bnNum(daysLeft)} à¦¦à¦¿à¦¨ à¦¬à¦¾à¦•à¦¿';
  }

  void _shareFestival(
    String icon,
    String title,
    String date,
    String countdown,
  ) {
    Share.share(
      '$icon à¦¶à§à¦­ $title\nðŸ“… $date â€¢ $countdown\n\nðŸ“² à¦¬à¦¾à¦‚à¦²à¦¾ à¦ªà¦žà§à¦œà¦¿à¦•à¦¾ à¦…à§à¦¯à¦¾à¦ª à¦¥à§‡à¦•à§‡',
      subject: title,
    );
  }

  @override
  Widget build(BuildContext context) {
    final festivals = BengaliCalendarData.upcomingFestivals(count: count);
    final boxDecoration = BoxDecoration(
      gradient: const LinearGradient(
        colors: [Color(0xFF4D220D), Color(0xFF15152F)],
      ),
      borderRadius: BorderRadius.circular(18),
      border: Border.all(color: const Color(0xFFF3B35D).withValues(alpha: 0.4)),
    );

    if (festivals.isEmpty) {
      return Container(
        padding: const EdgeInsets.all(14),
        decoration: boxDecoration,
        child: const Text(
          'ðŸŒ à¦•à§‹à¦¨à§‹ à¦¤à¦¥à§à¦¯ à¦¨à§‡à¦‡ â€” à¦ªà¦°à§‡ à¦¦à§‡à¦–à§à¦¨',
          style: TextStyle(color: Colors.white70, fontSize: 14),
        ),
      );
    }

    return Container(
      decoration: boxDecoration,
      padding: const EdgeInsets.symmetric(horizontal: 14),
      child: Column(
        children: List.generate(festivals.length, (i) {
          final f = festivals[i];
          final icon = f['icon'] ?? 'ðŸŽ‰';
          final title = f['title'] ?? '';
          final date = f['date'] ?? 'à¦¶à§€à¦˜à§à¦°à¦‡';
          final daysLeft = int.tryParse(f['daysLeft'] ?? '') ?? 0;
          final countdown = _countdownLabel(daysLeft);
          // à¦‰à§Žà¦¸à¦¬à§‡à¦° à¦œà¦¨à§à¦¯ à¦…à§à¦¯à¦¾à¦ªà§‡à¦° à¦¨à¦¿à¦œà¦¸à§à¦¬ à¦†à¦à¦•à¦¾ illustration (à¦¥à¦¾à¦•à¦²à§‡)
          final motif = PanjikaArt.motifFor(title, 'general');
          return Container(
            padding: const EdgeInsets.symmetric(vertical: 11),
            decoration: BoxDecoration(
              border: i == festivals.length - 1
                  ? null
                  : Border(
                      bottom: BorderSide(
                        color: Colors.white.withValues(alpha: 0.08),
                      ),
                    ),
            ),
            child: Row(
              children: [
                if (motif != null) ...[
                  Container(
                    padding: const EdgeInsets.all(5),
                    decoration: BoxDecoration(
                      color: Colors.white.withValues(alpha: 0.06),
                      borderRadius: BorderRadius.circular(10),
                    ),
                    child: PanjikaArt(motif, size: 28),
                  ),
                  const SizedBox(width: 10),
                ],
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
