class WorldClockScreen extends StatefulWidget {
  const WorldClockScreen({super.key});
  @override
  State<WorldClockScreen> createState() => _WorldClockScreenState();
}

class _WorldClockScreenState extends State<WorldClockScreen> {
  Timer? _timer;

  @override
  void initState() {
    super.initState();
    _timer = Timer.periodic(const Duration(seconds: 1), (_) {
      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  /// [city]-à¦° à¦ªà§à¦°à¦•à§ƒà¦¤ à¦¸à§à¦¥à¦¾à¦¨à§€à¦¯à¦¼ à¦¸à¦®à¦¯à¦¼ â€” à¦®à§‹à¦¬à¦¾à¦‡à¦²/à¦¡à§‡à¦¸à§à¦•à¦Ÿà¦ªà§‡ IANA à¦Ÿà¦¾à¦‡à¦®à¦œà§‹à¦¨ à¦¡à§‡à¦Ÿà¦¾à¦¬à§‡à¦¸
  /// (DST-à¦¸à¦¹ real à¦¹à¦¿à¦¸à§‡à¦¬) à¦¥à§‡à¦•à§‡, à¦“à¦¯à¦¼à§‡à¦¬à§‡ fallback à¦«à¦¿à¦•à§à¦¸à¦¡ à¦…à¦«à¦¸à§‡à¦Ÿ à¦¥à§‡à¦•à§‡
  DateTime _localTime(_WorldCity city) {
    if (!kIsWeb) {
      try {
        final loc = tz.getLocation(city.tzId);
        final t = tz.TZDateTime.now(loc);
        return DateTime(t.year, t.month, t.day, t.hour, t.minute, t.second);
      } catch (_) {}
    }
    return DateTime.now().toUtc().add(
      Duration(minutes: (city.fallbackOffset * 60).round()),
    );
  }

  double _offsetHours(_WorldCity city) {
    if (!kIsWeb) {
      try {
        final loc = tz.getLocation(city.tzId);
        return tz.TZDateTime.now(loc).timeZoneOffset.inMinutes / 60.0;
      } catch (_) {}
    }
    return city.fallbackOffset;
  }

  String _bnClock(DateTime dt) {
    final h12raw = dt.hour % 12;
    final h12 = h12raw == 0 ? 12 : h12raw;
    final ampm = dt.hour < 12 ? 'AM' : 'PM';
    return '${bnDigits(h12.toString())}:${bnDigits(dt.minute.toString().padLeft(2, '0'))}:${bnDigits(dt.second.toString().padLeft(2, '0'))} $ampm';
  }

  String _diffText(double cityOffset, double indiaOffset) {
    final diff = cityOffset - indiaOffset;
    if (diff.abs() < 0.01)
      return 'à¦­à¦¾à¦°à¦¤à§‡à¦° à¦¸à¦¾à¦¥à§‡ à¦¸à¦®à¦¯à¦¼ à¦à¦•à¦‡';
    final absDiff = diff.abs();
    final hours = absDiff.truncate();
    final minutes = ((absDiff - hours) * 60).round();
    final hm = minutes == 0
        ? '${bnNum(hours)} à¦˜à¦£à§à¦Ÿà¦¾'
        : '${bnNum(hours)} à¦˜à¦£à§à¦Ÿà¦¾ ${bnNum(minutes)} à¦®à¦¿à¦¨à¦¿à¦Ÿ';
    return diff > 0
        ? 'à¦­à¦¾à¦°à¦¤à§‡à¦° à¦šà§‡à¦¯à¦¼à§‡ $hm à¦à¦—à¦¿à¦¯à¦¼à§‡'
        : 'à¦­à¦¾à¦°à¦¤à§‡à¦° à¦šà§‡à¦¯à¦¼à§‡ $hm à¦ªà¦¿à¦›à¦¿à¦¯à¦¼à§‡';
  }

  /// à¦¦à¦¿à¦¨ à¦¨à¦¾ à¦°à¦¾à¦¤ â€” à¦¸à¦¾à¦§à¦¾à¦°à¦£ à¦˜à¦¡à¦¼à¦¿à¦° à¦¸à¦®à¦¯à¦¼ à¦§à¦°à§‡ (à¦¸à¦•à¦¾à¦² à§¬à¦Ÿà¦¾â€“à¦¸à¦¨à§à¦§à§à¦¯à¦¾ à§¬à¦Ÿà¦¾ à¦¦à¦¿à¦¨)
  (String, bool) _dayNight(DateTime local) {
    final h = local.hour;
    final isDay = h >= 6 && h < 18;
    return (isDay ? 'â˜€ï¸ à¦¦à¦¿à¦¨' : 'ðŸŒ™ à¦°à¦¾à¦¤', isDay);
  }

  @override
  Widget build(BuildContext context) {
    final indiaOffset = _offsetHours(_worldCities.first);
    return CosmicBackground(
      child: Column(
        children: [
          const _ScreenHeader(title: 'ðŸŒ à¦¬à¦¿à¦¶à§à¦¬ à¦˜à¦¡à¦¼à¦¿'),
          Expanded(
            child: ListView.builder(
              padding: const EdgeInsets.all(16),
              itemCount: _worldCities.length,
              itemBuilder: (context, i) {
                final city = _worldCities[i];
                final local = _localTime(city);
                final offset = _offsetHours(city);
                final (dayNightLabel, isDay) = _dayNight(local);
                return Container(
                  margin: const EdgeInsets.only(bottom: 10),
                  padding: const EdgeInsets.all(14),
                  decoration: BoxDecoration(
                    color: Colors.white.withValues(alpha: 0.06),
                    borderRadius: BorderRadius.circular(16),
                    border: Border.all(
                      color: Colors.white.withValues(alpha: 0.1),
                    ),
                  ),
                  child: Row(
                    children: [
                      SizedBox(
                        width: 68,
                        height: 68,
                        child: CustomPaint(painter: _AnalogClockPainter(local)),
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Row(
                              children: [
                                Text(
                                  city.flag,
                                  style: const TextStyle(fontSize: 16),
                                ),
                                const SizedBox(width: 6),
                                Expanded(
                                  child: Text(
                                    city.name,
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: const TextStyle(
                                      color: Colors.white,
                                      fontWeight: FontWeight.w700,
                                      fontSize: 14,
                                    ),
                                  ),
                                ),
                              ],
                            ),
                            const SizedBox(height: 3),
                            Text(
                              i == 0
                                  ? dayNightLabel
                                  : '${_diffText(offset, indiaOffset)} â€¢ $dayNightLabel',
                              style: TextStyle(
                                color: isDay
                                    ? const Color(0xFFFFD36E)
                                    : Colors.white60,
                                fontSize: 11.5,
                              ),
                            ),
                          ],
                        ),
                      ),
                      const SizedBox(width: 8),
                      Text(
                        _bnClock(local),
                        style: const TextStyle(
                          color: Colors.white,
                          fontWeight: FontWeight.bold,
                          fontSize: 13,
                        ),
                      ),
                    ],
                  ),
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

