class _RashiWheelState extends State<_RashiWheel>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: const Duration(seconds: 70),
    )..repeat();
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    const size = 260.0;
    const labelRadius = size / 2 - 34;
    return SizedBox(
      width: size,
      height: size,
      child: AnimatedBuilder(
        animation: _controller,
        builder: (context, _) {
          final baseAngle = _controller.value * 2 * math.pi;
          return Stack(
            alignment: Alignment.center,
            children: [
              Container(
                width: size,
                height: size,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  gradient: RadialGradient(
                    colors: [
                      const Color(0xFFFFD36E).withValues(alpha: 0.10),
                      Colors.transparent,
                    ],
                  ),
                  border: Border.all(
                    color: Colors.white.withValues(alpha: 0.22),
                    width: 1.3,
                  ),
                ),
              ),
              Container(
                width: size - 60,
                height: size - 60,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  border: Border.all(
                    color: Colors.white.withValues(alpha: 0.14),
                  ),
                ),
              ),
              for (int i = 0; i < 12; i++)
                Transform.translate(
                  offset: Offset(
                    labelRadius * math.cos(baseAngle + i * 30 * math.pi / 180),
                    labelRadius * math.sin(baseAngle + i * 30 * math.pi / 180),
                  ),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        ContentData._rashiSymbols[i],
                        style: const TextStyle(
                          fontSize: 18,
                          color: Color(0xFFFFD36E),
                        ),
                      ),
                      Text(
                        PanchangCalculator.rashiNames[i],
                        style: const TextStyle(
                          fontSize: 11,
                          color: Colors.white,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                    ],
                  ),
                ),
              const Text('ðŸ”®', style: TextStyle(fontSize: 30)),
            ],
          );
        },
      ),
    );
  }
}

