class RashiScreen extends StatefulWidget {
  const RashiScreen({super.key});

  @override
  State<RashiScreen> createState() => _RashiScreenState();
}

class _RashiScreenState extends State<RashiScreen> {
  int _selectedIndex = 0;
  int _periodIndex = 0;
  int _compareIndex = 1;
  int? _savedRashiIndex;
  DateTime _now = DateTime.now();
  Timer? _ticker;

  static const _periods = [
    'à¦†à¦œ',
    'à¦¸à¦ªà§à¦¤à¦¾à¦¹',
    'à¦®à¦¾à¦¸',
    'à¦¬à¦›à¦°',
  ];
  static const _luckyColors = [
    'à¦²à¦¾à¦²',
    'à¦¸à¦¬à§à¦œ',
    'à¦¹à¦²à§à¦¦',
    'à¦¸à¦¾à¦¦à¦¾',
    'à¦¸à§‹à¦¨à¦¾à¦²à¦¿',
    'à¦¹à¦¾à¦²à¦•à¦¾ à¦¸à¦¬à§à¦œ',
    'à¦—à§‹à¦²à¦¾à¦ªà¦¿',
    'à¦®à§‡à¦°à§à¦¨',
    'à¦•à¦®à¦²à¦¾',
    'à¦¨à§€à¦²',
    'à¦†à¦•à¦¾à¦¶à¦¿',
    'à¦¬à§‡à¦—à§à¦¨à¦¿',
  ];
  static const _directions = [
    'à¦ªà§‚à¦°à§à¦¬',
    'à¦¦à¦•à§à¦·à¦¿à¦£-à¦ªà§‚à¦°à§à¦¬',
    'à¦‰à¦¤à§à¦¤à¦°',
    'à¦‰à¦¤à§à¦¤à¦°-à¦ªà§‚à¦°à§à¦¬',
    'à¦ªà§‚à¦°à§à¦¬',
    'à¦‰à¦¤à§à¦¤à¦°',
    'à¦ªà¦¶à§à¦šà¦¿à¦®',
    'à¦¦à¦•à§à¦·à¦¿à¦£',
    'à¦‰à¦¤à§à¦¤à¦°-à¦ªà§‚à¦°à§à¦¬',
    'à¦¦à¦•à§à¦·à¦¿à¦£',
    'à¦ªà¦¶à§à¦šà¦¿à¦®',
    'à¦‰à¦¤à§à¦¤à¦°',
  ];

  @override
  void initState() {
    super.initState();
    _loadSavedRashi();
    _ticker = Timer.periodic(const Duration(seconds: 1), (_) {
      if (mounted) setState(() => _now = DateTime.now());
    });
  }

  @override
  void dispose() {
    _ticker?.cancel();
    super.dispose();
  }

  Future<void> _loadSavedRashi() async {
    final prefs = await SharedPreferences.getInstance();
    final idx = prefs.getInt('rashi_intelligence_my_rashi');
    if (!mounted || idx == null || idx < 0 || idx > 11) return;
    setState(() {
      _savedRashiIndex = idx;
      _selectedIndex = idx;
      _compareIndex = idx == 11 ? 0 : idx + 1;
    });
  }

  Future<void> _saveMyRashi() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setInt('rashi_intelligence_my_rashi', _selectedIndex);
    if (!mounted) return;
    setState(() => _savedRashiIndex = _selectedIndex);
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          '${PanchangCalculator.rashiNames[_selectedIndex]} â€œà¦†à¦®à¦¾à¦° à¦°à¦¾à¦¶à¦¿â€ à¦¹à¦¿à¦¸à§‡à¦¬à§‡ à¦¸à§‡à¦­ à¦¹à§Ÿà§‡à¦›à§‡',
        ),
      ),
    );
  }

  int _scoreFor(int idx, DateTime day, int salt) {
    final tithi = PanchangCalculator.tithiFor(day).index;
    final nak = PanchangCalculator.nakshatraIndexFor(day);
    final moon = PanchangCalculator.rashiIndexFor(day);
    var score =
        56 +
        ((idx * 17 +
                day.day * 7 +
                day.month * 11 +
                tithi * 3 +
                nak +
                salt * 13) %
            35);
    if (moon == idx) score += 4;
    if ((moon - idx).abs() == 6) score -= 3;
    return score.clamp(45, 96).toInt();
  }

  int get _overallScore {
    if (_periodIndex == 0) return _scoreFor(_selectedIndex, _now, 0);
    if (_periodIndex == 1) {
      final values = List.generate(
        7,
        (i) => _scoreFor(_selectedIndex, _now.add(Duration(days: i)), i),
      );
      return (values.reduce((a, b) => a + b) / values.length).round();
    }
    if (_periodIndex == 2) {
      final values = List.generate(
        12,
        (i) => _scoreFor(_selectedIndex, _now.add(Duration(days: i * 2)), i),
      );
      return (values.reduce((a, b) => a + b) / values.length).round();
    }
    final values = List.generate(
      12,
      (i) => _scoreFor(_selectedIndex, DateTime(_now.year, i + 1, 15), i),
    );
    return (values.reduce((a, b) => a + b) / values.length).round();
  }

  String _scoreMessage(int score) {
    if (score >= 88)
      return 'à¦–à§à¦¬ à¦¶à¦•à§à¦¤à¦¿à¦¶à¦¾à¦²à§€ à¦¦à¦¿à¦¨ â€” à¦ªà¦°à¦¿à¦•à¦²à§à¦ªà¦¿à¦¤ à¦•à¦¾à¦œà§‡ à¦à¦—à§‹à¦¨à§‹à¦° à¦…à¦¨à§à¦•à§‚à¦² à¦‡à¦™à§à¦—à¦¿à¦¤à¥¤';
    if (score >= 78)
      return 'à¦­à¦¾à¦²à§‹ à¦—à¦¤à¦¿ à¦¥à¦¾à¦•à¦¬à§‡ â€” à¦—à§à¦°à§à¦¤à§à¦¬à¦ªà§‚à¦°à§à¦£ à¦•à¦¾à¦œ à¦§à§€à¦°à§‡ à¦“ à¦ªà¦°à¦¿à¦·à§à¦•à¦¾à¦°à¦­à¦¾à¦¬à§‡ à¦à¦—à§‹à¦¨à¥¤';
    if (score >= 66)
      return 'à¦®à¦¿à¦¶à§à¦° à¦¦à¦¿à¦¨ â€” à¦¸à¦®à§Ÿ à¦¬à§‡à¦›à§‡ à¦•à¦¾à¦œ à¦•à¦°à¦²à§‡ à¦«à¦² à¦­à¦¾à¦²à§‹ à¦¹à¦¤à§‡ à¦ªà¦¾à¦°à§‡à¥¤';
    if (score >= 55)
      return 'à¦¸à¦¤à¦°à§à¦• à¦ªà¦°à¦¿à¦•à¦²à§à¦ªà¦¨à¦¾à¦° à¦¦à¦¿à¦¨ â€” à¦¤à¦¾à§œà¦¾à¦¹à§à§œà§‹ à¦¨à¦¾ à¦•à¦°à§‡ à¦…à¦—à§à¦°à¦¾à¦§à¦¿à¦•à¦¾à¦° à¦ à¦¿à¦• à¦•à¦°à§à¦¨à¥¤';
    return 'à¦¶à¦¾à¦¨à§à¦¤ à¦“ à¦¸à¦‚à¦¯à¦¤ à¦¥à¦¾à¦•à§à¦¨ â€” à¦¬à§œ à¦¸à¦¿à¦¦à§à¦§à¦¾à¦¨à§à¦¤à§‡ à¦¬à¦¾à¦¸à§à¦¤à¦¬ à¦¤à¦¥à§à¦¯à¦•à§‡ à¦…à¦—à§à¦°à¦¾à¦§à¦¿à¦•à¦¾à¦° à¦¦à¦¿à¦¨à¥¤';
  }

  String _periodForecast() {
    final score = _overallScore;
    final rows =
        ContentData.categories['à¦°à¦¾à¦¶à¦¿à¦«à¦²'] ?? const <List<String>>[];
    final dailyText =
        _selectedIndex < rows.length && rows[_selectedIndex].length > 1
        ? rows[_selectedIndex][1]
        : _scoreMessage(score);
    switch (_periodIndex) {
      case 0:
        return '$dailyText ${_scoreMessage(score)}';
      case 1:
        return 'à¦à¦‡ à¦¸à¦ªà§à¦¤à¦¾à¦¹à§‡ à¦§à¦¾à¦°à¦¾à¦¬à¦¾à¦¹à¦¿à¦•à¦¤à¦¾, à¦¯à§‹à¦—à¦¾à¦¯à§‹à¦— à¦“ à¦¸à¦®à§Ÿ à¦¬à§à¦¯à¦¬à¦¸à§à¦¥à¦¾à¦ªà¦¨à¦¾ à¦¸à¦¬à¦šà§‡à§Ÿà§‡ à¦—à§à¦°à§à¦¤à§à¦¬à¦ªà§‚à¦°à§à¦£à¥¤ ${_scoreMessage(score)}';
      case 2:
        return 'à¦à¦‡ à¦®à¦¾à¦¸à§‡ à¦…à¦¸à¦®à¦¾à¦ªà§à¦¤ à¦•à¦¾à¦œ à¦—à§à¦›à¦¿à§Ÿà§‡ à¦¨à¦¤à§à¦¨ à¦²à¦•à§à¦·à§à¦¯ à¦§à¦°à¦¾à¦° à¦¸à§à¦¯à§‹à¦— à¦†à¦›à§‡à¥¤ à¦…à¦°à§à¦¥ à¦“ à¦¸à¦®à§à¦ªà¦°à§à¦•à§‡à¦° à¦•à§à¦·à§‡à¦¤à§à¦°à§‡ à¦­à¦¾à¦°à¦¸à¦¾à¦®à§à¦¯ à¦°à¦¾à¦–à§à¦¨à¥¤';
      default:
        return 'à¦à¦‡ à¦¬à¦›à¦°à§‡ à¦§à¦¾à¦ªà§‡ à¦§à¦¾à¦ªà§‡ à¦¸à§à¦¥à¦¾à§Ÿà§€ à¦…à¦—à§à¦°à¦—à¦¤à¦¿, à¦¶à§‡à¦–à¦¾ à¦à¦¬à¦‚ à¦¸à¦®à§à¦ªà¦°à§à¦•à§‡à¦° à¦—à§à¦£à¦—à¦¤ à¦‰à¦¨à§à¦¨à¦¤à¦¿à¦¤à§‡ à¦œà§‹à¦° à¦¦à¦¿à¦¨à¥¤ à¦¬à§œ à¦¸à¦¿à¦¦à§à¦§à¦¾à¦¨à§à¦¤à§‡ à¦¬à¦¾à¦¸à§à¦¤à¦¬ à¦ªà¦°à¦¿à¦•à¦²à§à¦ªà¦¨à¦¾ à¦°à¦¾à¦–à§à¦¨à¥¤';
    }
  }

  bool _overlaps(DateTime a1, DateTime a2, DateTime b1, DateTime b2) {
    return a1.isBefore(b2) && b1.isBefore(a2);
  }

  (DateTime, DateTime) _luckyWindowFor(int idx, DateTime day) {
    final sun = PanchangCalculator.sunTimes(day);
    final rahu = PanchangCalculator.rahuKalam(day);
    final yama = PanchangCalculator.yamagandaKalam(day);
    final gulika = PanchangCalculator.gulikaKalam(day);
    final blocked = <(DateTime, DateTime)>[
      (rahu['start']!, rahu['end']!),
      (yama['start']!, yama['end']!),
      (gulika['start']!, gulika['end']!),
    ];

    final candidates = <(DateTime, DateTime)>[];
    var cursor = sun.sunrise.add(const Duration(minutes: 45));
    final last = sun.sunset.subtract(const Duration(minutes: 60));
    while (!cursor.isAfter(last)) {
      final end = cursor.add(const Duration(minutes: 60));
      var safe = true;
      for (final b in blocked) {
        if (_overlaps(cursor, end, b.$1, b.$2)) {
          safe = false;
          break;
        }
      }
      if (safe) candidates.add((cursor, end));
      cursor = cursor.add(const Duration(minutes: 45));
    }

    final abhijit = PanchangCalculator.abhijitMuhurta(day);
    if (abhijit['applicable'] == true) {
      final a = abhijit['start'] as DateTime;
      final b = abhijit['end'] as DateTime;
      var safe = true;
      for (final blockedWindow in blocked) {
        if (_overlaps(a, b, blockedWindow.$1, blockedWindow.$2)) {
          safe = false;
          break;
        }
      }
      if (safe) candidates.insert(0, (a, b));
    }

    if (candidates.isEmpty) {
      final fallback = sun.sunrise.add(const Duration(hours: 2));
      return (fallback, fallback.add(const Duration(minutes: 60)));
    }
    final pick =
        (idx * 3 + day.day + PanchangCalculator.tithiFor(day).index) %
        candidates.length;
    return candidates[pick];
  }

  String _countdown(Duration d) {
    if (d.isNegative) d = Duration.zero;
    final h = d.inHours;
    final m = d.inMinutes.remainder(60);
    final s = d.inSeconds.remainder(60);
    return '${bnDigits(h.toString().padLeft(2, '0'))}:${bnDigits(m.toString().padLeft(2, '0'))}:${bnDigits(s.toString().padLeft(2, '0'))}';
  }

  List<(DateTime, int)> _bestDays() {
    final days = List.generate(7, (i) {
      final day = DateTime(
        _now.year,
        _now.month,
        _now.day,
      ).add(Duration(days: i));
      return (day, _scoreFor(_selectedIndex, day, 41));
    });
    days.sort((a, b) => b.$2.compareTo(a.$2));
    return days.take(3).toList();
  }

  int _compatibilityScore(int a, int b) {
    if (a == b) return 82;
    final elementA = a % 4;
    final elementB = b % 4;
    var score = 61 + ((a * 13 + b * 17 + _now.day) % 25);
    if (elementA == elementB) score += 8;
    if ((elementA - elementB).abs() == 2) score -= 5;
    return score.clamp(45, 95).toInt();
  }

