class TempleScreen extends StatefulWidget {
  const TempleScreen({super.key});
  @override
  State<TempleScreen> createState() => _TempleScreenState();
}

class _TempleScreenState extends State<TempleScreen> {
  bool _loaded = false;

  @override
  void initState() {
    super.initState();
    TempleStore.instance.load().then((_) {
      if (mounted) setState(() => _loaded = true);
    });
  }

  Future<void> _addDialog() async {
    final templeCtrl = TextEditingController();
    final pujaCtrl = TextEditingController();
    DateTime when = DateTime.now().add(const Duration(days: 1));
    bool reminder = true;
    await showDialog(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setSt) => AlertDialog(
          backgroundColor: const Color(0xFF0B1C38),
          title: const Text(
            'à¦¨à¦¤à§à¦¨ à¦ªà§‚à¦œà¦¾/à¦®à¦¨à§à¦¦à¦¿à¦° à¦¸à§‚à¦šà¦¿',
            style: TextStyle(color: Colors.white),
          ),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                TextField(
                  controller: templeCtrl,
                  style: const TextStyle(color: Colors.white),
                  decoration: const InputDecoration(
                    labelText:
                        'à¦®à¦¨à§à¦¦à¦¿à¦°/à¦¸à§à¦¥à¦¾à¦¨à§‡à¦° à¦¨à¦¾à¦®',
                    labelStyle: TextStyle(color: Colors.white70),
                  ),
                ),
                TextField(
                  controller: pujaCtrl,
                  style: const TextStyle(color: Colors.white),
                  decoration: const InputDecoration(
                    labelText: 'à¦ªà§‚à¦œà¦¾à¦° à¦¨à¦¾à¦®',
                    labelStyle: TextStyle(color: Colors.white70),
                  ),
                ),
                const SizedBox(height: 10),
                SizedBox(
                  width: double.infinity,
                  child: OutlinedButton(
                    onPressed: () async {
                      final d = await showDatePicker(
                        context: ctx,
                        initialDate: when,
                        firstDate: DateTime.now(),
                        lastDate: DateTime.now().add(
                          const Duration(days: 3650),
                        ),
                      );
                      if (d == null) return;
                      if (!ctx.mounted) return;
                      final t = await showTimePicker(
                        context: ctx,
                        initialTime: TimeOfDay.fromDateTime(when),
                      );
                      if (t == null) return;
                      setSt(
                        () => when = DateTime(
                          d.year,
                          d.month,
                          d.day,
                          t.hour,
                          t.minute,
                        ),
                      );
                    },
                    child: Text(
                      '${when.day}/${when.month}/${when.year} â€” ${TimeOfDay.fromDateTime(when).format(ctx)}',
                      style: const TextStyle(color: Colors.white),
                    ),
                  ),
                ),
                Row(
                  children: [
                    const Expanded(
                      child: Text(
                        'à¦¨à§‹à¦Ÿà¦¿à¦«à¦¿à¦•à§‡à¦¶à¦¨ à¦°à¦¿à¦®à¦¾à¦‡à¦¨à§à¦¡à¦¾à¦°',
                        style: TextStyle(color: Colors.white70, fontSize: 13),
                      ),
                    ),
                    Switch(
                      value: reminder,
                      activeColor: const Color(0xFFFFD36E),
                      onChanged: (v) => setSt(() => reminder = v),
                    ),
                  ],
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: const Text('à¦¬à¦¾à¦¤à¦¿à¦²'),
            ),
            ElevatedButton(
              onPressed: () async {
                if (templeCtrl.text.trim().isEmpty ||
                    pujaCtrl.text.trim().isEmpty) {
                  return;
                }
                await TempleStore.instance.add(
                  TempleEvent(
                    temple: templeCtrl.text.trim(),
                    pujaName: pujaCtrl.text.trim(),
                    when: when,
                    reminderOn: reminder,
                  ),
                );
                if (ctx.mounted) Navigator.pop(ctx);
                if (mounted) setState(() {});
              },
              style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFFFD36E),
              ),
              child: const Text(
                'à¦¯à§‹à¦— à¦•à¦°à§à¦¨',
                style: TextStyle(color: Colors.black),
              ),
            ),
          ],
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final items = TempleStore.instance.items;
    return CosmicBackground(
