/// à¦œà¦¨à§à¦® à¦¤à¦¾à¦°à¦¿à¦–+à¦¸à¦®à¦¯à¦¼ à¦¬à§‡à¦›à§‡ à¦¨à§‡à¦“à¦¯à¦¼à¦¾à¦° à¦œà¦¨à§à¦¯ à¦ªà§à¦¨à¦ƒà¦¬à§à¦¯à¦¬à¦¹à¦¾à¦°à¦¯à§‹à¦—à§à¦¯ à¦¬à¦¾à¦Ÿà¦¨ â€” à¦•à§à¦·à§à¦ à¦¿ à¦šà¦¾à¦°à§à¦Ÿ à¦“
/// à¦•à§à¦·à§à¦ à¦¿ à¦®à¦¿à¦²à¦¨ à¦¦à§à¦‡ à¦œà¦¾à¦¯à¦¼à¦—à¦¾à¦¤à§‡à¦‡ à¦¬à§à¦¯à¦¬à¦¹à¦¾à¦° à¦¹à¦¯à¦¼
class _DateTimePickerField extends StatefulWidget {
  final String label;
  final ValueChanged<DateTime> onChanged;
  const _DateTimePickerField({required this.label, required this.onChanged});
  @override
  State<_DateTimePickerField> createState() => _DateTimePickerFieldState();
}

class _DateTimePickerFieldState extends State<_DateTimePickerField> {
  DateTime? _value;

  Future<void> _pick() async {
    final now = DateTime.now();
    final d = await showDatePicker(
      context: context,
      initialDate: DateTime(now.year - 25, now.month, now.day),
      firstDate: DateTime(1930),
      lastDate: now,
    );
    if (d == null) return;
    if (!mounted) return;
    final t = await showTimePicker(
      context: context,
      initialTime: const TimeOfDay(hour: 6, minute: 0),
    );
    if (t == null) return;
    final dt = DateTime(d.year, d.month, d.day, t.hour, t.minute);
    setState(() => _value = dt);
    widget.onChanged(dt);
  }

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      width: double.infinity,
      child: OutlinedButton.icon(
        onPressed: _pick,
        icon: const Icon(Icons.calendar_month, color: Color(0xFFFFD36E)),
        label: Text(
          _value == null
              ? widget.label
              : '${_value!.day}/${_value!.month}/${_value!.year} â€” ${TimeOfDay.fromDateTime(_value!).format(context)}',
          style: const TextStyle(color: Colors.white),
        ),
        style: OutlinedButton.styleFrom(
          side: const BorderSide(color: Color(0xFFFFD36E)),
          padding: const EdgeInsets.symmetric(vertical: 12),
        ),
      ),
    );
  }
}

