    final when = _when!;
    final booking = BookingRequest(
      name: _nameCtrl.text.trim(),
      phone: _phoneCtrl.text.trim(),
      astrologer: _selected!.name,
      topic: _topic,
      when: when,
      notes: _notesCtrl.text.trim(),
    );
    await BookingStore.instance.add(booking);
    final timeLabel = TimeOfDay.fromDateTime(when).format(context);
    final extra = booking.notes.isEmpty
        ? ''
        : '\nà¦…à¦¤à¦¿à¦°à¦¿à¦•à§à¦¤ à¦¤à¦¥à§à¦¯: ${booking.notes}';
    final msg = Uri.encodeComponent(
      'à¦¨à¦®à¦¸à§à¦•à¦¾à¦°, à¦†à¦®à¦¿ ${booking.name} â€” à¦†à¦®à¦¿ ${booking.astrologer}-à¦° à¦¸à¦¾à¦¥à§‡ '
      '${booking.topic} à¦¬à¦¿à¦·à¦¯à¦¼à§‡ à¦ªà¦°à¦¾à¦®à¦°à§à¦¶à§‡à¦° à¦œà¦¨à§à¦¯ à¦¬à§à¦•à¦¿à¦‚ à¦•à¦°à¦¤à§‡ à¦šà¦¾à¦‡à¥¤\n'
      'à¦ªà¦›à¦¨à§à¦¦à§‡à¦° à¦¸à¦®à¦¯à¦¼: ${when.day}/${when.month}/${when.year} $timeLabel\n'
      'à¦«à§‹à¦¨: ${booking.phone}$extra',
    );
    if (_astrologerWhatsApp.isNotEmpty) {
      final uri = Uri.parse('https://wa.me/$_astrologerWhatsApp?text=$msg');
      try {
        await launchUrl(uri, mode: LaunchMode.externalApplication);
      } catch (_) {}
    }
    if (mounted) {
      setState(() {
        _nameCtrl.clear();
        _phoneCtrl.clear();
        _notesCtrl.clear();
        _selected = null;
        _when = null;
      });
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'âœ… à¦¬à§à¦•à¦¿à¦‚ à¦°à¦¿à¦•à§‹à¦¯à¦¼à§‡à¦¸à§à¦Ÿ à¦ªà¦¾à¦ à¦¾à¦¨à§‹ à¦¹à¦¯à¦¼à§‡à¦›à§‡',
          ),
        ),
      );
    }
  }

