  /// à¦†à¦œà¦•à§‡à¦° à¦ªà¦°à§‡à¦° (à¦†à¦œà¦¸à¦¹) à¦—à§à¦°à¦¹à¦£à¦—à§à¦²à§‹ â€” à¦—à§à¦°à§‡à¦—à¦°à¦¿à¦¯à¦¼à¦¾à¦¨ à¦¤à¦¾à¦°à¦¿à¦–à§‡à¦° à¦ªà¦¾à¦¶à¦¾à¦ªà¦¾à¦¶à¦¿ real à¦¬à¦¾à¦‚à¦²à¦¾
  /// à¦®à¦¾à¦¸à§‡à¦° à¦¤à¦¾à¦°à¦¿à¦–à¦“ à¦¦à§‡à¦–à¦¾à¦¯à¦¼ (à¦¯à§‡à¦®à¦¨: "à§¨à§® à¦†à¦—à¦¸à§à¦Ÿ à§¨à§¦à§¨à§¬ (à§§à§§ à¦­à¦¾à¦¦à§à¦° à§§à§ªà§©à§©) â€¢ à¦†à¦‚à¦¶à¦¿à¦• à¦šà¦¨à§à¦¦à§à¦°à¦—à§à¦°à¦¹à¦£")
  static List<List<String>> _liveEclipses() {
    final now = DateTime.now();
    final todayStart = DateTime(now.year, now.month, now.day);
    final upcoming = _eclipseEvents
        .where((e) => !e.date.isBefore(todayStart))
        .toList();
    if (upcoming.isEmpty) {
      return [
        [
          'ðŸ”­ à¦—à§à¦°à¦¹à¦£',
          'à¦†à¦—à¦¾à¦®à§€ à¦•à¦¿à¦›à§à¦¦à¦¿à¦¨à§‡ à¦•à§‹à¦¨à§‹ à¦—à§à¦°à¦¹à¦£à§‡à¦° à¦¤à¦¥à§à¦¯ à¦¨à§‡à¦‡',
        ],
      ];
    }
    return upcoming.map((e) {
      final info = BengaliDateUtil.monthInfoFor(e.date);
      final bDay = e.date.difference(info.start).inDays + 1;
      final gregLabel =
          '${bnNum(e.date.day)} ${gregMonthBn(e.date.month)} ${bnNum(e.date.year)}';
      final bengaliLabel = '${bnNum(bDay)} ${info.name} ${bnNum(info.year)}';
      var detail = '$gregLabel ($bengaliLabel) â€¢ ${e.desc}';
      if (e.timingIst != null) {
        detail += '\nâ±ï¸ à¦¸à¦®à¦¯à¦¼ (IST): ${e.timingIst}';
      }
      if (e.indiaVisibility != null) {
        detail += '\nðŸ“ ${e.indiaVisibility}';
      }
      return ['${e.icon} ${e.title}', detail];
    }).toList();
  }

