  /// à¦à¦–à¦¨ à¦ªà§à¦°à¦¤à¦¿à¦Ÿà¦¾ real heliocentric Keplerian orbital elements (NASA JPL
  /// à¦Ÿà§‡à¦¬à¦¿à¦²) à¦¦à¦¿à¦¯à¦¼à§‡ à¦¹à¦¿à¦¸à§‡à¦¬ à¦•à¦°à¦¾ à¦†à¦œà¦•à§‡à¦° à¦ªà§à¦°à¦•à§ƒà¦¤ à¦°à¦¾à¦¶à¦¿ à¦“ à¦¸à¦°à¦²/à¦¬à¦•à§à¦°à§€ (retrograde) à¦—à¦¤à¦¿
  /// à¦¦à§‡à¦–à¦¾à¦¯à¦¼ â€” à¦•à§‹à¦¨à§‹ fake à¦¡à§‡à¦Ÿà¦¾ à¦¨à§‡à¦‡à¥¤
  static List<List<String>> _livePlanets() {
    final now = DateTime.now();
    final sunIdx = PanchangCalculator.sunRashiIndexFor(now);
    final moonIdx = PanchangCalculator.rashiIndexFor(now);
    final nakIdx = PanchangCalculator.nakshatraIndexFor(now);
    const synodic = 29.530588853;
    final moonAge = PanchangCalculator.moonAgeDays(now) % synodic;
    final illum = (1 - math.cos(moonAge / synodic * 2 * math.pi)) / 2;
    final waxing = moonAge < synodic / 2;
    final moonPhaseText = waxing
        ? 'à¦¬à¦°à§à¦§à¦¿à¦·à§à¦£à§ (${(illum * 100).round()}%)'
        : 'à¦•à§à¦·à¦¯à¦¼à¦¿à¦·à§à¦£à§ (${(illum * 100).round()}%)';

    String planetRow(String key) {
      final idx = PanchangCalculator.planetRashiIndexFor(key, now);
      final retro = PanchangCalculator.planetIsRetrograde(key, now);
      final rashi = PanchangCalculator.rashiNames[idx];
      return '$rashi à¦°à¦¾à¦¶à¦¿à¦¤à§‡ â€¢ ${retro ? "à¦¬à¦•à§à¦°à§€" : "à¦¸à¦°à¦²"} à¦—à¦¤à¦¿';
    }

    return [
      [
        'â˜€ï¸ à¦¸à§‚à¦°à§à¦¯',
        '${PanchangCalculator.rashiNames[sunIdx]} à¦°à¦¾à¦¶à¦¿à¦¤à§‡ à¦…à¦¬à¦¸à§à¦¥à¦¾à¦¨',
      ],
      [
        'ðŸŒ™ à¦šà¦¨à§à¦¦à§à¦°',
        '${PanchangCalculator.rashiNames[moonIdx]} à¦°à¦¾à¦¶à¦¿à¦¤à§‡ â€¢ $moonPhaseText',
      ],
      ['ðŸ”´ à¦®à¦™à§à¦—à¦²', planetRow('mars')],
      ['ðŸŸ¡ à¦¬à§ƒà¦¹à¦¸à§à¦ªà¦¤à¦¿', planetRow('jupiter')],
      ['ðŸ’« à¦¶à§à¦•à§à¦°', planetRow('venus')],
      ['ðŸª à¦¶à¦¨à¦¿', planetRow('saturn')],
      [
        'â­ à¦¨à¦•à§à¦·à¦¤à§à¦°',
        'à¦†à¦œ: ${PanchangCalculator.nakshatraNames[nakIdx]}',
      ],
    ];
  }

