class _TrialSignupForm extends StatefulWidget {
  const _TrialSignupForm();
  @override
  State<_TrialSignupForm> createState() => _TrialSignupFormState();
}

class _TrialSignupFormState extends State<_TrialSignupForm> {
  final _nameController = TextEditingController();
  final _addressController = TextEditingController();
  DateTime? _dob;
  String? _error;

  @override
  void dispose() {
    _nameController.dispose();
    _addressController.dispose();
    super.dispose();
  }

  Future<void> _submit() async {
    final name = _nameController.text.trim();
    final address = _addressController.text.trim();
    if (name.isEmpty || address.isEmpty || _dob == null) {
      setState(
        () => _error =
            'à¦¨à¦¾à¦®, à¦œà¦¨à§à¦® à¦¤à¦¾à¦°à¦¿à¦–-à¦¸à¦®à¦¯à¦¼ à¦“ à¦ à¦¿à¦•à¦¾à¦¨à¦¾ â€” à¦¸à¦¬à¦—à§à¦²à§‹ à¦¦à¦¿à¦¤à§‡ à¦¹à¦¬à§‡',
      );
      return;
    }
    setState(() => _error = null);
    await AppSettings.instance.activateTrial(
      name: name,
      dob: _dob!,
      address: address,
    );
    // à¦à¦°à¦ªà¦° à¦†à¦²à¦¾à¦¦à¦¾ à¦•à¦¿à¦›à§ à¦•à¦°à¦¾à¦° à¦¦à¦°à¦•à¦¾à¦° à¦¨à§‡à¦‡ â€” à¦‰à¦ªà¦°à§‡à¦° _PremiumGate à¦¨à¦¿à¦œà§‡ à¦¥à§‡à¦•à§‡à¦‡
