    'à¦¬à¦¬',
    'à¦¬à¦¾à¦²à¦¬',
    'à¦•à§Œà¦²à¦¬',
    'à¦¤à§ˆà¦¤à¦¿à¦²',
    'à¦—à¦°',
    'à¦¬à¦£à¦¿à¦œ',
    'à¦¬à¦¿à¦·à§à¦Ÿà¦¿',
  ];
  static const List<String> _karanaFixedNames = [
    'à¦¶à¦•à§à¦¨à¦¿',
    'à¦šà¦¤à§à¦·à§à¦ªà¦¦',
    'à¦¨à¦¾à¦—',
    'à¦•à¦¿à¦‚à¦¸à§à¦¤à§à¦˜à§à¦¨',
  ];

  /// à¦à¦•à¦Ÿà¦¿ à¦¤à¦¿à¦¥à¦¿ = à¦¦à§à¦Ÿà¦¿ à¦•à¦°à¦£ (à¦ªà§à¦°à¦¤à¦¿ à¦•à¦°à¦£ ~à§¬Â°)à¥¤ à¦®à§‹à¦Ÿ à§¬à§¦à¦Ÿà¦¿ à¦…à¦°à§à¦§-à¦¤à¦¿à¦¥à¦¿/à¦®à¦¾à¦¸ â€” à¦ªà§à¦°à¦¥à¦®à¦Ÿà¦¿
  /// à¦•à¦¿à¦‚à¦¸à§à¦¤à§à¦˜à§à¦¨ (à¦¸à§à¦¥à¦¿à¦°), à¦¤à¦¾à¦°à¦ªà¦° à§­à¦Ÿà¦¿ à¦šà¦²à¦®à¦¾à¦¨ à¦•à¦°à¦£ à§® à¦¬à¦¾à¦° à¦†à¦¬à¦°à§à¦¤à¦¿à¦¤ à¦¹à¦¯à¦¼, à¦¶à§‡à¦·à§‡ à¦¬à¦¾à¦•à¦¿
  /// à§©à¦Ÿà¦¿ à¦¸à§à¦¥à¦¿à¦° à¦•à¦°à¦£ (à¦¶à¦•à§à¦¨à¦¿, à¦šà¦¤à§à¦·à§à¦ªà¦¦, à¦¨à¦¾à¦—)à¥¤
  static String karanaFor(DateTime localDateTime) {
    final jd = julianDay(_toTrueUtc(localDateTime));
    final elong = _norm360(moonLongitude(jd) - sunLongitude(jd));
    final half = (elong / 6.0).floor().clamp(0, 59);
    if (half == 0)
      return _karanaFixedNames[3]; // à¦•à¦¿à¦‚à¦¸à§à¦¤à§à¦˜à§à¦¨
    if (half >= 57) return _karanaFixedNames[half - 57];
    return _karanaMovingNames[(half - 1) % 7];
  }
}

