class BengaliDateUtil {
  static final Map<int, List<Map<String, dynamic>>> _cache = {};

  /// à¦¬à¦¾à¦‚à¦²à¦¾ à¦®à¦¾à¦¸à§‡à¦° à¦ªà§à¦°à¦•à§ƒà¦¤ à¦¶à§à¦°à§ â€” à¦¸à§‚à¦°à§à¦¯à§‡à¦° à¦¸à¦‚à¦•à§à¦°à¦¾à¦¨à§à¦¤à¦¿ (à¦°à¦¾à¦¶à¦¿ à¦ªà§à¦°à¦¬à§‡à¦¶) à¦¥à§‡à¦•à§‡ à¦¹à¦¿à¦¸à§‡à¦¬à¥¤
  /// à¦†à¦—à§‡ à¦ªà§à¦°à¦¤à¦¿ à¦¬à¦›à¦° à¦à¦•à¦‡ à¦¤à¦¾à¦°à¦¿à¦– (à¦¬à§ˆà¦¶à¦¾à¦– = à§§à§ª à¦à¦ªà§à¦°à¦¿à¦²) à¦§à¦°à¦¾ à¦¹à¦¤à§‹, à¦¯à¦¾ à¦•à¦¯à¦¼à§‡à¦• à¦¬à¦›à¦°à§‡à¦‡
  /// à¦à¦• à¦¦à¦¿à¦¨ à¦¸à¦°à§‡ à¦¯à¦¾à¦¯à¦¼à¥¤ à¦à¦–à¦¨ à¦¸à§‚à¦°à§à¦¯ à¦•à¦–à¦¨ à¦¨à¦¤à§à¦¨ à¦°à¦¾à¦¶à¦¿à¦¤à§‡ à¦¢à§à¦•à¦›à§‡ à¦¸à§‡à¦Ÿà¦¾ à¦¬à§‡à¦° à¦•à¦°à§‡, à¦¤à¦¾à¦°
  /// à¦ªà¦°à§‡à¦° à¦ªà§à¦°à¦¥à¦® à¦¸à§‚à¦°à§à¦¯à§‹à¦¦à¦¯à¦¼à§‡ à¦®à¦¾à¦¸ à¦¶à§à¦°à§ à¦§à¦°à¦¾ à¦¹à¦¯à¦¼ (à¦ªà¦¶à§à¦šà¦¿à¦®à¦¬à¦™à§à¦—à§‡à¦° à¦ªà§à¦°à¦šà¦²à¦¿à¦¤ à¦¨à¦¿à¦¯à¦¼à¦®)à¥¤
  static const List<String> _monthNames = [
    'à¦¬à§ˆà¦¶à¦¾à¦–',
    'à¦œà§à¦¯à§ˆà¦·à§à¦ ',
    'à¦†à¦·à¦¾à¦¢à¦¼',
    'à¦¶à§à¦°à¦¾à¦¬à¦£',
    'à¦­à¦¾à¦¦à§à¦°',
    'à¦†à¦¶à§à¦¬à¦¿à¦¨',
    'à¦•à¦¾à¦°à§à¦¤à¦¿à¦•',
    'à¦…à¦—à§à¦°à¦¹à¦¾à¦¯à¦¼à¦£',
    'à¦ªà§Œà¦·',
    'à¦®à¦¾à¦˜',
    'à¦«à¦¾à¦²à§à¦—à§à¦¨',
    'à¦šà§ˆà¦¤à§à¦°',
  ];

  /// à¦¸à§‚à¦°à§à¦¯à§‡à¦° à¦¨à¦¿à¦°à¦¯à¦¼à¦¨ (sidereal) à¦¦à§à¦°à¦¾à¦˜à¦¿à¦®à¦¾ â€” à¦¸à¦‚à¦•à§à¦°à¦¾à¦¨à§à¦¤à¦¿ à¦¬à§‡à¦° à¦•à¦°à¦¾à¦° à¦œà¦¨à§à¦¯
  static double _siderealSunLon(DateTime utc) {
    final jd = PanchangCalculator.julianDay(utc);
    return PanchangCalculator._norm360(
      PanchangCalculator.sunLongitude(jd) - PanchangCalculator.ayanamsa(jd),
    );
  }

  /// à¦²à¦•à§à¦·à§à¦¯ à¦•à§‹à¦£ à¦¥à§‡à¦•à§‡ à¦•à¦¤ à¦¦à§‚à¦°à§‡ (-à§§à§®à§¦..+à§§à§®à§¦): à¦¸à¦‚à¦•à§à¦°à¦¾à¦¨à§à¦¤à¦¿à¦° à¦†à¦—à§‡ à¦‹à¦£à¦¾à¦¤à§à¦®à¦•, à¦ªà¦°à§‡ à¦§à¦¨à¦¾à¦¤à§à¦®à¦•
  static double _lonOffset(DateTime utc, double target) {
    var d = (_siderealSunLon(utc) - target) % 360.0;
    if (d > 180) d -= 360;
    if (d < -180) d += 360;
    return d;
  }

  /// [gYear] à¦¸à¦¾à¦²à§‡à¦° à¦¬à§ˆà¦¶à¦¾à¦– à¦¥à§‡à¦•à§‡ à¦¶à§à¦°à§ à¦•à¦°à§‡ [k]-à¦¤à¦® à¦®à¦¾à¦¸à§‡à¦° à¦¸à¦‚à¦•à§à¦°à¦¾à¦¨à§à¦¤à¦¿à¦° à¦®à§à¦¹à§‚à¦°à§à¦¤
  static DateTime _sankranti(int gYear, int k) {
    final target = (k * 30.0) % 360.0;
    // à¦†à¦¨à§à¦®à¦¾à¦¨à¦¿à¦• à¦…à¦¬à¦¸à§à¦¥à¦¾à¦¨ à¦¥à§‡à¦•à§‡ à¦¶à§à¦°à§ à¦•à¦°à§‡ à¦¸à¦¾à¦‡à¦¨ à¦¬à¦¦à¦²à§‡à¦° à¦¦à¦¿à¦¨ à¦–à§à¦à¦œà¦¿
    var t = DateTime.utc(
      gYear,
      4,
      14,
    ).add(Duration(days: (k * 30.44).round() - 8));
    var prev = _lonOffset(t, target);
    for (int step = 0; step < 80; step++) {
      final next = t.add(const Duration(hours: 6));
      final cur = _lonOffset(next, target);
      if (prev < 0 && cur >= 0) {
        // à¦¦à§à¦‡ à¦¬à¦¿à¦¨à§à¦¦à§à¦° à¦®à¦¾à¦à§‡ à¦¦à§à¦¬à¦¿à¦–à¦£à§à¦¡à¦¨ à¦•à¦°à§‡ à¦®à§à¦¹à§‚à¦°à§à¦¤à¦Ÿà¦¾ à¦¸à§‚à¦•à§à¦·à§à¦® à¦•à¦°à¦¿
        var lo = t, hi = next;
        for (int b = 0; b < 22; b++) {
          final mid = lo.add(
            Duration(milliseconds: hi.difference(lo).inMilliseconds ~/ 2),
          );
          if (_lonOffset(mid, target) < 0) {
            lo = mid;
          } else {
            hi = mid;
          }
        }
        return hi.add(const Duration(hours: 5, minutes: 30)); // IST
      }
      t = next;
      prev = cur;
    }
    // à¦¬à§à¦¯à¦°à§à¦¥ à¦¹à¦²à§‡ à¦ªà§à¦°à¦¨à§‹ à¦†à¦¨à§à¦®à¦¾à¦¨à¦¿à¦• à¦¤à¦¾à¦°à¦¿à¦–à§‡à¦‡ à¦«à¦¿à¦°à§‡ à¦¯à¦¾à¦‡ (à¦‰à¦ªà¦°à§‡à¦° à¦¸à¦¾à¦«à¦²à§à¦¯à§‡à¦° path-à¦à¦°
    // à¦®à¦¤à§‹à¦‡ IST-marked à¦«à¦°à¦®à§à¦¯à¦¾à¦Ÿà§‡, à¦¯à¦¾à¦¤à§‡ _monthStart-à¦à¦° à¦¤à§à¦²à¦¨à¦¾ à¦¸à¦ à¦¿à¦• à¦¥à¦¾à¦•à§‡)
    return DateTime.utc(
      gYear,
      4,
      14,
    ).add(Duration(days: (k * 30.44).round(), hours: 5, minutes: 30));
  }

  /// à¦¬à¦¾à¦‚à¦²à¦¾ à¦®à¦¾à¦¸à§‡à¦° à§§ à¦¤à¦¾à¦°à¦¿à¦– à¦¨à¦¿à¦°à§à¦£à¦¯à¦¼ (à¦ªà¦¶à§à¦šà¦¿à¦®à¦¬à¦™à§à¦—à§‡à¦° à¦ªà§à¦°à¦šà¦²à¦¿à¦¤ à¦¨à¦¿à¦¯à¦¼à¦®):
  /// à¦¸à¦‚à¦•à§à¦°à¦¾à¦¨à§à¦¤à¦¿ à¦¸à§‚à¦°à§à¦¯à¦¾à¦¸à§à¦¤à§‡à¦° à¦†à¦—à§‡ à¦¹à¦²à§‡ â†’ à¦ªà¦°à¦¦à¦¿à¦¨ à§§ à¦¤à¦¾à¦°à¦¿à¦–,
  /// à¦¸à§‚à¦°à§à¦¯à¦¾à¦¸à§à¦¤à§‡à¦° à¦ªà¦°à§‡ à¦¹à¦²à§‡ â†’ à¦¤à¦¾à¦° à¦ªà¦°à¦¦à¦¿à¦¨ à§§ à¦¤à¦¾à¦°à¦¿à¦–à¥¤
  /// (à§¨à§¦à§¨à§§â€“à§¨à§¦à§¨à§¬ à¦¸à¦¾à¦²à§‡à¦° à¦ªà§à¦°à¦•à§ƒà¦¤ à¦ªà¦¯à¦¼à¦²à¦¾ à¦¬à§ˆà¦¶à¦¾à¦–à§‡à¦° à¦¸à¦¾à¦¥à§‡ à¦®à¦¿à¦²à¦¿à¦¯à¦¼à§‡ à¦¯à¦¾à¦šà¦¾à¦‡ à¦•à¦°à¦¾ à¦¹à¦¯à¦¼à§‡à¦›à§‡)
  ///
  /// [monthIndex] (à§¦=à¦¬à§ˆà¦¶à¦¾à¦–...à§§à§§=à¦šà§ˆà¦¤à§à¦°) à¦à¦šà§à¦›à¦¿à¦• â€” à¦­à¦¾à¦¦à§à¦°(à§ª) à¦“ à¦†à¦¶à§à¦¬à¦¿à¦¨(à§«) à¦®à¦¾à¦¸à§‡
  /// à¦à¦‡ à¦¸à¦°à¦² à¦¸à§‚à¦°à§à¦¯à¦¾à¦¸à§à¦¤-à¦¨à¦¿à¦¯à¦¼à¦®à§‡ à¦¹à¦¿à¦¸à§‡à¦¬ à¦•à¦°à¦²à§‡ prokerala.com-à¦à¦° à¦ªà§à¦°à¦•à¦¾à¦¶à¦¿à¦¤ à¦ªà¦žà§à¦œà¦¿à¦•à¦¾à¦°
  /// (à¦†à¦° à¦¬à§à¦¯à¦¬à¦¹à¦¾à¦°à¦•à¦¾à¦°à§€à¦° à¦ªà§à¦°à¦¤à§à¦¯à¦¾à¦¶à¦¾à¦°) à¦šà§‡à¦¯à¦¼à§‡ à¦ à¦¿à¦• à§§ à¦¦à¦¿à¦¨ à¦†à¦—à§‡ à¦¦à§‡à¦–à¦¾à¦¯à¦¼ â€” à¦¯à¦¾à¦šà¦¾à¦‡ à¦•à¦°à§‡
  /// à¦¦à§‡à¦–à¦¾ à¦—à§‡à¦›à§‡ à§¨à§¦à§¨à§¬ à¦¸à¦¾à¦²à§‡ à¦à¦‡ à¦¦à§à¦‡ à¦®à¦¾à¦¸à§‡à¦‡ à¦¬à¦¾à¦¸à§à¦¤à¦¬ à¦ªà¦žà§à¦œà¦¿à¦•à¦¾ à¦†à¦°à¦“ à§§ à¦¦à¦¿à¦¨ à¦ªà¦°à§‡ à¦¶à§à¦°à§
  /// à¦§à¦°à§‡ (à¦¸à¦®à§à¦­à¦¬à¦¤ à¦ªà§à¦°à¦¥à¦¾à¦—à¦¤ à¦¸à§‚à¦°à§à¦¯ à¦¸à¦¿à¦¦à§à¦§à¦¾à¦¨à§à¦¤-à¦­à¦¿à¦¤à§à¦¤à¦¿à¦• à¦ªà¦žà§à¦œà¦¿à¦•à¦¾ à¦†à¦§à§à¦¨à¦¿à¦•
  /// à¦œà§à¦¯à§‹à¦¤à¦¿à¦°à§à¦¬à¦¿à¦¦à§à¦¯à¦¾à¦° à¦¹à¦¿à¦¸à§‡à¦¬à§‡à¦° à¦šà§‡à¦¯à¦¼à§‡ à¦à¦‡ à¦¸à¦®à¦¯à¦¼à§‡ à¦à¦•à¦Ÿà§ à¦­à¦¿à¦¨à§à¦¨) â€” à¦¬à¦¾à¦•à¦¿ à§§à§¦à¦Ÿà¦¾ à¦®à¦¾à¦¸à§‡
  /// à¦¦à§à¦Ÿà§‹ à¦¹à¦¿à¦¸à§‡à¦¬à¦‡ à¦¹à§à¦¬à¦¹à§ à¦®à§‡à¦²à§‡à¥¤ à¦¤à¦¾à¦‡ à¦à¦‡ à¦¦à§à¦‡ à¦®à¦¾à¦¸à§‡ à¦¬à§à¦¯à¦¬à¦¹à¦¾à¦°à¦•à¦¾à¦°à§€à¦° à¦…à¦¨à§à¦°à§‹à¦§ à¦…à¦¨à§à¦¯à¦¾à¦¯à¦¼à§€
  /// à¦¸à¦°à¦¾à¦¸à¦°à¦¿ à§§ à¦¦à¦¿à¦¨ à¦¯à§‹à¦— à¦•à¦°à¦¾ à¦¹à¦šà§à¦›à§‡à¥¤
  static DateTime _monthStart(DateTime sankrantiLocal, [int? monthIndex]) {
    final day = DateTime(
      sankrantiLocal.year,
      sankrantiLocal.month,
      sankrantiLocal.day,
    );
    final sunset = PanchangCalculator.sunTimes(day).sunset;
    var offset = sankrantiLocal.isAfter(sunset) ? 2 : 1;
    if (monthIndex == 4 || monthIndex == 5) offset += 1;
    return day.add(Duration(days: offset));
  }

  static List<Map<String, dynamic>> _yearBoundaries(int g) {
    final by = g - 593;
    return List.generate(12, (k) {
      return {
        'name': _monthNames[k],
        'date': _monthStart(_sankranti(g, k), k),
        'bYear': by,
      };
    });
  }

  static const _tabs = [
    'à¦¸à¦®à§à¦ªà§‚à¦°à§à¦£ à¦®à¦¾à¦¸',
    'à¦¬à¦¿à¦¶à§‡à¦· à¦¦à¦¿à¦¨ à¦¸à¦®à§‚à¦¹',
    'à¦¬à¦¿à¦¬à¦¾à¦¹',
    'à¦…à¦¨à§à¦¨à¦ªà§à¦°à¦¾à¦¶à¦¨',
    'à¦—à§ƒà¦¹à¦ªà§à¦°à¦¬à§‡à¦¶',
    'à¦à¦•à¦¾à¦¦à¦¶à§€',
    'à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾',
    'à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾',
  ];

  static String _tabCategory(String tab) {
    switch (tab) {
      case 'à¦¬à¦¿à¦¬à¦¾à¦¹':
        return 'marriage';
      case 'à¦…à¦¨à§à¦¨à¦ªà§à¦°à¦¾à¦¶à¦¨':
        return 'annaprashan';
      case 'à¦—à§ƒà¦¹à¦ªà§à¦°à¦¬à§‡à¦¶':
        return 'griha';
      case 'à¦¬à¦¿à¦¶à§‡à¦· à¦¦à¦¿à¦¨ à¦¸à¦®à§‚à¦¹':
        return 'general';
      case 'à¦à¦•à¦¾à¦¦à¦¶à§€':
        return 'ekadashi';
      case 'à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾':
        return 'purnima';
      case 'à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾':
        return 'amabasya';
      default:
        return '';
    }
  }

  static List<Map<String, dynamic>> _boundariesAround(int gregYear) {
    if (_cache.containsKey(gregYear)) return _cache[gregYear]!;
    final list = <Map<String, dynamic>>[];
    for (final g in [gregYear - 2, gregYear - 1, gregYear, gregYear + 1]) {
      list.addAll(_yearBoundaries(g));
    }
    list.sort(
      (a, b) => (a['date'] as DateTime).compareTo(b['date'] as DateTime),
    );
    _cache[gregYear] = list;
    return list;
  }

  static BengaliMonthInfo monthInfoFor(DateTime date) {
    final boundaries = _boundariesAround(date.year);
    int idx = 0;
    for (int i = 0; i < boundaries.length; i++) {
      if (!(boundaries[i]['date'] as DateTime).isAfter(date)) idx = i;
    }
    final cur = boundaries[idx];
    final next = boundaries[idx + 1];
    return BengaliMonthInfo(
      cur['name'] as String,
      cur['bYear'] as int,
      cur['date'] as DateTime,
      (next['date'] as DateTime).subtract(const Duration(days: 1)),
    );
  }
}

