class PanjikaArt extends StatelessWidget {
  final String motif;
  final double size;
  const PanjikaArt(this.motif, {super.key, this.size = 24});

  /// à¦‰à§Žà¦¸à¦¬/à¦¤à¦¿à¦¥à¦¿à¦° à¦¨à¦¾à¦® à¦“ à¦•à§à¦¯à¦¾à¦Ÿà¦¾à¦—à¦°à¦¿ à¦¥à§‡à¦•à§‡ à¦‰à¦ªà¦¯à§à¦•à§à¦¤ motif à¦¬à§‡à¦›à§‡ à¦¨à§‡à¦¯à¦¼à¥¤
  /// à¦ªà§à¦°à¦¥à¦®à§‡ à¦¤à¦¿à¦¥à¦¿-à¦•à§à¦¯à¦¾à¦Ÿà¦¾à¦—à¦°à¦¿ (à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾/à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾/à¦à¦•à¦¾à¦¦à¦¶à§€/à¦¸à¦‚à¦•à§à¦°à¦¾à¦¨à§à¦¤à¦¿), à¦¤à¦¾à¦°à¦ªà¦°
  /// à¦¨à¦¾à¦®à§‡à¦° à¦­à§‡à¦¤à¦°à§‡à¦° à¦¶à¦¬à§à¦¦ à¦®à¦¿à¦²à¦¿à¦¯à¦¼à§‡à¥¤ à¦•à¦¿à¦›à§à¦‡ à¦¨à¦¾ à¦®à¦¿à¦²à¦²à§‡ null (à¦¤à¦–à¦¨ à¦†à¦—à§‡à¦° à¦‡à¦®à§‹à¦œà¦¿/
  /// à¦¡à¦¿à¦«à¦²à§à¦Ÿ à¦…à¦²à¦™à§à¦•à¦°à¦£ à¦¦à§‡à¦–à¦¾à¦¨à§‹ à¦¹à¦¬à§‡)à¥¤
  static String? motifFor(
    String label,
    String category, {
    bool sankranti = false,
  }) {
    switch (category) {
      case 'purnima':
        return 'moonFull';
      case 'amabasya':
        return 'moonNew';
      case 'ekadashi':
        return 'tulsi';
    }
    bool has(List<String> keys) => keys.any((k) => label.contains(k));
    if (has([
      'à¦¦à§à¦°à§à¦—à¦¾',
      'à¦·à¦·à§à¦ à§€',
      'à¦¸à¦ªà§à¦¤à¦®à§€',
      'à¦…à¦·à§à¦Ÿà¦®à§€',
      'à¦¨à¦¬à¦®à§€',
      'à¦¦à¦¶à¦®à§€',
      'à¦®à¦¹à¦¾à¦²à¦¯à¦¼à¦¾',
    ])) {
      return 'trishul';
    }
    if (has([
      'à¦•à¦¾à¦²à§€',
      'à¦¦à§€à¦ªà¦¾à¦¬à¦²à¦¿',
      'à¦¦à¦¿à¦“à¦¯à¦¼à¦¾à¦²à¦¿',
      'à¦¦à§€à¦ª',
    ]))
      return 'diya';
    if (has(['à¦²à¦•à§à¦·à§à¦®à§€', 'à¦•à§‹à¦œà¦¾à¦—à¦°à§€'])) return 'lotus';
    if (has(['à¦¸à¦°à¦¸à§à¦¬à¦¤à§€'])) return 'veena';
    if (has(['à¦¶à¦¿à¦¬', 'à¦¶à¦¿à¦¬à¦°à¦¾à¦¤à§à¦°à¦¿'])) return 'shiva';
    if (has(['à¦œà¦¨à§à¦®à¦¾à¦·à§à¦Ÿà¦®à§€', 'à¦•à§ƒà¦·à§à¦£']))
      return 'peacock';
    if (has(['à¦—à¦£à§‡à¦¶'])) return 'lotus';
    if (has(['à¦°à¦¥'])) return 'temple';
    if (has(['à¦°à¦¾à¦® à¦¨à¦¬à¦®à§€', 'à¦®à¦¨à§à¦¦à¦¿à¦°', 'à¦ªà§‚à¦œà¦¾']))
      return 'temple';
    if (has(['à¦°à¦¾à¦–à¦¿', 'à¦­à¦¾à¦‡à¦«à§‹à¦à¦Ÿà¦¾', 'à¦­à¦¾à¦‡']))
      return 'rakhi';
    if (has(['à¦§à¦¨à¦¤à§‡à¦°à¦¾à¦¸', 'à¦§à¦¨'])) return 'coin';
    if (has(['à¦¦à§‹à¦²', 'à¦¹à§‹à¦²à¦¿', 'à¦¬à¦¸à¦¨à§à¦¤'])) return 'flower';
    if (has(['à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾'])) return 'moonFull';
    if (has(['à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾'])) return 'moonNew';
    if (has(['à¦—à§à¦°à¦¹à¦£'])) return 'moonNew';
    if (has([
      'à¦¸à§à¦¬à¦¾à¦§à§€à¦¨à¦¤à¦¾',
      'à¦ªà§à¦°à¦œà¦¾à¦¤à¦¨à§à¦¤à§à¦°',
      'à¦¦à¦¿à¦¬à¦¸',
    ]))
      return 'flag';
    if (has(['à¦¨à¦¬à¦¬à¦°à§à¦·', 'à¦¬à¦¡à¦¼à¦¦à¦¿à¦¨'])) return 'star';
    // à¦¨à¦¾à¦®à§‡à¦° à¦¸à¦¾à¦¥à§‡ à¦•à¦¿à¦›à§ à¦¨à¦¾ à¦®à¦¿à¦²à¦²à§‡à¦“, à¦®à¦¾à¦¸-à¦¶à§à¦°à§à¦° (à¦¸à¦‚à¦•à§à¦°à¦¾à¦¨à§à¦¤à¦¿) à¦¦à¦¿à¦¨à§‡ à¦¸à§‚à¦°à§à¦¯
    if (sankranti) return 'sun';
    return null;
  }

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      width: size,
      height: size,
      child: CustomPaint(painter: _PanjikaArtPainter(motif)),
    );
  }
}

class _PanjikaArtPainter extends CustomPainter {
  final String motif;
  _PanjikaArtPainter(this.motif);

  // à¦à¦¤à¦¿à¦¹à§à¦¯à¦¬à¦¾à¦¹à§€ à¦ªà§à¦¯à¦¾à¦²à§‡à¦Ÿ
  static const _saffron = Color(0xFFE8871E);
  static const _saffronLt = Color(0xFFF3A93B);
  static const _red = Color(0xFFC62828);
  static const _gold = Color(0xFFD9A73A);
  static const _goldLt = Color(0xFFF2CE63);
  static const _cream = Color(0xFFF6EFD6);
  static const _navy = Color(0xFF17225C);
  static const _green = Color(0xFF2E7D32);
  static const _leaf = Color(0xFF3FA04A);
  static const _flame = Color(0xFFFF7A00);
  static const _flameCore = Color(0xFFFFD24A);
  static const _moon = Color(0xFFF7EFCF);
  static const _pink = Color(0xFFF39BB8);
  static const _pinkDp = Color(0xFFDB5C86);
  static const _peaBlue = Color(0xFF1E6FB0);
  static const _peaGreen = Color(0xFF1F9E77);

  @override
  void paint(Canvas canvas, Size size) {
    final s = size.width;
    Offset p(double x, double y) => Offset(x * s, y * s);
    final fill = Paint()
      ..style = PaintingStyle.fill
      ..isAntiAlias = true;
    final stroke = Paint()
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round
      ..isAntiAlias = true;

    switch (motif) {
      case 'moonFull':
        // à¦¨à¦°à¦® à¦†à¦²à§‹à¦° à¦¬à¦²à¦¯à¦¼ + à¦ªà§‚à¦°à§à¦£ à¦šà¦¾à¦à¦¦ + à¦•à¦¯à¦¼à§‡à¦•à¦Ÿà¦¾ à¦¹à¦¾à¦²à¦•à¦¾ à¦—à¦°à§à¦¤
        fill.color = _goldLt.withValues(alpha: 0.28);
        canvas.drawCircle(p(0.5, 0.5), s * 0.46, fill);
        fill.color = _moon;
        canvas.drawCircle(p(0.5, 0.5), s * 0.34, fill);
        fill.color = const Color(0xFFE4D9B0);
        canvas.drawCircle(p(0.40, 0.42), s * 0.05, fill);
        canvas.drawCircle(p(0.58, 0.55), s * 0.06, fill);
        canvas.drawCircle(p(0.55, 0.36), s * 0.032, fill);
        break;

      case 'moonNew':
        // à¦…à¦¨à§à¦§à¦•à¦¾à¦° à¦šà¦¾à¦à¦¦, à¦¬à¦¾à¦ à¦¦à¦¿à¦•à§‡ à¦¸à¦°à§ à¦°à§à¦ªà¦¾à¦²à¦¿ à¦•à¦¾à¦¸à§à¦¤à§‡
        fill.color = const Color(0xFF3A3F63);
        canvas.drawCircle(p(0.5, 0.5), s * 0.34, fill);
        final crescent = Path()
          ..addArc(
            Rect.fromCircle(center: p(0.5, 0.5), radius: s * 0.34),
            math.pi * 0.62,
            math.pi * 0.76,
          );
        stroke
          ..color = _moon
          ..strokeWidth = s * 0.05;
        canvas.drawPath(crescent, stroke);
        break;

      case 'diya':
        // à¦ªà§à¦°à¦¦à§€à¦ª â€” à¦®à¦¾à¦Ÿà¦¿à¦° à¦¬à¦¾à¦Ÿà¦¿, à¦¸à§‹à¦¨à¦¾à¦²à¦¿ à¦°à¦¿à¦®, à¦¶à¦¿à¦–à¦¾ à¦“ à¦¨à¦°à¦® à¦†à¦­à¦¾
        fill.color = _flame.withValues(alpha: 0.22);
        canvas.drawCircle(p(0.5, 0.30), s * 0.20, fill);
        // à¦¶à¦¿à¦–à¦¾
        final flame = Path()
          ..moveTo(s * 0.5, s * 0.14)
          ..cubicTo(s * 0.62, s * 0.30, s * 0.60, s * 0.44, s * 0.5, s * 0.46)
          ..cubicTo(s * 0.40, s * 0.44, s * 0.38, s * 0.30, s * 0.5, s * 0.14)
          ..close();
        fill.color = _flame;
        canvas.drawPath(flame, fill);
        final flameIn = Path()
          ..moveTo(s * 0.5, s * 0.24)
          ..cubicTo(s * 0.56, s * 0.32, s * 0.55, s * 0.41, s * 0.5, s * 0.43)
          ..cubicTo(s * 0.45, s * 0.41, s * 0.44, s * 0.32, s * 0.5, s * 0.24)
          ..close();
        fill.color = _flameCore;
        canvas.drawPath(flameIn, fill);
        // à¦¬à¦¾à¦Ÿà¦¿
        final bowl = Path()
          ..moveTo(s * 0.16, s * 0.60)
          ..cubicTo(s * 0.24, s * 0.86, s * 0.76, s * 0.86, s * 0.84, s * 0.60)
          ..close();
        fill.color = const Color(0xFFB5502A);
        canvas.drawPath(bowl, fill);
        // à¦°à¦¿à¦®
        stroke
          ..color = _gold
          ..strokeWidth = s * 0.05;
        canvas.drawLine(p(0.16, 0.60), p(0.84, 0.60), stroke);
        fill.color = _goldLt;
        canvas.drawCircle(p(0.5, 0.60), s * 0.05, fill);
        break;

      case 'lotus':
        {
          // à¦ªà¦¦à§à¦® â€” à¦ªà§‡à¦›à¦¨à§‡à¦° à¦¸à¦¾à¦°à¦¿ à¦¹à¦¾à¦²à¦•à¦¾, à¦¸à¦¾à¦®à¦¨à§‡à¦° à¦¸à¦¾à¦°à¦¿ à¦—à¦¾à¦¢à¦¼ à¦¡à¦—à¦¾
          void petal(double cx, double angle, double len, Color c) {
            canvas.save();
            canvas.translate(cx * s, 0.66 * s);
            canvas.rotate(angle);
            final path = Path()
              ..moveTo(0, 0)
              ..quadraticBezierTo(-len * 0.28 * s, -len * 0.5 * s, 0, -len * s)
              ..quadraticBezierTo(len * 0.28 * s, -len * 0.5 * s, 0, 0)
              ..close();
            fill.color = c;
            canvas.drawPath(path, fill);
            canvas.restore();
          }

          // à¦ªà§‡à¦›à¦¨à§‡à¦° à¦¸à¦¾à¦°à¦¿
          petal(0.5, -0.9, 0.42, _pink.withValues(alpha: 0.8));
          petal(0.5, 0.9, 0.42, _pink.withValues(alpha: 0.8));
          petal(0.5, -0.45, 0.5, _pink);
          petal(0.5, 0.45, 0.5, _pink);
          // à¦¸à¦¾à¦®à¦¨à§‡à¦° à¦•à§‡à¦¨à§à¦¦à§à¦°à§€à¦¯à¦¼ à¦ªà¦¾à¦ªà¦¡à¦¼à¦¿
          petal(0.5, 0.0, 0.56, _pinkDp);
          petal(0.5, -0.22, 0.52, _pink);
          petal(0.5, 0.22, 0.52, _pink);
          fill.color = _goldLt;
          canvas.drawCircle(p(0.5, 0.62), s * 0.05, fill);
        }
        break;

      case 'sun':
        // à¦¸à§‚à¦°à§à¦¯ â€” à¦•à§‡à¦¨à§à¦¦à§à¦° à¦“ à¦šà¦¾à¦°à¦ªà¦¾à¦¶à§‡ à¦°à¦¶à§à¦®à¦¿ (à¦¸à¦‚à¦•à§à¦°à¦¾à¦¨à§à¦¤à¦¿)
        stroke
          ..color = _saffron
          ..strokeWidth = s * 0.045;
        for (int i = 0; i < 12; i++) {
          final a = i * math.pi / 6;
          canvas.drawLine(
            p(0.5 + 0.30 * math.cos(a), 0.5 + 0.30 * math.sin(a)),
            p(0.5 + 0.42 * math.cos(a), 0.5 + 0.42 * math.sin(a)),
            stroke,
          );
        }
        fill.color = _saffronLt;
        canvas.drawCircle(p(0.5, 0.5), s * 0.24, fill);
        fill.color = _saffron;
        canvas.drawCircle(p(0.5, 0.5), s * 0.16, fill);
        break;

      case 'trishul':
        // à¦¤à§à¦°à¦¿à¦¶à§‚à¦² â€” à¦¦à§à¦°à§à¦—à¦¾/à¦¶à¦•à§à¦¤à¦¿à¦° à¦ªà§à¦°à¦¤à§€à¦•
        stroke
          ..color = _gold
          ..strokeWidth = s * 0.055;
        canvas.drawLine(p(0.5, 0.30), p(0.5, 0.9), stroke);
        // à¦®à¦¾à¦à§‡à¦° à¦«à¦²à¦¾
        final mid = Path()
          ..moveTo(s * 0.5, s * 0.08)
          ..lineTo(s * 0.44, s * 0.30)
          ..lineTo(s * 0.56, s * 0.30)
          ..close();
        fill.color = _gold;
        canvas.drawPath(mid, fill);
        // à¦ªà¦¾à¦¶à§‡à¦° à¦¦à§à¦‡ à¦¬à¦¾à¦à¦•à¦¾à¦¨à§‹ à¦«à¦²à¦¾
        stroke.strokeWidth = s * 0.05;
        final left = Path()
          ..moveTo(s * 0.30, s * 0.16)
          ..quadraticBezierTo(s * 0.30, s * 0.34, s * 0.42, s * 0.34);
        final right = Path()
          ..moveTo(s * 0.70, s * 0.16)
          ..quadraticBezierTo(s * 0.70, s * 0.34, s * 0.58, s * 0.34);
        canvas.drawPath(left, stroke);
        canvas.drawPath(right, stroke);
        canvas.drawLine(p(0.30, 0.16), p(0.30, 0.30), stroke);
        canvas.drawLine(p(0.70, 0.16), p(0.70, 0.30), stroke);
        // à¦¬à¦¾à¦à¦§à¦¨
        fill.color = _red;
        canvas.drawCircle(p(0.5, 0.34), s * 0.045, fill);
        break;

      case 'temple':
        // à¦®à¦¨à§à¦¦à¦¿à¦° â€” à¦šà§‚à¦¡à¦¼à¦¾ (à¦¶à¦¿à¦–à¦°), à¦•à¦²à¦¸ à¦“ à¦ªà¦¤à¦¾à¦•à¦¾
        fill.color = _saffronLt;
        // à¦®à§‚à¦² à¦•à¦¾à¦ à¦¾à¦®à§‹
        canvas.drawRRect(
          RRect.fromRectAndRadius(
            Rect.fromLTWH(s * 0.28, s * 0.55, s * 0.44, s * 0.35),
            Radius.circular(s * 0.02),
          ),
          fill,
        );
        // à¦¶à¦¿à¦–à¦° (à¦¤à§à¦°à¦¿à¦­à§à¦œà¦¾à¦•à¦¾à¦° à¦¸à§à¦¤à¦°)
        final spire = Path()
          ..moveTo(s * 0.5, s * 0.14)
          ..lineTo(s * 0.30, s * 0.55)
          ..lineTo(s * 0.70, s * 0.55)
          ..close();
        fill.color = _saffron;
        canvas.drawPath(spire, fill);
        // à¦¦à¦°à¦œà¦¾
        fill.color = _navy;
        final door = Path()
          ..moveTo(s * 0.43, s * 0.90)
          ..lineTo(s * 0.43, s * 0.68)
          ..arcToPoint(
            Offset(s * 0.57, s * 0.68),
            radius: Radius.circular(s * 0.07),
          )
          ..lineTo(s * 0.57, s * 0.90)
          ..close();
        canvas.drawPath(door, fill);
        // à¦•à¦²à¦¸ + à¦ªà¦¤à¦¾à¦•à¦¾
        fill.color = _gold;
        canvas.drawCircle(p(0.5, 0.12), s * 0.04, fill);
        stroke
          ..color = _gold
          ..strokeWidth = s * 0.03;
        canvas.drawLine(p(0.5, 0.12), p(0.5, 0.03), stroke);
        fill.color = _red;
        final flag = Path()
          ..moveTo(s * 0.5, s * 0.03)
          ..lineTo(s * 0.66, s * 0.07)
          ..lineTo(s * 0.5, s * 0.11)
          ..close();
        canvas.drawPath(flag, fill);
        break;

      case 'veena':
        // à¦¸à¦°à¦¸à§à¦¬à¦¤à§€à¦° à¦¬à§€à¦£à¦¾ â€” à¦¸à¦°à¦²à§€à¦•à§ƒà¦¤: à¦²à¦®à§à¦¬à¦¾ à¦¦à¦£à§à¦¡, à¦—à§‹à¦² à¦…à¦¨à§à¦°à¦£à¦• à¦“ à¦¤à¦¾à¦°
        stroke
          ..color = _gold
          ..strokeWidth = s * 0.05;
        canvas.drawLine(p(0.28, 0.78), p(0.74, 0.24), stroke);
        fill.color = _saffronLt;
        canvas.drawCircle(p(0.26, 0.80), s * 0.14, fill);
        fill.color = _saffron;
        canvas.drawCircle(p(0.26, 0.80), s * 0.09, fill);
        fill.color = _cream;
        canvas.drawCircle(p(0.76, 0.22), s * 0.06, fill);
        stroke
          ..color = _navy
          ..strokeWidth = s * 0.018;
        canvas.drawLine(p(0.30, 0.74), p(0.72, 0.28), stroke);
        break;

      case 'shiva':
        // à¦¶à¦¿à¦¬ â€” à¦¤à§à¦°à¦¿à¦¶à§‚à¦²à§‡à¦° à¦¸à¦¾à¦¥à§‡ à¦…à¦°à§à¦§à¦šà¦¨à§à¦¦à§à¦°
        stroke
          ..color = _navy
          ..strokeWidth = s * 0.05;
        canvas.drawLine(p(0.5, 0.34), p(0.5, 0.9), stroke);
        final tri = Path()
          ..moveTo(s * 0.5, s * 0.20)
          ..lineTo(s * 0.45, s * 0.34)
          ..lineTo(s * 0.55, s * 0.34)
          ..close();
        fill.color = _navy;
        canvas.drawPath(tri, fill);
        stroke.strokeWidth = s * 0.045;
        canvas.drawLine(p(0.33, 0.24), p(0.33, 0.34), stroke);
        canvas.drawLine(p(0.67, 0.24), p(0.67, 0.34), stroke);
        // à¦…à¦°à§à¦§à¦šà¦¨à§à¦¦à§à¦°
        stroke
          ..color = _gold
          ..strokeWidth = s * 0.05;
        canvas.drawArc(
          Rect.fromCircle(center: p(0.5, 0.14), radius: s * 0.12),
          math.pi * 0.15,
          math.pi * 0.7,
          false,
          stroke,
        );
        break;

      case 'peacock':
        // à¦®à¦¯à¦¼à§‚à¦°à¦ªà¦¾à¦²à¦• â€” à¦œà¦¨à§à¦®à¦¾à¦·à§à¦Ÿà¦®à§€/à¦•à§ƒà¦·à§à¦£
        stroke
          ..color = _peaGreen
          ..strokeWidth = s * 0.03;
        canvas.drawLine(p(0.5, 0.9), p(0.5, 0.34), stroke);
        // à¦ªà¦¾à¦²à¦•à§‡à¦° à¦šà§‹à¦–
        fill.color = _peaBlue.withValues(alpha: 0.85);
        canvas.drawOval(
          Rect.fromCenter(
            center: p(0.5, 0.28),
            width: s * 0.36,
            height: s * 0.5,
          ),
          fill,
        );
        fill.color = _peaGreen;
        canvas.drawOval(
          Rect.fromCenter(
            center: p(0.5, 0.30),
            width: s * 0.24,
            height: s * 0.34,
          ),
          fill,
        );
        fill.color = _gold;
        canvas.drawCircle(p(0.5, 0.30), s * 0.08, fill);
        fill.color = _navy;
        canvas.drawCircle(p(0.5, 0.31), s * 0.045, fill);
        // barbs
        stroke
          ..color = _peaGreen.withValues(alpha: 0.7)
          ..strokeWidth = s * 0.02;
        for (int i = 0; i < 4; i++) {
          final y = 0.5 + i * 0.1;
          canvas.drawLine(p(0.5, y), p(0.5 - 0.12, y - 0.05), stroke);
          canvas.drawLine(p(0.5, y), p(0.5 + 0.12, y - 0.05), stroke);
        }
        break;

      case 'flower':
        // à¦—à¦¾à¦à¦¦à¦¾/à¦¸à¦¾à¦§à¦¾à¦°à¦£ à¦«à§à¦² â€” à¦¬à¦¸à¦¨à§à¦¤/à¦¦à§‹à¦²
        fill.color = _saffron;
        for (int i = 0; i < 8; i++) {
          final a = i * math.pi / 4;
          canvas.drawCircle(
            p(0.5 + 0.22 * math.cos(a), 0.5 + 0.22 * math.sin(a)),
            s * 0.11,
            fill,
          );
        }
        fill.color = _saffronLt;
        for (int i = 0; i < 8; i++) {
          final a = i * math.pi / 4 + math.pi / 8;
          canvas.drawCircle(
            p(0.5 + 0.14 * math.cos(a), 0.5 + 0.14 * math.sin(a)),
            s * 0.08,
            fill,
          );
        }
        fill.color = _gold;
        canvas.drawCircle(p(0.5, 0.5), s * 0.10, fill);
        break;

      case 'rakhi':
        // à¦°à¦¾à¦–à¦¿ â€” à¦®à¦¾à¦à§‡ à¦°à§‹à¦œà§‡à¦Ÿ, à¦¦à§à¦‡ à¦ªà¦¾à¦¶à§‡ à¦¸à§à¦¤à§‹
        stroke
          ..color = _red
          ..strokeWidth = s * 0.05;
        canvas.drawLine(p(0.05, 0.5), p(0.30, 0.5), stroke);
        canvas.drawLine(p(0.70, 0.5), p(0.95, 0.5), stroke);
        fill.color = _gold;
        for (int i = 0; i < 8; i++) {
          final a = i * math.pi / 4;
          canvas.drawCircle(
            p(0.5 + 0.16 * math.cos(a), 0.5 + 0.16 * math.sin(a)),
            s * 0.07,
            fill,
          );
        }
        fill.color = _red;
        canvas.drawCircle(p(0.5, 0.5), s * 0.11, fill);
        fill.color = _goldLt;
        canvas.drawCircle(p(0.5, 0.5), s * 0.05, fill);
        break;

      case 'coin':
        // à¦¸à§à¦¬à¦°à§à¦£à¦®à§à¦¦à§à¦°à¦¾ â€” à¦§à¦¨à¦¤à§‡à¦°à¦¾à¦¸
        fill.color = _gold;
        canvas.drawCircle(p(0.5, 0.5), s * 0.34, fill);
        stroke
          ..color = _goldLt
          ..strokeWidth = s * 0.04;
        canvas.drawCircle(p(0.5, 0.5), s * 0.27, stroke);
        // à¦•à§‡à¦¨à§à¦¦à§à¦°à§‡ à¦¤à¦¾à¦°à¦¾
        fill.color = _cream;
        final star = Path();
        for (int i = 0; i < 10; i++) {
          final r = i.isEven ? 0.16 : 0.07;
          final a = -math.pi / 2 + i * math.pi / 5;
          final pt = p(0.5 + r * math.cos(a), 0.5 + r * math.sin(a));
          if (i == 0) {
            star.moveTo(pt.dx, pt.dy);
          } else {
            star.lineTo(pt.dx, pt.dy);
          }
        }
        star.close();
        canvas.drawPath(star, fill);
        break;

      case 'flag':
        // à¦¤à§‡à¦°à¦™à¦¾ â€” à¦œà¦¾à¦¤à§€à¦¯à¦¼ à¦¦à¦¿à¦¬à¦¸
        stroke
          ..color = const Color(0xFF7A5230)
          ..strokeWidth = s * 0.035;
        canvas.drawLine(p(0.22, 0.12), p(0.22, 0.92), stroke);
        fill.color = _saffron;
        canvas.drawRect(
          Rect.fromLTWH(s * 0.24, s * 0.20, s * 0.54, s * 0.12),
          fill,
        );
        fill.color = Colors.white;
        canvas.drawRect(
          Rect.fromLTWH(s * 0.24, s * 0.32, s * 0.54, s * 0.12),
          fill,
        );
        fill.color = _green;
        canvas.drawRect(
          Rect.fromLTWH(s * 0.24, s * 0.44, s * 0.54, s * 0.12),
          fill,
        );
        stroke
          ..color = _navy
          ..strokeWidth = s * 0.02;
        canvas.drawCircle(p(0.51, 0.38), s * 0.045, stroke);
        break;

      case 'tulsi':
        // à¦¤à§à¦²à¦¸à§€ à¦®à¦žà§à¦š â€” à¦à¦•à¦¾à¦¦à¦¶à§€/à¦¬à§à¦°à¦¤
        fill.color = const Color(0xFFB5502A);
        canvas.drawRRect(
          RRect.fromRectAndRadius(
            Rect.fromLTWH(s * 0.34, s * 0.55, s * 0.32, s * 0.34),
            Radius.circular(s * 0.03),
          ),
          fill,
        );
        fill.color = const Color(0xFF8E3F20);
        canvas.drawRect(
          Rect.fromLTWH(s * 0.30, s * 0.52, s * 0.40, s * 0.06),
          fill,
        );
        // à¦—à¦¾à¦›
        stroke
          ..color = _green
          ..strokeWidth = s * 0.035;
        canvas.drawLine(p(0.5, 0.55), p(0.5, 0.30), stroke);
        fill.color = _leaf;
        for (int i = 0; i < 6; i++) {
          final a = -math.pi / 2 + (i - 2.5) * 0.5;
          canvas.drawOval(
            Rect.fromCenter(
              center: p(0.5 + 0.16 * math.cos(a), 0.34 + 0.14 * math.sin(a)),
              width: s * 0.12,
              height: s * 0.07,
            ),
            fill,
          );
        }
        fill.color = _green;
        canvas.drawCircle(p(0.5, 0.24), s * 0.06, fill);
        break;

      case 'star':
      default:
        // à¦¸à¦¾à¦§à¦¾à¦°à¦£ à¦…à¦²à¦™à§à¦•à¦°à¦£ â€” à¦†à¦Ÿ-à¦•à§‹à¦£à¦¾ à¦¤à¦¾à¦°à¦¾
        fill.color = _goldLt;
        final st = Path();
        for (int i = 0; i < 16; i++) {
          final r = i.isEven ? 0.40 : 0.17;
          final a = -math.pi / 2 + i * math.pi / 8;
          final pt = p(0.5 + r * math.cos(a), 0.5 + r * math.sin(a));
          if (i == 0) {
            st.moveTo(pt.dx, pt.dy);
          } else {
            st.lineTo(pt.dx, pt.dy);
          }
        }
        st.close();
        canvas.drawPath(st, fill);
        fill.color = _gold;
        canvas.drawCircle(p(0.5, 0.5), s * 0.10, fill);
        break;
    }
  }

  @override
  bool shouldRepaint(covariant _PanjikaArtPainter old) => old.motif != motif;
}

