class _TodaySmartLaunchCard extends StatelessWidget {
  const _TodaySmartLaunchCard();

  @override
  Widget build(BuildContext context) {
    final now = DateTime.now();
    final sun = PanchangCalculator.sunTimes(
      now,
      lat: AppLocation.lat,
      lon: AppLocation.lon,
    );
    final tithi = PanchangCalculator.tithiFor(sun.sunrise);
    final rahu = PanchangCalculator.rahuKalam(
      now,
      lat: AppLocation.lat,
      lon: AppLocation.lon,
    );

    return InkWell(
      onTap: () => Navigator.push(
        context,
        MaterialPageRoute(builder: (_) => const TodaySmartScreen()),
      ),
      borderRadius: BorderRadius.circular(18),
      child: Container(
        width: double.infinity,
