class DateConverterScreen extends StatefulWidget {
  const DateConverterScreen({super.key});

  @override
  State<DateConverterScreen> createState() => _DateConverterScreenState();
}

class _DateConverterScreenState extends State<DateConverterScreen> {
  static const _months = [
    'à¦¬à§ˆà¦¶à¦¾à¦–',
    'à¦œà§à¦¯à§ˆà¦·à§à¦ ',
    'à¦†à¦·à¦¾à¦¢à¦¼',
    'à¦¶à§à¦°à¦¾à¦¬à¦£',
    'à¦­à¦¾à¦¦à§à¦°',
    'à¦†à¦¶à§à¦¬à¦¿à¦¨',
    'à¦•à¦¾à¦°à§à¦¤à¦¿à¦•',
    'à¦…à¦—à§à¦°à¦¹à¦¾à¦¯à¦¼à¦£',
    'à¦ªà§Œà¦·',
    'à¦®à¦¾à¦˜',
    'à¦«à¦¾à¦²à§à¦—à§à¦¨',
    'à¦šà§ˆà¦¤à§à¦°',
  ];

  DateTime _englishDate = DateTime.now();
  late int _bYear;
  late String _bMonth;
  late int _bDay;

  @override
  void initState() {
    super.initState();
    final info = BengaliDateUtil.monthInfoFor(_englishDate);
    _bYear = info.year;
    _bMonth = info.name;
    _bDay = _englishDate.difference(info.start).inDays + 1;
  }

  BengaliMonthInfo? _findBengaliMonth(int year, String month) {
    final start = DateTime(year + 593, 1, 1);
    final end = DateTime(year + 594, 12, 31);
    var d = start;
    while (!d.isAfter(end)) {
      final info = BengaliDateUtil.monthInfoFor(d);
      if (info.year == year && info.name == month) return info;
      d = info.end.add(const Duration(days: 1));
    }
    return null;
  }

  DateTime? get _convertedGregorian {
    final info = _findBengaliMonth(_bYear, _bMonth);
    if (info == null) return null;
    final total = info.end.difference(info.start).inDays + 1;
    final day = _bDay.clamp(1, total).toInt();
    return info.start.add(Duration(days: day - 1));
  }

  Future<void> _pickEnglish() async {
    final d = await showDatePicker(
      context: context,
      initialDate: _englishDate,
      firstDate: DateTime(1950),
      lastDate: DateTime(2100),
    );
    if (d == null) return;
    setState(() => _englishDate = d);
  }

  Widget _glass(Widget child) {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: const Color(0xFF07172F).withValues(alpha: 0.62),
        borderRadius: BorderRadius.circular(18),
        border: Border.all(color: Colors.white.withValues(alpha: 0.13)),
      ),
      child: child,
    );
  }

  @override
  Widget build(BuildContext context) {
    final eInfo = BengaliDateUtil.monthInfoFor(_englishDate);
    final eBDay = _englishDate.difference(eInfo.start).inDays + 1;
    final greg = _convertedGregorian;
    final bInfo = _findBengaliMonth(_bYear, _bMonth);
    final bMax = bInfo == null
        ? 30
        : bInfo.end.difference(bInfo.start).inDays + 1;
    final safeBDay = _bDay.clamp(1, bMax).toInt();

    return CosmicBackground(
      child: Column(
        children: [
          const _ScreenHeader(
            title:
                'ðŸ”„ à¦¬à¦¾à¦‚à¦²à¦¾ â†” à¦‡à¦‚à¦°à§‡à¦œà¦¿ à¦¤à¦¾à¦°à¦¿à¦–',
          ),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.fromLTRB(16, 12, 16, 30),
              children: [
                const SizedBox(height: 155),
                _glass(
                  Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Text(
                        'à¦‡à¦‚à¦°à§‡à¦œà¦¿ â†’ à¦¬à¦¾à¦‚à¦²à¦¾',
