class MonthSummaryScreen extends StatefulWidget {
  const MonthSummaryScreen({super.key});

  @override
  State<MonthSummaryScreen> createState() => _MonthSummaryScreenState();
}

class _MonthSummaryScreenState extends State<MonthSummaryScreen> {
  DateTime _anchor = DateTime.now();

  void _change(int dir) {
    final info = BengaliDateUtil.monthInfoFor(_anchor);
    setState(() {
      _anchor = dir < 0
          ? info.start.subtract(const Duration(days: 1))
          : info.end.add(const Duration(days: 1));
    });
  }

  Widget _stat(String icon, String label, int count) {
    return Container(
      padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 8),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.06),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: Colors.white.withValues(alpha: 0.10)),
      ),
      child: Column(
        children: [
          Text(icon, style: const TextStyle(fontSize: 20)),
          const SizedBox(height: 4),
          Text(
            bnNum(count),
            style: const TextStyle(
              color: Color(0xFFFFD36E),
              fontSize: 17,
              fontWeight: FontWeight.w900,
            ),
          ),
          Text(
            label,
            textAlign: TextAlign.center,
            style: const TextStyle(color: Colors.white70, fontSize: 9.5),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final info = BengaliDateUtil.monthInfoFor(_anchor);
    final total = info.end.difference(info.start).inDays + 1;
    final rows = <Map<String, dynamic>>[];
    final counts = <String, int>{};

    for (var i = 0; i < total; i++) {
      final d = info.start.add(Duration(days: i));
      final events = BengaliCalendarData.eventsFor(d);
      if (events.isEmpty) continue;
      rows.add({'date': d, 'day': i + 1, 'events': events});
      for (final e in events) {
        counts[e.category] = (counts[e.category] ?? 0) + 1;
      }
    }

    const goodKeys = {
      'marriage',
      'annaprashan',
      'griha',
      'byabosha',
      'namakaran',
      'jomi',
      'bari',
      'gari',
    };
    final goodCount = counts.entries
        .where((e) => goodKeys.contains(e.key))
        .fold<int>(0, (a, b) => a + b.value);

    return CosmicBackground(
      child: Column(
        children: [
          const _ScreenHeader(title: 'ðŸ“Š à¦®à¦¾à¦¸à§‡à¦° Summary'),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.fromLTRB(16, 12, 16, 30),
              children: [
                const SizedBox(height: 155),
                Container(
                  padding: const EdgeInsets.all(14),
                  decoration: BoxDecoration(
                    color: const Color(0xFF07172F).withValues(alpha: 0.62),
                    borderRadius: BorderRadius.circular(18),
                    border: Border.all(
                      color: const Color(0xFFFFD36E).withValues(alpha: 0.24),
                    ),
                  ),
                  child: Column(
                    children: [
                      Row(
                        children: [
                          IconButton(
                            onPressed: () => _change(-1),
                            icon: const Icon(
                              Icons.chevron_left,
                              color: Colors.white,
                            ),
                          ),
                          Expanded(
                            child: Text(
                              '${info.name} ${bnNum(info.year)}',
                              textAlign: TextAlign.center,
                              style: const TextStyle(
                                color: Color(0xFFFFD36E),
                                fontSize: 21,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                          ),
                          IconButton(
                            onPressed: () => _change(1),
                            icon: const Icon(
                              Icons.chevron_right,
                              color: Colors.white,
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 10),
                      GridView.count(
                        shrinkWrap: true,
                        physics: const NeverScrollableScrollPhysics(),
                        crossAxisCount: 3,
                        crossAxisSpacing: 8,
                        mainAxisSpacing: 8,
                        childAspectRatio: 1.05,
                        children: [
                          _stat('ðŸŽ‰', 'à¦‰à§Žà¦¸à¦¬', counts['general'] ?? 0),
                          _stat(
                            'ðŸŒ¿',
                            'à¦à¦•à¦¾à¦¦à¦¶à§€',
                            counts['ekadashi'] ?? 0,
                          ),
                          _stat(
                            'ðŸŒ•',
                            'à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾',
                            counts['purnima'] ?? 0,
                          ),
                          _stat(
                            'ðŸŒ‘',
                            'à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾',
                            counts['amabasya'] ?? 0,
                          ),
                          _stat('â­', 'à¦¶à§à¦­à¦¦à¦¿à¦¨', goodCount),
                          _stat(
                            'ðŸ“Œ',
                            'à¦®à§‹à¦Ÿ à¦¬à¦¿à¦¶à§‡à¦·',
                            rows.length,
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: 14),
                const Text(
                  'à¦à¦‡ à¦®à¦¾à¦¸à§‡à¦° à¦¬à¦¿à¦¶à§‡à¦· à¦¦à¦¿à¦¨',
                  style: TextStyle(
                    color: Colors.white,
                    fontSize: 15,
                    fontWeight: FontWeight.w800,
                  ),
                ),
                const SizedBox(height: 9),
                if (rows.isEmpty)
                  const Text(
                    'à¦à¦‡ à¦®à¦¾à¦¸à§‡ à¦†à¦²à¦¾à¦¦à¦¾ à¦•à§‹à¦¨à§‹ event à¦ªà¦¾à¦“à§Ÿà¦¾ à¦¯à¦¾à§Ÿà¦¨à¦¿à¥¤',
                    style: TextStyle(color: Colors.white70),
                  )
                else
                  ...rows.map((row) {
                    final d = row['date'] as DateTime;
                    final day = row['day'] as int;
                    final events = row['events'] as List<CalendarEvent>;
                    return Container(
                      margin: const EdgeInsets.only(bottom: 8),
                      padding: const EdgeInsets.all(12),
                      decoration: BoxDecoration(
                        color: const Color(0xFF07172F).withValues(alpha: 0.58),
                        borderRadius: BorderRadius.circular(15),
