class JapaCounterScreen extends StatefulWidget {
  const JapaCounterScreen({super.key});

  @override
  State<JapaCounterScreen> createState() => _JapaCounterScreenState();
}

class _JapaCounterScreenState extends State<JapaCounterScreen> {
  static const _countKey = 'japa_counter_count';
  static const _roundKey = 'japa_counter_rounds';

  int _count = 0;
  int _rounds = 0;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final p = await SharedPreferences.getInstance();
    if (!mounted) return;
    setState(() {
      _count = p.getInt(_countKey) ?? 0;
      _rounds = p.getInt(_roundKey) ?? 0;
    });
  }

  Future<void> _save() async {
    final p = await SharedPreferences.getInstance();
    await p.setInt(_countKey, _count);
    await p.setInt(_roundKey, _rounds);
  }

  void _add() {
    setState(() {
      _count++;
      if (_count >= 108) {
        _count = 0;
        _rounds++;
      }
    });
    _save();
  }

  void _minus() {
    if (_count <= 0) return;
    setState(() => _count--);
    _save();
  }

  void _reset() {
    setState(() {
      _count = 0;
      _rounds = 0;
    });
    _save();
  }

  @override
  Widget build(BuildContext context) {
    return CosmicBackground(
      child: Column(
        children: [
          const _ScreenHeader(title: 'ðŸ“¿ à¦œà¦ª à¦•à¦¾à¦‰à¦¨à§à¦Ÿà¦¾à¦°'),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.fromLTRB(16, 12, 16, 30),
              children: [
                const SizedBox(height: 170),
                Container(
                  padding: const EdgeInsets.all(22),
                  decoration: BoxDecoration(
                    color: const Color(0xFF07172F).withValues(alpha: 0.66),
                    borderRadius: BorderRadius.circular(26),
                    border: Border.all(
                      color: const Color(0xFFFFD36E).withValues(alpha: 0.30),
                    ),
                  ),
                  child: Column(
                    children: [
                      const Text(
