class _PujaChecklistScreenState extends State<PujaChecklistScreen> {
  static const _itemsKey = 'puja_checklist_items_v1';
  static const _doneKey = 'puja_checklist_done_v1';
  static const _defaultItems = [
    'à¦«à§à¦²',
    'à¦¬à§‡à¦²à¦ªà¦¾à¦¤à¦¾ / à¦¤à§à¦²à¦¸à§€',
    'à¦§à§‚à¦ª',
    'à¦ªà§à¦°à¦¦à§€à¦ª',
    'à¦¤à§‡à¦² / à¦˜à¦¿',
    'à¦«à¦²',
    'à¦®à¦¿à¦·à§à¦Ÿà¦¿ / à¦ªà§à¦°à¦¸à¦¾à¦¦',
    'à¦œà¦² / à¦—à¦™à§à¦—à¦¾à¦œà¦²',
    'à¦šà¦¨à§à¦¦à¦¨',
    'à¦ªà§‚à¦œà¦¾à¦° à¦†à¦¸à¦¨',
  ];

  final _controller = TextEditingController();
  List<String> _items = [..._defaultItems];
  Set<String> _done = {};

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final p = await SharedPreferences.getInstance();
    if (!mounted) return;
    setState(() {
      _items = p.getStringList(_itemsKey) ?? [..._defaultItems];
      _done = (p.getStringList(_doneKey) ?? const <String>[]).toSet();
    });
  }

  Future<void> _save() async {
    final p = await SharedPreferences.getInstance();
    await p.setStringList(_itemsKey, _items);
    await p.setStringList(_doneKey, _done.toList());
  }

  void _add() {
    final v = _controller.text.trim();
    if (v.isEmpty || _items.contains(v)) return;
    setState(() {
      _items.add(v);
      _controller.clear();
    });
    _save();
  }

  void _resetDone() {
    setState(() => _done.clear());
    _save();
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final completed = _items.where(_done.contains).length;
    return CosmicBackground(
      child: Column(
        children: [
          const _ScreenHeader(title: 'âœ… à¦ªà§‚à¦œà¦¾ Checklist'),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.fromLTRB(16, 12, 16, 30),
              children: [
                const SizedBox(height: 155),
                Container(
                  padding: const EdgeInsets.all(14),
                  decoration: BoxDecoration(
                    color: const Color(0xFF07172F).withValues(alpha: 0.62),
                    borderRadius: BorderRadius.circular(18),
                    border: Border.all(
                      color: const Color(0xFFFFD36E).withValues(alpha: 0.24),
                    ),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        'à¦ªà§à¦°à¦¸à§à¦¤à§à¦¤à¦¿ ${bnNum(completed)}/${bnNum(_items.length)}',
                        style: const TextStyle(
                          color: Color(0xFFFFD36E),
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                      const SizedBox(height: 8),
                      LinearProgressIndicator(
                        value: _items.isEmpty ? 0 : completed / _items.length,
                        backgroundColor: Colors.white12,
                      ),
                      const SizedBox(height: 12),
                      Row(
                        children: [
                          Expanded(
                            child: TextField(
                              controller: _controller,
                              style: const TextStyle(color: Colors.white),
                              decoration: InputDecoration(
                                hintText:
                                    'à¦¨à¦¿à¦œà§‡à¦° à¦¸à¦¾à¦®à¦—à§à¦°à§€ à¦¯à§‹à¦— à¦•à¦°à§à¦¨',
                                hintStyle: const TextStyle(
                                  color: Colors.white54,
                                ),
                                filled: true,
                                fillColor: Colors.white.withValues(alpha: 0.06),
                                border: OutlineInputBorder(
                                  borderRadius: BorderRadius.circular(14),
                                  borderSide: BorderSide.none,
                                ),
                              ),
                              onSubmitted: (_) => _add(),
                            ),
                          ),
                          const SizedBox(width: 8),
                          IconButton.filled(
                            onPressed: _add,
                            icon: const Icon(Icons.add),
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: 12),
                ..._items.map(
                  (item) => Container(
                    margin: const EdgeInsets.only(bottom: 7),
                    decoration: BoxDecoration(
                      color: const Color(0xFF07172F).withValues(alpha: 0.56),
                      borderRadius: BorderRadius.circular(14),
                      border: Border.all(
                        color: Colors.white.withValues(alpha: 0.10),
                      ),
                    ),
                    child: CheckboxListTile(
                      value: _done.contains(item),
                      activeColor: const Color(0xFFFFD36E),
                      checkColor: const Color(0xFF071428),
                      title: Text(
                        item,
                        style: TextStyle(
                          color: _done.contains(item)
                              ? Colors.white54
                              : Colors.white,
                          decoration: _done.contains(item)
                              ? TextDecoration.lineThrough
                              : null,
                        ),
                      ),
                      onChanged: (v) {
                        setState(() {
                          if (v == true) {
                            _done.add(item);
                          } else {
                            _done.remove(item);
                          }
                        });
                        _save();
                      },
                    ),
                  ),
                ),
                TextButton.icon(
                  onPressed: _resetDone,
                  icon: const Icon(Icons.refresh),
                  label: const Text('à¦¸à¦¬ tick reset à¦•à¦°à§à¦¨'),
                  style: TextButton.styleFrom(foregroundColor: Colors.white70),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class FavouriteDayScreen extends StatefulWidget {
  const FavouriteDayScreen({super.key});

  @override
  State<FavouriteDayScreen> createState() => _FavouriteDayScreenState();
}

class _FavouriteDayScreenState extends State<FavouriteDayScreen> {
  static const _key = 'favourite_days_v1';
  final List<Map<String, dynamic>> _items = [];

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final p = await SharedPreferences.getInstance();
    final raw = p.getStringList(_key) ?? const [];
    final loaded = <Map<String, dynamic>>[];
    for (final s in raw) {
      try {
        final m = jsonDecode(s) as Map<String, dynamic>;
        loaded.add(m);
      } catch (_) {}
    }
    if (!mounted) return;
    setState(() {
      _items
        ..clear()
        ..addAll(loaded);
    });
  }

  Future<void> _save() async {
    final p = await SharedPreferences.getInstance();
    await p.setStringList(_key, _items.map((e) => jsonEncode(e)).toList());
  }

  Future<void> _add() async {
    final now = DateTime.now();
    final d = await showDatePicker(
      context: context,
      initialDate: now,
      firstDate: DateTime(now.year - 2),
      lastDate: DateTime(now.year + 5),
    );
    if (d == null || !mounted) return;

    final c = TextEditingController();
    final label = await showDialog<String>(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('à¦¦à¦¿à¦¨à¦Ÿà¦¿à¦° à¦¨à¦¾à¦® à¦¦à¦¿à¦¨'),
        content: TextField(
          controller: c,
          autofocus: true,
          decoration: const InputDecoration(
            hintText:
                'à¦¯à§‡à¦®à¦¨: à¦†à¦®à¦¾à¦¦à§‡à¦° à¦¬à¦¿à¦¬à¦¾à¦¹à¦¬à¦¾à¦°à§à¦·à¦¿à¦•à§€',
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('à¦¬à¦¾à¦¤à¦¿à¦²'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(
              context,
              c.text.trim().isEmpty
                  ? 'à¦ªà§à¦°à¦¿à§Ÿ à¦¦à¦¿à¦¨'
                  : c.text.trim(),
            ),
            child: const Text('Save'),
          ),
        ],
      ),
    );
    c.dispose();
    if (label == null) return;

    setState(() {
      _items.add({'label': label, 'date': d.millisecondsSinceEpoch});
      _items.sort((a, b) => (a['date'] as int).compareTo(b['date'] as int));
    });
    _save();
  }

  @override
  Widget build(BuildContext context) {
    return CosmicBackground(
      child: Column(
        children: [
          const _ScreenHeader(title: 'â¤ï¸ Favourite Day'),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.fromLTRB(16, 12, 16, 30),
              children: [
                const SizedBox(height: 155),
                SizedBox(
                  width: double.infinity,
                  child: FilledButton.icon(
                    onPressed: _add,
                    icon: const Icon(Icons.add),
                    label: const Text(
                      'à¦ªà§à¦°à¦¿à§Ÿ à¦¦à¦¿à¦¨ à¦¯à§‹à¦— à¦•à¦°à§à¦¨',
                    ),
                  ),
                ),
                const SizedBox(height: 12),
                if (_items.isEmpty)
                  const Text(
                    'à¦à¦–à¦¨à§‹ à¦•à§‹à¦¨à§‹ à¦ªà§à¦°à¦¿à§Ÿ à¦¦à¦¿à¦¨ save à¦•à¦°à¦¾ à¦¹à§Ÿà¦¨à¦¿à¥¤',
                    style: TextStyle(color: Colors.white70),
                  )
                else
                  ...List.generate(_items.length, (i) {
                    final item = _items[i];
                    final d = DateTime.fromMillisecondsSinceEpoch(
                      item['date'] as int,
                    );
                    final info = BengaliDateUtil.monthInfoFor(d);
                    final bDay = d.difference(info.start).inDays + 1;
                    return Container(
                      margin: const EdgeInsets.only(bottom: 8),
                      padding: const EdgeInsets.all(12),
                      decoration: BoxDecoration(
                        color: const Color(0xFF07172F).withValues(alpha: 0.60),
                        borderRadius: BorderRadius.circular(15),
                        border: Border.all(
                          color: Colors.white.withValues(alpha: 0.10),
                        ),
                      ),
                      child: Row(
                        children: [
                          const Text('â¤ï¸', style: TextStyle(fontSize: 22)),
                          const SizedBox(width: 10),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(
                                  item['label'].toString(),
                                  style: const TextStyle(
                                    color: Colors.white,
                                    fontWeight: FontWeight.w800,
                                  ),
                                ),
                                const SizedBox(height: 3),
                                Text(
                                  '${d.day}/${d.month}/${d.year} â€¢ ${bnNum(bDay)} ${info.name} ${bnNum(info.year)}',
                                  style: const TextStyle(
                                    color: Colors.white60,
                                    fontSize: 10.5,
                                  ),
                                ),
                              ],
                            ),
