class SearchScreen extends StatefulWidget {
  const SearchScreen({super.key});

  @override
  State<SearchScreen> createState() => _SearchScreenState();
}

class _SearchScreenState extends State<SearchScreen> {
  final TextEditingController _controller = TextEditingController();

  List<_SmartSearchHit> _results = [];
  bool _searched = false;
  bool _busy = false;

  String _bn(int value) {
    const digits = [
      'à§¦',
      'à§§',
      'à§¨',
      'à§©',
      'à§ª',
      'à§«',
      'à§¬',
      'à§­',
      'à§®',
      'à§¯',
    ];

    return value.toString().split('').map((e) => digits[int.parse(e)]).join();
  }

  String _categoryBn(String category) {
    switch (category) {
      case 'ekadashi':
        return 'à¦à¦•à¦¾à¦¦à¦¶à§€';
      case 'purnima':
        return 'à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾';
      case 'amabasya':
        return 'à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾';
      case 'marriage':
        return 'à¦¬à¦¿à¦¬à¦¾à¦¹à§‡à¦° à¦¶à§à¦­ à¦¦à¦¿à¦¨';
      case 'annaprashan':
        return 'à¦…à¦¨à§à¦¨à¦ªà§à¦°à¦¾à¦¶à¦¨';
      case 'griha':
        return 'à¦—à§ƒà¦¹à¦ªà§à¦°à¦¬à§‡à¦¶';
      case 'byabosha':
        return 'à¦¬à§à¦¯à¦¬à¦¸à¦¾à¦° à¦¶à§à¦­ à¦¦à¦¿à¦¨';
      case 'namakaran':
        return 'à¦¨à¦¾à¦®à¦•à¦°à¦£';
      case 'holiday':
        return 'à¦›à§à¦Ÿà¦¿';
      default:
        return category;
    }
  }

  Future<void> _search() async {
    final q = _controller.text.trim().toLowerCase();

    if (q.isEmpty) {
      setState(() {
        _results = [];
        _searched = false;
      });
      return;
    }

    setState(() {
      _busy = true;
      _searched = true;
    });

    await Future<void>.delayed(const Duration(milliseconds: 20));

    final hits = <_SmartSearchHit>[];
    final now = DateTime.now();

    final start = DateTime(
      now.year,
      now.month,
      now.day,
    ).subtract(const Duration(days: 30));

    // à¦†à¦œ à¦¥à§‡à¦•à§‡ à¦ªà§à¦°à¦¾à§Ÿ à§¨ à¦¬à¦›à¦° à¦ªà¦°à§à¦¯à¦¨à§à¦¤ à¦–à§‹à¦à¦œà¦¾ à¦¹à¦¬à§‡à¥¤
    for (int i = 0; i <= 760; i++) {
      final date = start.add(Duration(days: i));

      final events = BengaliCalendarData.eventsFor(date);

      if (events.isEmpty) continue;

      for (final event in events) {
        final categoryText = _categoryBn(event.category);

        final searchable = '${event.label} $categoryText ${event.category}'
            .toLowerCase();

        if (!searchable.contains(q)) {
          continue;
        }

        final info = BengaliDateUtil.monthInfoFor(date);

        final bengaliDay = date.difference(info.start).inDays + 1;

        hits.add(
          _SmartSearchHit(
            date: date,
            bengaliDay: bengaliDay,
            bengaliMonth: info.name,
            label: event.label,
            category: categoryText,
            icon: event.icon,
          ),
        );

        if (hits.length >= 80) break;
      }

      if (hits.length >= 80) break;
    }

    if (!mounted) return;

    setState(() {
      _results = hits;
      _busy = false;
    });
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
