class _TraditionalDayInsight {
  final DateTime date;
  final int score;
  final String label;
  final TithiInfo tithi;
  final String nakshatra;
  final String rashi;
  final List<CalendarEvent> events;
  final Map<String, dynamic> abhijit;
  final Map<String, DateTime> rahu;

  const _TraditionalDayInsight({
    required this.date,
    required this.score,
    required this.label,
    required this.tithi,
    required this.nakshatra,
    required this.rashi,
    required this.events,
    required this.abhijit,
    required this.rahu,
  });

  static _TraditionalDayInsight forDate(DateTime date) {
    final sun = PanchangCalculator.sunTimes(
      date,
      lat: AppLocation.lat,
      lon: AppLocation.lon,
    );
    final tithi = PanchangCalculator.tithiFor(sun.sunrise);
    final nak = PanchangCalculator
        .nakshatraNames[PanchangCalculator.nakshatraIndexFor(sun.sunrise)];
    final rashi = PanchangCalculator
        .rashiNames[PanchangCalculator.rashiIndexFor(sun.sunrise)];
    final events = BengaliCalendarData.eventsFor(date);
    final abhijit = PanchangCalculator.abhijitMuhurta(
      date,
      lat: AppLocation.lat,
      lon: AppLocation.lon,
    );
    final rahu = PanchangCalculator.rahuKalam(
      date,
      lat: AppLocation.lat,
      lon: AppLocation.lon,
    );

    var score = 52;
    if (tithi.paksha == 'à¦¶à§à¦•à§à¦²') score += 10;
    if (abhijit['applicable'] == true) score += 6;
    if (date.weekday == DateTime.tuesday) score -= 8;
    if (tithi.name == 'à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾') score -= 6;
    if (tithi.name == 'à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾') score += 4;

    const auspicious = {
      'marriage',
      'griha',
      'annaprashan',
      'byabosha',
      'namakaran',
      'jomi',
      'bari',
      'gari',
    };
    if (events.any((e) => auspicious.contains(e.category))) score += 18;
    if (events.any((e) => e.category == 'general')) score += 3;
    score = score.clamp(25, 95).toInt();

    final label = score >= 80
        ? 'à¦–à§à¦¬ à¦­à¦¾à¦²à§‹ à¦¸à§‚à¦šà¦•'
        : score >= 68
        ? 'à¦­à¦¾à¦²à§‹ à¦¸à§‚à¦šà¦•'
        : score >= 55
        ? 'à¦¸à¦¾à¦§à¦¾à¦°à¦£ à¦¸à§‚à¦šà¦•'
        : 'à¦¸à¦¤à¦°à§à¦• à¦¸à§‚à¦šà¦•';

    return _TraditionalDayInsight(
      date: date,
      score: score,
      label: label,
      tithi: tithi,
      nakshatra: nak,
      rashi: rashi,
      events: events,
      abhijit: abhijit,
      rahu: rahu,
    );
  }
}

