  int _minute(DateTime d) => d.hour * 60 + d.minute;

  bool _inside(int now, DateTime start, DateTime end) {
    final a = _minute(start);
    final b = _minute(end);
    return now >= a && now < b;
  }

  String _durationText(int minutes) {
    if (minutes <= 0) return 'à¦à¦–à¦¨';
    final h = minutes ~/ 60;
    final m = minutes % 60;
    if (h == 0) return '${bnNum(m)} à¦®à¦¿à¦¨à¦¿à¦Ÿ';
    if (m == 0) return '${bnNum(h)} à¦˜à¦£à§à¦Ÿà¦¾';
