class _PanchangCompareScreenState extends State<PanchangCompareScreen> {
  DateTime _a = DateTime.now();
  DateTime _b = DateTime.now().add(const Duration(days: 7));

  Future<void> _pick(bool first) async {
    final initial = first ? _a : _b;
    final picked = await showDatePicker(
      context: context,
      initialDate: initial,
      firstDate: DateTime(DateTime.now().year - 2),
      lastDate: DateTime(DateTime.now().year + 5, 12, 31),
    );
    if (picked == null || !mounted) return;
    setState(() {
      if (first) {
        _a = picked;
      } else {
        _b = picked;
      }
    });
  }

