class PanjikaVoiceAssistantScreen extends StatefulWidget {
  const PanjikaVoiceAssistantScreen({super.key});

  @override
  State<PanjikaVoiceAssistantScreen> createState() =>
      _PanjikaVoiceAssistantScreenState();
}

class _PanjikaVoiceAssistantScreenState
    extends State<PanjikaVoiceAssistantScreen> {
  final stt.SpeechToText _speech = stt.SpeechToText();
  final TextEditingController _text = TextEditingController();
  bool _ready = false;
  bool _listening = false;
  bool _initializing = true;
  String _answer =
      'à¦®à¦¾à¦‡à¦• à¦šà¦¾à¦ªà§à¦¨ à¦¬à¦¾ à¦ªà§à¦°à¦¶à§à¦¨ à¦²à¦¿à¦–à§à¦¨à¥¤';

  @override
  void initState() {
    super.initState();
    _initSpeech();
  }

  Future<void> _initSpeech() async {
    try {
      final ok = await _speech.initialize(
        onStatus: (status) {
          if (!mounted) return;
          if (status == 'done' || status == 'notListening') {
            setState(() => _listening = false);
          }
        },
        onError: (_) {
          if (mounted) setState(() => _listening = false);
        },
      );
      if (!mounted) return;
      setState(() {
        _ready = ok;
        _initializing = false;
      });
    } catch (_) {
      if (!mounted) return;
      setState(() {
        _ready = false;
        _initializing = false;
      });
    }
  }

  Future<void> _listen() async {
    if (!_ready) return;
    if (_listening) {
      await _speech.stop();
      if (mounted) setState(() => _listening = false);
      return;
    }
    setState(() => _listening = true);

    void onResult(dynamic result) {
      if (!mounted) return;
      final words = result.recognizedWords as String;
      setState(() => _text.text = words);
      if (result.finalResult == true && words.trim().isNotEmpty) {
        _answerQuestion(words);
      }
    }

    try {
      await _speech.listen(
        onResult: onResult,
        localeId: 'bn_IN',
        listenFor: const Duration(seconds: 12),
        pauseFor: const Duration(seconds: 3),
      );
    } catch (_) {
      try {
        await _speech.listen(
          onResult: onResult,
          listenFor: const Duration(seconds: 12),
          pauseFor: const Duration(seconds: 3),
        );
      } catch (_) {
        if (mounted) setState(() => _listening = false);
      }
    }
  }

  DateTime? _nextEventDate(String category, {int maxDays = 150}) {
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    for (var i = 0; i <= maxDays; i++) {
      final d = today.add(Duration(days: i));
      if (BengaliCalendarData.eventsFor(d).any((e) => e.category == category)) {
        return d;
      }
    }
    return null;
  }

  String _dateLabel(DateTime date) {
    final info = BengaliDateUtil.monthInfoFor(date);
    final day = date.difference(info.start).inDays + 1;
    return '${bnNum(day)} ${info.name} â€¢ ${bnNum(date.day)} ${gregMonthBn(date.month)} ${bnNum(date.year)}';
  }

  void _answerQuestion(String raw) {
    final q = raw.trim().toLowerCase();
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    String answer;

    if (q.contains('à¦°à¦¾à¦¹à§')) {
      final r = PanchangCalculator.rahuKalam(
        today,
        lat: AppLocation.lat,
        lon: AppLocation.lon,
      );
      answer =
          'à¦†à¦œ à¦°à¦¾à¦¹à§à¦•à¦¾à¦² ${bnTime12(r['start']!)} à¦¥à§‡à¦•à§‡ ${bnTime12(r['end']!)}à¥¤';
    } else if (q.contains('à¦¸à§‚à¦°à§à¦¯à§‹à¦¦')) {
      final s = PanchangCalculator.sunTimes(
        today,
        lat: AppLocation.lat,
        lon: AppLocation.lon,
      );
      answer = 'à¦†à¦œ à¦¸à§‚à¦°à§à¦¯à§‹à¦¦à¦¯à¦¼ ${bnTime12(s.sunrise)}à¥¤';
    } else if (q.contains('à¦¸à§‚à¦°à§à¦¯à¦¾à¦¸à§à¦¤')) {
      final s = PanchangCalculator.sunTimes(
        today,
        lat: AppLocation.lat,
        lon: AppLocation.lon,
      );
      answer = 'à¦†à¦œ à¦¸à§‚à¦°à§à¦¯à¦¾à¦¸à§à¦¤ ${bnTime12(s.sunset)}à¥¤';
    } else if (q.contains('à¦à¦•à¦¾à¦¦à¦¶')) {
      final d = _nextEventDate('ekadashi');
      answer = d == null
          ? 'à¦†à¦—à¦¾à¦®à§€ à¦à¦•à¦¾à¦¦à¦¶à§€à¦° à¦¤à¦¾à¦°à¦¿à¦– à¦ªà¦¾à¦“à¦¯à¦¼à¦¾ à¦¯à¦¾à¦¯à¦¼à¦¨à¦¿à¥¤'
          : 'à¦†à¦—à¦¾à¦®à§€ à¦à¦•à¦¾à¦¦à¦¶à§€ ${_dateLabel(d)}à¥¤';
    } else if (q.contains('à¦ªà§‚à¦°à§à¦£à¦¿à¦®')) {
      final d = _nextEventDate('purnima');
      answer = d == null
          ? 'à¦†à¦—à¦¾à¦®à§€ à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾à¦° à¦¤à¦¾à¦°à¦¿à¦– à¦ªà¦¾à¦“à¦¯à¦¼à¦¾ à¦¯à¦¾à¦¯à¦¼à¦¨à¦¿à¥¤'
          : 'à¦†à¦—à¦¾à¦®à§€ à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾ ${_dateLabel(d)}à¥¤';
    } else if (q.contains('à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯')) {
      final d = _nextEventDate('amabasya');
      answer = d == null
          ? 'à¦†à¦—à¦¾à¦®à§€ à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾à¦° à¦¤à¦¾à¦°à¦¿à¦– à¦ªà¦¾à¦“à¦¯à¦¼à¦¾ à¦¯à¦¾à¦¯à¦¼à¦¨à¦¿à¥¤'
          : 'à¦†à¦—à¦¾à¦®à§€ à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾ ${_dateLabel(d)}à¥¤';
    } else if (q.contains('à¦‰à§Žà¦¸à¦¬') || q.contains('à¦ªà§‚à¦œà¦¾')) {
      final f = BengaliCalendarData.upcomingFestivals(count: 1);
      answer = f.isEmpty
          ? 'à¦†à¦—à¦¾à¦®à§€ à¦‰à§Žà¦¸à¦¬à§‡à¦° à¦¤à¦¥à§à¦¯ à¦ªà¦¾à¦“à¦¯à¦¼à¦¾ à¦¯à¦¾à¦¯à¦¼à¦¨à¦¿à¥¤'
          : 'à¦†à¦—à¦¾à¦®à§€ à¦¬à¦¿à¦¶à§‡à¦· à¦¦à¦¿à¦¨ ${f.first['title'] ?? ''}, ${f.first['date'] ?? ''}à¥¤';
    } else if (q.contains('à¦•à¦¾à¦²')) {
      final d = today.add(const Duration(days: 1));
      final t = PanchangCalculator.tithiFor(d);
      final info = BengaliDateUtil.monthInfoFor(d);
      final bday = d.difference(info.start).inDays + 1;
      answer =
          'à¦•à¦¾à¦² ${bnNum(bday)} ${info.name}, ${t.paksha} à¦ªà¦•à§à¦·à§‡à¦° ${t.name} à¦¤à¦¿à¦¥à¦¿à¥¤';
    } else if (q.contains('à¦†à¦œ') ||
        q.contains('à¦ªà¦žà§à¦œà¦¿à¦•à¦¾') ||
        q.contains('à¦ªà¦žà§à¦šà¦¾à¦™à§à¦—')) {
      final t = PanchangCalculator.tithiFor(now);
      final nak = PanchangCalculator
          .nakshatraNames[PanchangCalculator.nakshatraIndexFor(now)];
      final rashi =
          PanchangCalculator.rashiNames[PanchangCalculator.rashiIndexFor(now)];
      answer =
          'à¦†à¦œ ${_dateLabel(today)}à¥¤ ${t.paksha} à¦ªà¦•à§à¦·à§‡à¦° ${t.name} à¦¤à¦¿à¦¥à¦¿à¥¤ à¦¨à¦•à§à¦·à¦¤à§à¦° $nak, à¦šà¦¨à§à¦¦à§à¦° à¦°à¦¾à¦¶à¦¿ $rashià¥¤';
    } else {
      answer =
          'à¦†à¦®à¦¿ à¦à¦–à¦¨ à¦†à¦œà¦•à§‡à¦° à¦ªà¦žà§à¦œà¦¿à¦•à¦¾, à¦•à¦¾à¦²à¦•à§‡à¦° à¦¤à¦¿à¦¥à¦¿, à¦°à¦¾à¦¹à§à¦•à¦¾à¦², à¦¸à§‚à¦°à§à¦¯à§‹à¦¦à¦¯à¦¼, à¦¸à§‚à¦°à§à¦¯à¦¾à¦¸à§à¦¤, à¦à¦•à¦¾à¦¦à¦¶à§€, à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾, à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾ à¦“ à¦†à¦—à¦¾à¦®à§€ à¦‰à§Žà¦¸à¦¬à§‡à¦° à¦ªà§à¦°à¦¶à§à¦¨ à¦¬à§à¦à¦¤à§‡ à¦ªà¦¾à¦°à¦¿à¥¤';
    }

    setState(() {
      _answer = answer;
      _listening = false;
    });
    TtsService.instance.speak(answer);
  }

