class _AgendaEntry {
  final DateTime when;
  final String icon;
  final String title;
  final String type;
  const _AgendaEntry(this.when, this.icon, this.title, this.type);
}

class SmartAgendaScreen extends StatefulWidget {
  const SmartAgendaScreen({super.key});

  @override
  State<SmartAgendaScreen> createState() => _SmartAgendaScreenState();
}

class _SmartAgendaScreenState extends State<SmartAgendaScreen> {
  bool _loading = true;
  List<_AgendaEntry> _items = const [];

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    await FamilyMemberStore.instance.load();
    await ReminderStore.instance.load();
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final end = today.add(const Duration(days: 30));
    final all = <_AgendaEntry>[];

    for (var i = 0; i <= 30; i++) {
      final d = today.add(Duration(days: i));
      for (final e in BengaliCalendarData.eventsFor(d)) {
        all.add(_AgendaEntry(d, e.icon, e.label, 'à¦ªà¦žà§à¦œà¦¿à¦•à¦¾'));
      }
    }

    for (final f in FamilyMemberStore.instance.items) {
      final d = f.nextOccurrence;
      if (!d.isAfter(end)) {
        all.add(
          _AgendaEntry(
            d,
            f.occasion == 'à¦¬à¦¿à¦¬à¦¾à¦¹à¦¬à¦¾à¦°à§à¦·à¦¿à¦•à§€'
                ? 'ðŸ’ž'
                : 'ðŸŽ‚',
            '${f.name} â€¢ ${f.occasion}',
            'à¦ªà¦°à¦¿à¦¬à¦¾à¦°',
          ),
        );
      }
    }

    for (final r in ReminderStore.instance.items) {
      if (r.when.isAfter(now) && !r.when.isAfter(end)) {
        all.add(
          _AgendaEntry(r.when, 'â°', r.text, 'à¦°à¦¿à¦®à¦¾à¦‡à¦¨à§à¦¡à¦¾à¦°'),
        );
      }
    }

    all.sort((a, b) => a.when.compareTo(b.when));
    if (!mounted) return;
    setState(() {
      _items = all;
      _loading = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    return CosmicBackground(
      child: Column(
        children: [
          const _ScreenHeader(title: 'ðŸ—“ï¸ Smart 30-Day Agenda'),
          Expanded(
            child: _loading
                ? const Center(
                    child: CircularProgressIndicator(color: Color(0xFFFFD36E)),
                  )
                : _items.isEmpty
                ? const Center(
                    child: Text(
                      'à¦†à¦—à¦¾à¦®à§€ à§©à§¦ à¦¦à¦¿à¦¨à§‡ à¦•à§‹à¦¨à§‹ saved item à¦¨à§‡à¦‡',
                      style: TextStyle(color: Colors.white70),
                    ),
                  )
                : ListView.builder(
                    padding: const EdgeInsets.all(16),
                    itemCount: _items.length,
                    itemBuilder: (context, i) {
                      final a = _items[i];
                      final now = DateTime.now();
                      final today = DateTime(now.year, now.month, now.day);
                      final day = DateTime(
                        a.when.year,
                        a.when.month,
                        a.when.day,
                      );
                      final days = day.difference(today).inDays;
                      return Container(
                        margin: const EdgeInsets.only(bottom: 9),
                        padding: const EdgeInsets.all(13),
                        decoration: BoxDecoration(
                          color: Colors.white.withValues(alpha: 0.065),
                          borderRadius: BorderRadius.circular(16),
                          border: Border.all(
                            color: Colors.white.withValues(alpha: 0.11),
                          ),
                        ),
                        child: Row(
                          children: [
                            Text(a.icon, style: const TextStyle(fontSize: 24)),
                            const SizedBox(width: 11),
                            Expanded(
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text(
                                    a.title,
                                    style: const TextStyle(
                                      color: Colors.white,
                                      fontSize: 13.5,
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                  const SizedBox(height: 3),
                                  Text(
                                    '${a.type} â€¢ ${bnNum(a.when.day)} ${gregMonthBn(a.when.month)}',
                                    style: const TextStyle(
                                      color: Colors.white60,
                                      fontSize: 11.5,
                                    ),
                                  ),
                                ],
                              ),
                            ),
                            Text(
                              days == 0
                                  ? 'à¦†à¦œ'
                                  : days == 1
                                  ? 'à¦•à¦¾à¦²'
                                  : '${bnNum(days)} à¦¦à¦¿à¦¨',
                              style: const TextStyle(
                                color: Color(0xFFFFD36E),
                                fontSize: 11,
                                fontWeight: FontWeight.w800,
                              ),
                            ),
