}

class _SmartNotificationDigestScreenState
    extends State<SmartNotificationDigestScreen> {
  static const _morningKey = 'phase4_digest_morning';
  static const _eveningKey = 'phase4_digest_evening';
  static const _morningBase = 960000;
  static const _eveningBase = 961000;

  bool _morning = false;
  bool _evening = false;
  bool _busy = true;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final p = await SharedPreferences.getInstance();
    if (!mounted) return;
    setState(() {
      _morning = p.getBool(_morningKey) ?? false;
      _evening = p.getBool(_eveningKey) ?? false;
      _busy = false;
    });
  }

  String _summaryFor(DateTime day, {required bool morning}) {
    final info = BengaliDateUtil.monthInfoFor(day);
    final bday = day.difference(info.start).inDays + 1;
    final tithi = PanchangCalculator.tithiFor(day);
    final events = BengaliCalendarData.eventsFor(day);
    final rahu = PanchangCalculator.rahuKalam(
      day,
      lat: AppLocation.lat,
      lon: AppLocation.lon,
    );
    final eventText = events.isEmpty
        ? 'à¦¬à¦¿à¦¶à§‡à¦· à¦‰à§Žà¦¸à¦¬ à¦¨à§‡à¦‡'
        : events.take(2).map((e) => '${e.icon} ${e.label}').join(' â€¢ ');
    if (morning) {
      return '${bnNum(bday)} ${info.name} â€¢ ${tithi.name} â€¢ $eventText â€¢ à¦°à¦¾à¦¹à§à¦•à¦¾à¦² ${bnTime12(rahu['start']!)}â€“${bnTime12(rahu['end']!)}';
    }
    final tomorrow = day.add(const Duration(days: 1));
    final tomorrowInfo = BengaliDateUtil.monthInfoFor(tomorrow);
    final tomorrowDay = tomorrow.difference(tomorrowInfo.start).inDays + 1;
    final tomorrowTithi = PanchangCalculator.tithiFor(tomorrow);
    final tomorrowEvents = BengaliCalendarData.eventsFor(tomorrow);
    final tomorrowEventText = tomorrowEvents.isEmpty
        ? 'à¦¬à¦¿à¦¶à§‡à¦· à¦‰à§Žà¦¸à¦¬ à¦¨à§‡à¦‡'
        : tomorrowEvents
              .take(2)
              .map((e) => '${e.icon} ${e.label}')
              .join(' â€¢ ');
    return 'à¦†à¦—à¦¾à¦®à§€à¦•à¦¾à¦² ${bnNum(tomorrowDay)} ${tomorrowInfo.name} â€¢ ${tomorrowTithi.name} â€¢ $tomorrowEventText';
  }

  Future<void> _cancelScheduled() async {
    for (int i = 0; i < 14; i++) {
      await NotificationService.instance.cancel(_morningBase + i);
      await NotificationService.instance.cancel(_eveningBase + i);
    }
  }

  Future<void> _saveAndSchedule() async {
    setState(() => _busy = true);
    final p = await SharedPreferences.getInstance();
    await p.setBool(_morningKey, _morning);
    await p.setBool(_eveningKey, _evening);
    await _cancelScheduled();

    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    for (int i = 0; i < 14; i++) {
      final day = today.add(Duration(days: i));
      if (_morning) {
        final when = DateTime(day.year, day.month, day.day, 7, 0);
        if (when.isAfter(now)) {
          await NotificationService.instance.scheduleGeneric(
            _morningBase + i,
            'ðŸŒ… à¦†à¦œà¦•à§‡à¦° à¦ªà¦žà§à¦œà¦¿à¦•à¦¾ à¦¬à§à¦°à¦¿à¦«',
            _summaryFor(day, morning: true),
            when,
          );
        }
      }
      if (_evening) {
        final when = DateTime(day.year, day.month, day.day, 19, 0);
        if (when.isAfter(now)) {
          await NotificationService.instance.scheduleGeneric(
            _eveningBase + i,
            'ðŸŒ™ à¦†à¦—à¦¾à¦®à§€ à¦¦à¦¿à¦¨à§‡à¦° à¦ªà¦žà§à¦œà¦¿à¦•à¦¾',
            _summaryFor(day, morning: false),
            when,
          );
        }
      }
    }

    if (!mounted) return;
    setState(() => _busy = false);
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          (!_morning && !_evening)
              ? 'Smart Digest à¦¬à¦¨à§à¦§ à¦•à¦°à¦¾ à¦¹à¦¯à¦¼à§‡à¦›à§‡'
              : 'à¦ªà¦°à¦¬à¦°à§à¦¤à§€ à§§à§ª à¦¦à¦¿à¦¨à§‡à¦° Smart Digest schedule à¦¹à¦¯à¦¼à§‡à¦›à§‡',
        ),
      ),
    );
  }

  Widget _glass(Widget child) => Container(
