class ShubhoAlarmScreen extends StatefulWidget {
  const ShubhoAlarmScreen({super.key});

  @override
  State<ShubhoAlarmScreen> createState() => _ShubhoAlarmScreenState();
}

class _ShubhoAlarmScreenState extends State<ShubhoAlarmScreen> {
  DateTime _date = DateTime.now();
  String _type = 'à¦…à¦­à¦¿à¦œà¦¿à§Ž à¦®à§à¦¹à§‚à¦°à§à¦¤';
  bool _busy = false;

  Future<void> _pickDate() async {
    final d = await showDatePicker(
      context: context,
      initialDate: _date,
      firstDate: DateTime.now(),
      lastDate: DateTime(DateTime.now().year + 2, 12, 31),
    );
    if (d != null) setState(() => _date = d);
  }

  DateTime? _timeForType(String type) {
    if (type == 'à¦¸à§‚à¦°à§à¦¯à§‹à¦¦à¦¯à¦¼') {
      return PanchangCalculator.sunTimes(
        _date,
        lat: AppLocation.lat,
        lon: AppLocation.lon,
      ).sunrise;
    }
    if (type == 'à¦°à¦¾à¦¹à§à¦•à¦¾à¦² à¦¶à§‡à¦·') {
      return PanchangCalculator.rahuKalam(
        _date,
        lat: AppLocation.lat,
        lon: AppLocation.lon,
      )['end'];
    }
    final a = PanchangCalculator.abhijitMuhurta(
      _date,
      lat: AppLocation.lat,
      lon: AppLocation.lon,
    );
    if (a['applicable'] != true) return null;
    return a['start'] as DateTime?;
  }

  Future<void> _schedule() async {
    final target = _timeForType(_type);
    if (target == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
