class SadhanaStreakScreen extends StatefulWidget {
  const SadhanaStreakScreen({super.key});

  @override
  State<SadhanaStreakScreen> createState() => _SadhanaStreakScreenState();
}

class _SadhanaStreakScreenState extends State<SadhanaStreakScreen> {
  static const _key = 'phase4_sadhana_log';
  Set<String> _done = <String>{};
  bool _loading = true;

  static const _actions = <String, String>{
    'panjika': 'ðŸ“– à¦†à¦œà¦•à§‡à¦° à¦ªà¦žà§à¦œà¦¿à¦•à¦¾ à¦¦à§‡à¦–à§‡à¦›à¦¿',
    'japa': 'ðŸ“¿ à¦œà¦ª/à¦§à§à¦¯à¦¾à¦¨ à¦•à¦°à§‡à¦›à¦¿',
    'puja': 'ðŸª” à¦ªà§‚à¦œà¦¾/à¦ªà§à¦°à¦¾à¦°à§à¦¥à¦¨à¦¾ à¦•à¦°à§‡à¦›à¦¿',
  };

  String _dayKey(DateTime d) =>
      '${d.year.toString().padLeft(4, '0')}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';

  String _entry(DateTime d, String action) => '${_dayKey(d)}|$action';

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final p = await SharedPreferences.getInstance();
    if (!mounted) return;
    setState(() {
      _done = (p.getStringList(_key) ?? const []).toSet();
      _loading = false;
    });
  }

  Future<void> _toggle(String action, bool value) async {
    final today = DateTime.now();
    final e = _entry(today, action);
    setState(() {
      if (value) {
        _done.add(e);
      } else {
        _done.remove(e);
      }
    });
    final p = await SharedPreferences.getInstance();
    await p.setStringList(_key, _done.toList());
  }

  bool _hasAny(DateTime d) =>
      _actions.keys.any((a) => _done.contains(_entry(d, a)));

  int get _streak {
    var count = 0;
    var d = DateTime.now();
    while (_hasAny(d)) {
      count++;
      d = d.subtract(const Duration(days: 1));
      if (count > 3650) break;
    }
    return count;
  }

  int get _todayCount => _actions.keys
      .where((a) => _done.contains(_entry(DateTime.now(), a)))
      .length;

  Widget _glass(Widget child) => Container(
    width: double.infinity,
    padding: const EdgeInsets.all(15),
    decoration: BoxDecoration(
      color: const Color(0xFF07172F).withValues(alpha: 0.64),
      borderRadius: BorderRadius.circular(18),
      border: Border.all(
        color: const Color(0xFF7EE2B8).withValues(alpha: 0.20),
      ),
    ),
    child: child,
  );

  @override
  Widget build(BuildContext context) {
    final today = DateTime.now();
    return CosmicBackground(
      child: Column(
        children: [
          const _ScreenHeader(title: 'ðŸ”¥ Sadhana Streak'),
          Expanded(
            child: _loading
                ? const Center(
                    child: CircularProgressIndicator(color: Color(0xFFFFD36E)),
                  )
                : ListView(
                    padding: const EdgeInsets.all(16),
                    children: [
                      _glass(
                        Row(
                          children: [
                            Container(
                              width: 66,
                              height: 66,
                              alignment: Alignment.center,
                              decoration: BoxDecoration(
                                shape: BoxShape.circle,
                                color: const Color(
                                  0xFFFFD36E,
                                ).withValues(alpha: 0.14),
                                border: Border.all(
                                  color: const Color(
                                    0xFFFFD36E,
                                  ).withValues(alpha: 0.45),
                                ),
                              ),
                              child: Text(
                                '${bnNum(_streak)}ðŸ”¥',
                                style: const TextStyle(
                                  color: Colors.white,
                                  fontSize: 20,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                            ),
                            const SizedBox(width: 14),
                            Expanded(
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  const Text(
                                    'à¦†à¦ªà¦¨à¦¾à¦° à¦¬à¦°à§à¦¤à¦®à¦¾à¦¨ à¦§à¦¾à¦°à¦¾à¦¬à¦¾à¦¹à¦¿à¦•à¦¤à¦¾',
                                    style: TextStyle(
                                      color: Colors.white70,
                                      fontSize: 12,
                                    ),
                                  ),
                                  const SizedBox(height: 4),
                                  Text(
                                    '${bnNum(_streak)} à¦¦à¦¿à¦¨à§‡à¦° Streak',
                                    style: const TextStyle(
                                      color: Color(0xFFFFD36E),
                                      fontSize: 20,
                                      fontWeight: FontWeight.w900,
                                    ),
                                  ),
                                  Text(
                                    'à¦†à¦œ $_todayCount/${_actions.length} à¦•à¦¾à¦œ à¦¸à¦®à§à¦ªà§‚à¦°à§à¦£',
                                    style: const TextStyle(
                                      color: Colors.white60,
                                      fontSize: 11.5,
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          ],
                        ),
                      ),
                      const SizedBox(height: 12),
                      _glass(
                        Column(
                          children: _actions.entries
                              .map(
                                (e) => CheckboxListTile(
                                  value: _done.contains(_entry(today, e.key)),
                                  onChanged: (v) => _toggle(e.key, v ?? false),
                                  title: Text(
                                    e.value,
                                    style: const TextStyle(
                                      color: Colors.white,
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                  controlAffinity:
                                      ListTileControlAffinity.leading,
                                ),
                              )
                              .toList(),
                        ),
                      ),
                      const SizedBox(height: 12),
                      _glass(
                        Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            const Text(
                              'à¦—à¦¤ à§­ à¦¦à¦¿à¦¨',
                              style: TextStyle(
                                color: Color(0xFFFFD36E),
                                fontWeight: FontWeight.w800,
                              ),
                            ),
                            const SizedBox(height: 12),
                            Row(
                              mainAxisAlignment: MainAxisAlignment.spaceBetween,
                              children: List.generate(7, (i) {
                                final d = today.subtract(Duration(days: 6 - i));
                                final active = _hasAny(d);
                                return Column(
                                  children: [
                                    Container(
                                      width: 34,
                                      height: 34,
                                      alignment: Alignment.center,
                                      decoration: BoxDecoration(
                                        shape: BoxShape.circle,
                                        color: active
                                            ? const Color(
                                                0xFF7EE2B8,
                                              ).withValues(alpha: 0.22)
                                            : Colors.white.withValues(
                                                alpha: 0.05,
                                              ),
                                        border: Border.all(
                                          color: active
                                              ? const Color(0xFF7EE2B8)
                                              : Colors.white.withValues(
                                                  alpha: 0.12,
                                                ),
                                        ),
                                      ),
                                      child: Text(
                                        active ? 'âœ“' : 'â€¢',
                                        style: TextStyle(
                                          color: active
                                              ? const Color(0xFF7EE2B8)
                                              : Colors.white38,
                                          fontWeight: FontWeight.w900,
                                        ),
                                      ),
                                    ),
                                    const SizedBox(height: 4),
                                    Text(
                                      bnNum(d.day),
                                      style: const TextStyle(
                                        color: Colors.white60,
                                        fontSize: 10,
                                      ),
                                    ),
                                  ],
                                );
                              }),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
          ),
        ],
      ),
    );
  }
}

