  Future<void> _load() async {
    await FamilyMemberStore.instance.load();
    final items = [...FamilyMemberStore.instance.items]
      ..sort((a, b) => a.daysLeft.compareTo(b.daysLeft));
    if (!mounted) return;
    setState(() {
      _items = items;
      _selected = items.isEmpty ? null : items.first;
    });
    await _loadDone();
