class SmartReminderCenterScreen extends StatefulWidget {
  const SmartReminderCenterScreen({super.key});

  @override
  State<SmartReminderCenterScreen> createState() =>
      _SmartReminderCenterScreenState();
}

class _SmartReminderCenterScreenState extends State<SmartReminderCenterScreen> {
  bool _loading = true;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    await ReminderStore.instance.load();
    await FamilyMemberStore.instance.load();
    if (!mounted) return;
    setState(() => _loading = false);
  }

  Widget _launch(BuildContext context, String icon, String title, Widget page) {
    return Expanded(
      child: InkWell(
        borderRadius: BorderRadius.circular(15),
        onTap: () =>
            Navigator.push(context, MaterialPageRoute(builder: (_) => page)),
        child: Container(
          height: 78,
          padding: const EdgeInsets.all(8),
          decoration: BoxDecoration(
            color: Colors.white.withValues(alpha: 0.07),
            borderRadius: BorderRadius.circular(15),
            border: Border.all(color: Colors.white.withValues(alpha: 0.11)),
          ),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Text(icon, style: const TextStyle(fontSize: 21)),
              const SizedBox(height: 5),
              Text(
                title,
                textAlign: TextAlign.center,
                maxLines: 2,
                style: const TextStyle(
                  color: Colors.white,
                  fontSize: 9.8,
                  fontWeight: FontWeight.w700,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final now = DateTime.now();
    final upcomingReminders =
        ReminderStore.instance.items.where((e) => e.when.isAfter(now)).toList()
          ..sort((a, b) => a.when.compareTo(b.when));
    final family = FamilyMemberStore.instance.items.toList()
      ..sort((a, b) => a.daysLeft.compareTo(b.daysLeft));

    return CosmicBackground(
      child: Column(
        children: [
          const _ScreenHeader(title: 'ðŸ”” Smart Reminder Center'),
          Expanded(
            child: _loading
                ? const Center(child: CircularProgressIndicator())
                : ListView(
                    padding: const EdgeInsets.fromLTRB(15, 8, 15, 28),
                    children: [
                      Row(
                        children: [
                          _launch(
                            context,
                            'â°',
                            'My Reminders',
                            const ReminderScreen(),
                          ),
                          const SizedBox(width: 8),
                          _launch(
                            context,
                            'ðŸ“¨',
                            'Daily Digest',
                            const SmartNotificationDigestScreen(),
                          ),
                          const SizedBox(width: 8),
                          _launch(
                            context,
                            'â­',
                            'Shubho Alarm',
                            const ShubhoAlarmScreen(),
                          ),
                        ],
                      ),
                      const SizedBox(height: 16),
                      Container(
                        padding: const EdgeInsets.all(14),
                        decoration: BoxDecoration(
                          color: const Color(
                            0xFF07172F,
                          ).withValues(alpha: 0.62),
                          borderRadius: BorderRadius.circular(18),
                          border: Border.all(
                            color: const Color(
                              0xFFFFD36E,
                            ).withValues(alpha: 0.20),
                          ),
                        ),
                        child: Row(
                          children: [
                            Expanded(
                              child: _centerStat(
                                'â°',
                                '${upcomingReminders.length}',
                                'à¦†à¦—à¦¾à¦®à§€ Reminder',
                              ),
                            ),
                            Container(
                              width: 1,
                              height: 42,
                              color: Colors.white.withValues(alpha: 0.08),
                            ),
                            Expanded(
                              child: _centerStat(
                                'ðŸ‘¨â€ðŸ‘©â€ðŸ‘§',
                                '${family.length}',
                                'Family Occasion',
                              ),
                            ),
                          ],
                        ),
                      ),
                      const SizedBox(height: 18),
                      const Text(
                        'à¦¸à¦¬à¦šà§‡à§Ÿà§‡ à¦•à¦¾à¦›à§‡à¦° Reminder',
                        style: TextStyle(
                          color: Color(0xFFFFD36E),
                          fontSize: 15,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      const SizedBox(height: 8),
                      if (upcomingReminders.isEmpty)
                        _empty('à¦•à§‹à¦¨à§‹ future reminder à¦¨à§‡à¦‡')
                      else
                        for (final r in upcomingReminders.take(4))
                          _line(
                            'â°',
                            r.text,
                            '${bnNum(r.when.day)} ${gregMonthBn(r.when.month)} â€¢ ${bnTime12(r.when)}',
                          ),
                      const SizedBox(height: 18),
                      const Text(
                        'Family Upcoming',
                        style: TextStyle(
                          color: Color(0xFFFFD36E),
                          fontSize: 15,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      const SizedBox(height: 8),
                      if (family.isEmpty)
                        _empty(
                          'Family Calendar-à¦ à¦à¦–à¦¨à§‹ à¦•à¦¿à¦›à§ à¦¯à§‹à¦— à¦•à¦°à¦¾ à¦¹à§Ÿà¦¨à¦¿',
                        )
                      else
                        for (final f in family.take(4))
                          _line(
                            'ðŸŽ',
                            '${f.name} â€¢ ${f.occasion}',
                            f.daysLeft == 0
                                ? 'à¦†à¦œ'
                                : '${bnNum(f.daysLeft)} à¦¦à¦¿à¦¨ à¦ªà¦°à§‡',
                          ),
                    ],
                  ),
          ),
        ],
      ),
    );
  }

  Widget _centerStat(String icon, String value, String label) {
    return Column(
      children: [
        Text(icon, style: const TextStyle(fontSize: 20)),
        const SizedBox(height: 3),
        Text(
          value,
