  String get _key {
    final d = DateTime.now();
    return 'phase5_routine_${d.year}_${d.month}_${d.day}';
  }

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final p = await SharedPreferences.getInstance();
    final raw = p.getStringList(_key) ?? const [];
    _done
      ..clear()
      ..addAll(raw.map(int.parse));
    if (!mounted) return;
    setState(() => _loading = false);
  }

  Future<void> _toggle(int index) async {
    setState(() {
      if (_done.contains(index)) {
        _done.remove(index);
      } else {
        _done.add(index);
      }
    });
    final p = await SharedPreferences.getInstance();
    await p.setStringList(_key, _done.map((e) => '$e').toList());
  }

