class MyYearMapScreen extends StatefulWidget {
  const MyYearMapScreen({super.key});

  @override
  State<MyYearMapScreen> createState() => _MyYearMapScreenState();
}

class _MyYearMapScreenState extends State<MyYearMapScreen> {
  bool _loading = true;
  late List<Map<String, int>> _months;

  @override
  void initState() {
    super.initState();
    _buildMap();
  }

  Future<void> _buildMap() async {
    await ReminderStore.instance.load();
    await FamilyMemberStore.instance.load();

    final year = DateTime.now().year;
    final result = <Map<String, int>>[];

    for (int month = 1; month <= 12; month++) {
      final days = DateUtils.getDaysInMonth(year, month);
      var calendarEvents = 0;

      for (int day = 1; day <= days; day++) {
        calendarEvents += BengaliCalendarData.eventsFor(
          DateTime(year, month, day),
        ).length;
      }

      final familyCount = FamilyMemberStore.instance.items
          .where((e) => e.date.month == month)
          .length;

      final reminderCount = ReminderStore.instance.items
          .where((e) => e.when.year == year && e.when.month == month)
          .length;

      result.add({
        'month': month,
        'events': calendarEvents,
        'family': familyCount,
        'reminders': reminderCount,
      });
    }

    if (!mounted) return;
    setState(() {
      _months = result;
      _loading = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    return CosmicBackground(
      child: Column(
        children: [
          const _ScreenHeader(title: 'ðŸ—ºï¸ My Year Map'),
          Expanded(
            child: _loading
                ? const Center(child: CircularProgressIndicator())
                : ListView(
                    padding: const EdgeInsets.fromLTRB(15, 8, 15, 28),
                    children: [
                      const Text(
                        'à¦à¦• à¦¬à¦›à¦°à§‡ à¦ªà¦žà§à¦œà¦¿à¦•à¦¾ à¦‡à¦­à§‡à¦¨à§à¦Ÿ, Family occasion à¦“ à¦†à¦ªà¦¨à¦¾à¦° Reminder â€” à¦à¦• à¦¨à¦œà¦°à§‡à¥¤',
                        style: TextStyle(
                          color: Colors.white70,
                          fontSize: 11.5,
                          height: 1.45,
                        ),
                      ),
                      const SizedBox(height: 14),
                      for (final m in _months) _monthCard(m),
                    ],
                  ),
          ),
        ],
      ),
    );
  }

  Widget _monthCard(Map<String, int> m) {
    final total =
        (m['events'] ?? 0) + (m['family'] ?? 0) + (m['reminders'] ?? 0);
    final strength = (total / 20).clamp(0.08, 1.0);

    return Container(
      margin: const EdgeInsets.only(bottom: 9),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: const Color(0xFF07172F).withValues(alpha: 0.62),
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: Colors.white.withValues(alpha: 0.09)),
      ),
      child: Column(
        children: [
          Row(
            children: [
              SizedBox(
                width: 82,
                child: Text(
                  gregMonthBn(m['month']!),
                  style: const TextStyle(
                    color: Colors.white,
                    fontSize: 12.5,
                    fontWeight: FontWeight.w800,
                  ),
                ),
              ),
              Expanded(
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(999),
                  child: LinearProgressIndicator(
                    value: strength.toDouble(),
                    minHeight: 7,
                    backgroundColor: Colors.white.withValues(alpha: 0.06),
                    valueColor: const AlwaysStoppedAnimation(Color(0xFFFFD36E)),
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 8),
          Row(
            children: [
              Expanded(
                child: Text(
                  'ðŸ“… ${bnNum(m['events']!)} à¦ªà¦žà§à¦œà¦¿à¦•à¦¾',
                  style: const TextStyle(color: Colors.white60, fontSize: 10),
                ),
              ),
              Expanded(
                child: Text(
                  'ðŸ‘¨â€ðŸ‘©â€ðŸ‘§ ${bnNum(m['family']!)} à¦ªà¦°à¦¿à¦¬à¦¾à¦°',
                  style: const TextStyle(color: Colors.white60, fontSize: 10),
                ),
              ),
              Expanded(
                child: Text(
                  'ðŸ”” ${bnNum(m['reminders']!)} Reminder',
                  textAlign: TextAlign.right,
                  style: const TextStyle(color: Colors.white60, fontSize: 10),
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }
