class Next24HoursPanchangScreen extends StatelessWidget {
  const Next24HoursPanchangScreen({super.key});

  List<Map<String, dynamic>> _timeline() {
    final now = DateTime.now();
    final until = now.add(const Duration(hours: 24));
    final rows = <Map<String, dynamic>>[];

    void add(DateTime time, String icon, String title) {
      if (!time.isBefore(now) && !time.isAfter(until)) {
        rows.add({'time': time, 'icon': icon, 'title': title});
      }
    }

    for (int offset = 0; offset <= 1; offset++) {
      final day = DateTime(
        now.year,
        now.month,
        now.day,
      ).add(Duration(days: offset));
      final sun = PanchangCalculator.sunTimes(
        day,
        lat: AppLocation.lat,
        lon: AppLocation.lon,
      );
      final rahu = PanchangCalculator.rahuKalam(day);
      final abhijit = PanchangCalculator.abhijitMuhurta(day);
      add(sun.sunrise, 'ðŸŒ…', 'à¦¸à§‚à¦°à§à¦¯à§‹à¦¦à§Ÿ');
      add(rahu['start']!, 'â³', 'à¦°à¦¾à¦¹à§à¦•à¦¾à¦² à¦¶à§à¦°à§');
      add(rahu['end']!, 'âœ…', 'à¦°à¦¾à¦¹à§à¦•à¦¾à¦² à¦¶à§‡à¦·');
      if (abhijit['applicable'] == true) {
        add(
          abhijit['start'] as DateTime,
          'â˜€ï¸',
          'à¦…à¦­à¦¿à¦œà¦¿à§Ž à¦®à§à¦¹à§‚à¦°à§à¦¤ à¦¶à§à¦°à§',
        );
        add(
          abhijit['end'] as DateTime,
          'âœ¨',
          'à¦…à¦­à¦¿à¦œà¦¿à§Ž à¦®à§à¦¹à§‚à¦°à§à¦¤ à¦¶à§‡à¦·',
        );
      }
      add(sun.sunset, 'ðŸŒ‡', 'à¦¸à§‚à¦°à§à¦¯à¦¾à¦¸à§à¦¤');
    }

    rows.sort(
      (a, b) => (a['time'] as DateTime).compareTo(b['time'] as DateTime),
    );
    return rows;
  }

  @override
  Widget build(BuildContext context) {
    final now = DateTime.now();
    final rows = _timeline();
    final todayEvents = BengaliCalendarData.eventsFor(now);
    final tomorrowEvents = BengaliCalendarData.eventsFor(
      now.add(const Duration(days: 1)),
    );

    return CosmicBackground(
      child: Column(
        children: [
          const _ScreenHeader(
            title: 'â±ï¸ à¦†à¦—à¦¾à¦®à§€ à§¨à§ª à¦˜à¦£à§à¦Ÿà¦¾',
          ),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.fromLTRB(15, 8, 15, 28),
              children: [
                Container(
                  padding: const EdgeInsets.all(15),
                  decoration: BoxDecoration(
                    gradient: const LinearGradient(
                      colors: [Color(0xFF173A4A), Color(0xFF171D3B)],
                    ),
                    borderRadius: BorderRadius.circular(20),
                    border: Border.all(
                      color: const Color(0xFF77D7F5).withValues(alpha: 0.3),
                    ),
                  ),
                  child: const Text(
                    'à¦¸à§‚à¦°à§à¦¯à§‹à¦¦à§Ÿ, à¦°à¦¾à¦¹à§à¦•à¦¾à¦², à¦…à¦­à¦¿à¦œà¦¿à§Ž à¦®à§à¦¹à§‚à¦°à§à¦¤ à¦“ à¦¸à§‚à¦°à§à¦¯à¦¾à¦¸à§à¦¤â€”à¦†à¦—à¦¾à¦®à§€ à§¨à§ª à¦˜à¦£à§à¦Ÿà¦¾à¦° à¦¸à¦®à§Ÿà¦•à§à¦°à¦®à§‡à¥¤',
