class _LifePlanItem {
  final String id;
  final String title;
  final String category;
  final DateTime when;
  final bool done;

  const _LifePlanItem({
    required this.id,
    required this.title,
    required this.category,
    required this.when,
    required this.done,
  });

  _LifePlanItem copyWith({bool? done}) => _LifePlanItem(
    id: id,
    title: title,
    category: category,
    when: when,
    done: done ?? this.done,
  );

  Map<String, dynamic> toJson() => {
    'id': id,
    'title': title,
    'category': category,
    'when': when.millisecondsSinceEpoch,
    'done': done,
  };

  static _LifePlanItem fromJson(Map<String, dynamic> m) => _LifePlanItem(
    id: m['id'].toString(),
    title: m['title'].toString(),
    category: m['category']?.toString() ?? 'à¦…à¦¨à§à¦¯à¦¾à¦¨à§à¦¯',
    when: DateTime.fromMillisecondsSinceEpoch(m['when'] as int),
    done: m['done'] == true,
  );
}

class _LifePlannerStore {
  _LifePlannerStore._();
  static final _LifePlannerStore instance = _LifePlannerStore._();
  static const _key = 'phase6_bengali_life_planner';

  final List<_LifePlanItem> items = [];

  Future<void> load() async {
    final p = await SharedPreferences.getInstance();
    final raw = p.getStringList(_key) ?? const [];
    items
      ..clear()
      ..addAll(
        raw.map(
          (e) => _LifePlanItem.fromJson(jsonDecode(e) as Map<String, dynamic>),
        ),
      );
    _sort();
  }

  void _sort() {
    items.sort((a, b) {
      if (a.done != b.done) return a.done ? 1 : -1;
      return a.when.compareTo(b.when);
    });
  }

  Future<void> _save() async {
    final p = await SharedPreferences.getInstance();
    await p.setStringList(
      _key,
      items.map((e) => jsonEncode(e.toJson())).toList(),
    );
  }

  Future<void> add(_LifePlanItem item) async {
    items.add(item);
    _sort();
    await _save();
  }

  Future<void> toggle(String id) async {
    final i = items.indexWhere((e) => e.id == id);
    if (i < 0) return;
    items[i] = items[i].copyWith(done: !items[i].done);
    _sort();
    await _save();
  }

  Future<void> remove(String id) async {
    items.removeWhere((e) => e.id == id);
    await _save();
  }
}

