class _Phase6DailyIntelligenceCardState
    extends State<_Phase6DailyIntelligenceCard> {
  int _openPlans = 0;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    await _LifePlannerStore.instance.load();
    if (!mounted) return;
    final today = DateUtils.dateOnly(DateTime.now());
    setState(() {
      _openPlans = _LifePlannerStore.instance.items.where((e) {
        return !e.done && DateUtils.isSameDay(e.when, today);
      }).length;
    });
  }

  @override
  Widget build(BuildContext context) {
    final now = DateTime.now();
    final events = BengaliCalendarData.eventsFor(now);
    final festival = BengaliCalendarData.upcomingFestivals(count: 1);
    final next = festival.isEmpty ? null : festival.first;

    return Container(
      padding: const EdgeInsets.all(13),
      decoration: BoxDecoration(
        gradient: LinearGradient(
          colors: [
            const Color(0xFF10243C).withValues(alpha: 0.82),
            const Color(0xFF203C39).withValues(alpha: 0.62),
          ],
        ),
        borderRadius: BorderRadius.circular(20),
        border: Border.all(
          color: const Color(0xFF7EE2B8).withValues(alpha: 0.22),
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Row(
            children: [
              Text('ðŸ§ ', style: TextStyle(fontSize: 20)),
              SizedBox(width: 7),
              Text(
                'Daily Intelligence',
                style: TextStyle(
                  color: Color(0xFF7EE2B8),
                  fontSize: 14.5,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ],
          ),
          const SizedBox(height: 8),
          Text(
            'à¦†à¦œ ${bnNum(events.length)}à¦Ÿà¦¿ à¦ªà¦žà§à¦œà¦¿à¦•à¦¾ event â€¢ ${bnNum(_openPlans)}à¦Ÿà¦¿ personal plan',
            style: const TextStyle(
              color: Colors.white,
              fontSize: 11.5,
              fontWeight: FontWeight.w700,
            ),
          ),
          if (next != null) ...[
            const SizedBox(height: 4),
            Text(
              'à¦ªà¦°à¦¬à¦°à§à¦¤à§€: ${next['icon'] ?? 'ðŸŽ‰'} ${next['title'] ?? ''} â€¢ ${bnNum(int.tryParse(next['daysLeft'] ?? '') ?? 0)} à¦¦à¦¿à¦¨ à¦¬à¦¾à¦•à¦¿',
