  Future<void> _vaultAction() async {
    final p = await SharedPreferences.getInstance();
    final saved = p.getString('super30_family_vault_pin');
    final ctrl = TextEditingController();
    if (!mounted) return;
    final entered = await showDialog<String>(
      context: context,
      builder: (context) => AlertDialog(
        title: Text(
          saved == null ? 'à¦¨à¦¤à§à¦¨ Family Vault PIN' : 'Family Vault PIN',
        ),
        content: TextField(
          controller: ctrl,
          keyboardType: TextInputType.number,
          obscureText: true,
          maxLength: 6,
          decoration: const InputDecoration(
            hintText: 'à§ªâ€“à§¬ à¦¸à¦‚à¦–à§à¦¯à¦¾à¦° PIN',
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('à¦¬à¦¾à¦¤à¦¿à¦²'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(context, ctrl.text.trim()),
            child: const Text('à¦ à¦¿à¦• à¦†à¦›à§‡'),
          ),
        ],
      ),
    );
    ctrl.dispose();
    if (entered == null || entered.length < 4) return;
    if (saved == null) {
      await p.setString('super30_family_vault_pin', entered);
      if (mounted) setState(() => _vaultUnlocked = true);
    } else if (entered == saved) {
      if (mounted) setState(() => _vaultUnlocked = true);
    } else if (mounted) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('PIN à¦®à¦¿à¦²à§‡à¦¨à¦¿')));
    }
  }

  Widget _explainablePanchang() {
    final now = DateTime.now();
    final sun = PanchangCalculator.sunTimes(
      now,
      lat: AppLocation.lat,
      lon: AppLocation.lon,
    );
    final t = PanchangCalculator.tithiFor(sun.sunrise);
    final nak = PanchangCalculator
        .nakshatraNames[PanchangCalculator.nakshatraIndexFor(sun.sunrise)];
    final rashi = PanchangCalculator
        .rashiNames[PanchangCalculator.rashiIndexFor(sun.sunrise)];
    final rahu = PanchangCalculator.rahuKalam(now);
    final abh = PanchangCalculator.abhijitMuhurta(now);
    final insideRahu =
        now.isAfter(rahu['start']!) && now.isBefore(rahu['end']!);
    int score = 70;
    if (abh['applicable'] == true) score += 12;
    if (insideRahu) score -= 18;
    if (BengaliCalendarData.eventsFor(now).isNotEmpty) score += 4;
    score = score.clamp(0, 100);
    return Column(
      children: [
        _glass(
          Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              _heading(
                'à¦†à¦œà¦•à§‡à¦° à¦à¦¤à¦¿à¦¹à§à¦¯à¦­à¦¿à¦¤à§à¦¤à¦¿à¦• Panchang Score â€¢ ${bnNum(score)}/à§§à§¦à§¦',
              ),
              const SizedBox(height: 8),
              _line('ðŸ•‰', '${t.paksha} à¦ªà¦•à§à¦· â€¢ ${t.name}'),
              _line('â­', 'à¦¨à¦•à§à¦·à¦¤à§à¦°: $nak'),
              _line('ðŸª', 'à¦šà¦¨à§à¦¦à§à¦° à¦°à¦¾à¦¶à¦¿: $rashi'),
              _line(
                'â³',
                insideRahu
                    ? 'à¦à¦–à¦¨ à¦°à¦¾à¦¹à§à¦•à¦¾à¦²à§‡à¦° à¦®à¦§à§à¦¯à§‡ â€” à¦¨à¦¤à§à¦¨ à¦•à¦¾à¦œà§‡à¦° à¦¸à¦®à§Ÿ à¦¬à¦¾à¦›à¦¾à¦‡à§Ÿà§‡ à¦¸à¦¤à¦°à§à¦•à¦¤à¦¾'
                    : 'à¦à¦–à¦¨ à¦°à¦¾à¦¹à§à¦•à¦¾à¦²à§‡à¦° à¦¬à¦¾à¦‡à¦°à§‡',
              ),
              _line(
                'â˜€ï¸',
                abh['applicable'] == true
                    ? 'à¦†à¦œ à¦…à¦­à¦¿à¦œà¦¿à§Ž à¦®à§à¦¹à§‚à¦°à§à¦¤ à¦ªà¦¾à¦“à§Ÿà¦¾ à¦¯à¦¾à¦šà§à¦›à§‡'
