  Widget _advancedMoon() {
    final now = DateTime.now();
    const synodic = 29.530588853;
    final age = PanchangCalculator.moonAgeDays(now) % synodic;
    final angle = age / synodic * 2 * math.pi;
    final illumination = ((1 - math.cos(angle)) / 2 * 100).round();
    final waxing = age < synodic / 2;
    DateTime? nextPurnima;
    DateTime? nextAmavasya;
    for (int i = 0; i < 45; i++) {
      final d = DateTime(now.year, now.month, now.day).add(Duration(days: i));
      final ev = BengaliCalendarData.eventsFor(d);
      if (nextPurnima == null && ev.any((e) => e.category == 'purnima'))
        nextPurnima = d;
      if (nextAmavasya == null && ev.any((e) => e.category == 'amabasya'))
        nextAmavasya = d;
    }
    return Column(
      children: [
        _glass(
          Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              _heading('ðŸŒ• Advanced Moon Center'),
              const SizedBox(height: 10),
              Center(
                child: SizedBox(
                  width: 120,
                  height: 120,
                  child: CustomPaint(
                    painter: _MoonPhasePainter(
                      illumination: illumination / 100.0,
                      waxing: waxing,
                    ),
                  ),
                ),
              ),
              const SizedBox(height: 10),
              _line(
                'ðŸ’¡',
                'à¦†à¦²à§‹à¦•à¦¿à¦¤ à¦…à¦‚à¦¶ à¦ªà§à¦°à¦¾à§Ÿ ${bnNum(illumination)}%',
              ),
              _line(
                'ðŸŒ—',
                waxing
                    ? 'à¦¶à§à¦•à§à¦²à¦ªà¦•à§à¦· â€¢ à¦šà¦¾à¦à¦¦ à¦¬à¦¾à§œà¦›à§‡'
                    : 'à¦•à§ƒà¦·à§à¦£à¦ªà¦•à§à¦· â€¢ à¦šà¦¾à¦à¦¦ à¦•à¦®à¦›à§‡',
              ),
              _line(
                'ðŸŒ•',
                nextPurnima == null
                    ? 'à¦ªà¦°à¦¬à¦°à§à¦¤à§€ à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾ à¦¤à¦¾à¦²à¦¿à¦•à¦¾à§Ÿ à¦ªà¦¾à¦“à§Ÿà¦¾ à¦¯à¦¾à§Ÿà¦¨à¦¿'
                    : 'à¦ªà¦°à¦¬à¦°à§à¦¤à§€ à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾: ${bnNum(nextPurnima.day)} ${gregMonthBn(nextPurnima.month)}',
              ),
              _line(
                'ðŸŒ‘',
                nextAmavasya == null
                    ? 'à¦ªà¦°à¦¬à¦°à§à¦¤à§€ à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾ à¦¤à¦¾à¦²à¦¿à¦•à¦¾à§Ÿ à¦ªà¦¾à¦“à§Ÿà¦¾ à¦¯à¦¾à§Ÿà¦¨à¦¿'
                    : 'à¦ªà¦°à¦¬à¦°à§à¦¤à§€ à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾: ${bnNum(nextAmavasya.day)} ${gregMonthBn(nextAmavasya.month)}',
              ),
            ],
          ),
        ),
      ],
