  Widget _miniApps() {
    final now = DateTime.now();
    String ageText =
        'à¦œà¦¨à§à¦®à¦¤à¦¾à¦°à¦¿à¦– à¦¨à¦¿à¦°à§à¦¬à¦¾à¦šà¦¨ à¦•à¦°à§à¦¨';
    if (_miniDob != null) {
      int y = now.year - _miniDob!.year;
      if (DateTime(now.year, _miniDob!.month, _miniDob!.day).isAfter(now)) y--;
      ageText = 'à¦¬à§Ÿà¦¸ à¦ªà§à¦°à¦¾à§Ÿ ${bnNum(y)} à¦¬à¦›à¦°';
    }
    String cdText = 'Countdown date à¦¨à¦¿à¦°à§à¦¬à¦¾à¦šà¦¨ à¦•à¦°à§à¦¨';
    if (_countdownDate != null) {
      final days = DateTime(
        _countdownDate!.year,
        _countdownDate!.month,
        _countdownDate!.day,
      ).difference(DateTime(now.year, now.month, now.day)).inDays;
      cdText = days < 0
          ? 'à¦¤à¦¾à¦°à¦¿à¦–à¦Ÿà¦¿ à¦šà¦²à§‡ à¦—à§‡à¦›à§‡'
          : '${bnNum(days)} à¦¦à¦¿à¦¨ à¦¬à¦¾à¦•à¦¿';
    }
    return Column(
      children: [
        _glass(
