class _VastuRoomPlannerScreenState extends State<VastuRoomPlannerScreen> {
  String _room = _roomVastuRules.keys.first;
  String _direction = 'NE';

  String get _status {
    final r = _roomVastuRules[_room]!;
    if (r.preferred.contains(_direction))
      return 'à¦–à§à¦¬ à¦ªà§à¦°à¦šà¦²à¦¿à¦¤ à¦ªà¦›à¦¨à§à¦¦';
    if (r.acceptable.contains(_direction))
      return 'à¦—à§à¦°à¦¹à¦£à¦¯à§‹à¦—à§à¦¯ à¦¬à¦¿à¦•à¦²à§à¦ª';
    return 'à¦…à¦¨à§à¦¯ layout-à¦“ à¦¬à¦¿à¦¬à§‡à¦šà¦¨à¦¾ à¦•à¦°à§à¦¨';
  }

  Color get _statusColor {
    final r = _roomVastuRules[_room]!;
    if (r.preferred.contains(_direction)) return const Color(0xFF65D69A);
    if (r.acceptable.contains(_direction)) return const Color(0xFFFFD36E);
    return const Color(0xFFFF9B7A);
