class VastuHomeChecklistScreen extends StatefulWidget {
  const VastuHomeChecklistScreen({super.key});
  @override
  State<VastuHomeChecklistScreen> createState() =>
      _VastuHomeChecklistScreenState();
}

class _VastuHomeChecklistScreenState extends State<VastuHomeChecklistScreen> {
  static const _storageKey = 'vastu_home_checklist_v1';
  static const _items = [
    'à¦ªà§‚à¦œà¦¾/à¦§à§à¦¯à¦¾à¦¨à§‡à¦° à¦œà¦¾à§Ÿà¦—à¦¾ à¦¶à¦¾à¦¨à§à¦¤ à¦“ à¦ªà¦°à¦¿à¦·à§à¦•à¦¾à¦°',
    'Kitchen-à¦ exhaust/ventilation à¦†à¦›à§‡',
    'Main door circulation à¦¬à¦¾à¦§à¦¾à¦¹à§€à¦¨',
    'Bedroom-à¦ privacy à¦“ ventilation à¦ à¦¿à¦•',
    'Study area-à¦¤à§‡ à¦ªà¦°à§à¦¯à¦¾à¦ªà§à¦¤ à¦†à¦²à§‹',
    'Toilet waterproofing/exhaust plan à¦¹à§Ÿà§‡à¦›à§‡',
    'Staircase safety/handrail/code check à¦¹à§Ÿà§‡à¦›à§‡',
    'Water tank/plumbing load engineer check à¦•à¦°à§‡à¦›à§‡à¦¨',
    'Foundation/column structural engineer approve à¦•à¦°à§‡à¦›à§‡à¦¨',
    'Local setback/building permission check à¦¹à§Ÿà§‡à¦›à§‡',
  ];
  final Set<int> _done = {};
  bool _loaded = false;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final p = await SharedPreferences.getInstance();
    final raw = p.getStringList(_storageKey) ?? const [];
    if (!mounted) return;
    setState(() {
      _done
        ..clear()
        ..addAll(raw.map(int.tryParse).whereType<int>());
      _loaded = true;
    });
  }

  Future<void> _toggle(int i, bool value) async {
    setState(() {
      if (value) {
        _done.add(i);
      } else {
        _done.remove(i);
      }
    });
    final p = await SharedPreferences.getInstance();
    await p.setStringList(_storageKey, _done.map((e) => '$e').toList());
  }

  Future<void> _reset() async {
    setState(_done.clear);
    final p = await SharedPreferences.getInstance();
    await p.remove(_storageKey);
  }

  @override
  Widget build(BuildContext context) {
    final pct = _items.isEmpty
        ? 0
        : ((_done.length / _items.length) * 100).round();
    return CosmicBackground(
      child: Column(
        children: [
          const _ScreenHeader(title: 'âœ… Home Vastu Checklist'),
          Expanded(
            child: !_loaded
                ? const Center(child: CircularProgressIndicator())
                : ListView(
                    padding: const EdgeInsets.fromLTRB(14, 8, 14, 30),
                    children: [
                      _VastuGlassCard(
                        child: Row(
                          children: [
                            SizedBox(
                              width: 54,
                              height: 54,
                              child: Stack(
                                fit: StackFit.expand,
                                children: [
                                  CircularProgressIndicator(
                                    value: pct / 100,
                                    color: const Color(0xFFFFD36E),
                                    backgroundColor: Colors.white12,
                                  ),
                                  Center(
                                    child: Text(
                                      '$pct%',
                                      style: const TextStyle(
                                        color: Colors.white,
                                        fontSize: 11,
                                        fontWeight: FontWeight.w900,
                                      ),
                                    ),
                                  ),
                                ],
                              ),
                            ),
                            const SizedBox(width: 12),
                            Expanded(
                              child: Text(
                                '${_done.length}/${_items.length} planning check complete',
                                style: const TextStyle(
                                  color: Colors.white,
                                  fontSize: 14,
                                  fontWeight: FontWeight.w800,
                                ),
                              ),
                            ),
                            TextButton(
                              onPressed: _reset,
                              child: const Text('Reset'),
                            ),
                          ],
                        ),
                      ),
                      const SizedBox(height: 10),
                      ...List.generate(
                        _items.length,
                        (i) => Container(
                          margin: const EdgeInsets.only(bottom: 8),
                          decoration: BoxDecoration(
                            color: const Color(
                              0xFF07172F,
                            ).withValues(alpha: 0.62),
                            borderRadius: BorderRadius.circular(14),
                            border: Border.all(
                              color: Colors.white.withValues(alpha: 0.12),
                            ),
                          ),
                          child: CheckboxListTile(
                            value: _done.contains(i),
                            onChanged: (v) => _toggle(i, v ?? false),
                            activeColor: const Color(0xFFFFD36E),
                            checkColor: const Color(0xFF071428),
                            title: Text(
                              _items[i],
                              style: const TextStyle(
                                color: Colors.white,
                                fontSize: 12.2,
                              ),
                            ),
                          ),
                        ),
                      ),
                    ],
                  ),
          ),
        ],
      ),
    );
  }
}

class SuperServicesScreen extends StatelessWidget {
  const SuperServicesScreen({super.key});

  void _open(BuildContext context, String title) {
    void pushPage(Widget page) {
      Navigator.push(context, MaterialPageRoute(builder: (_) => page));
    }

    void openSheet(String sheetTitle) {
      showModalBottomSheet(
        context: context,
        backgroundColor: Colors.transparent,
        isScrollControlled: true,
        builder: (_) => _FeatureSheet(title: sheetTitle),
      );
    }

    switch (title) {
      case 'à¦¬à¦¾à¦‚à¦²à¦¾ à¦•à§à¦¯à¦¾à¦²à§‡à¦¨à§à¦¡à¦¾à¦°':
        pushPage(const BengaliCalendarScreen());
        return;

      case 'à¦†à¦œà¦•à§‡à¦° à¦ªà¦žà§à¦œà¦¿à¦•à¦¾':
        pushPage(const TodaySmartScreen());
        return;

      case 'à¦à¦•à¦¾à¦¦à¦¶à§€':
        openSheet('à¦à¦•à¦¾à¦¦à¦¶à§€');
        return;

      case 'à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾':
        showModalBottomSheet(
          context: context,
          backgroundColor: Colors.transparent,
          isScrollControlled: true,
          builder: (_) => const _MoonPhaseSheet(initialIsPurnima: true),
        );
        return;

      case 'à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾':
        showModalBottomSheet(
          context: context,
          backgroundColor: Colors.transparent,
          isScrollControlled: true,
          builder: (_) => const _MoonPhaseSheet(initialIsPurnima: false),
        );
        return;

      case 'à¦‰à§Žà¦¸à¦¬':
        openSheet('à¦‰à§Žà¦¸à¦¬ à¦“ à¦¬à¦¿à¦¶à§‡à¦· à¦¦à¦¿à¦¨');
        return;

      case 'à¦¶à§à¦­ à¦®à§à¦¹à§‚à¦°à§à¦¤':
      case 'à¦¬à¦¿à¦¬à¦¾à¦¹':
      case 'à¦—à§ƒà¦¹à¦ªà§à¦°à¦¬à§‡à¦¶':
      case 'à¦—à¦¾à§œà¦¿ à¦•à§‡à¦¨à¦¾':
      case 'à¦œà¦®à¦¿ à¦•à§‡à¦¨à¦¾':
      case 'à¦¬à§à¦¯à¦¬à¦¸à¦¾ à¦¶à§à¦°à§':
        pushPage(const ShubhoMuhurtaScreen());
        return;

      case 'Family Calendar':
      case 'à¦¬à¦¾à¦‚à¦²à¦¾ à¦œà¦¨à§à¦®à¦¦à¦¿à¦¨':
        pushPage(const FamilyCalendarScreen());
        return;

      case 'Reminder':
      case 'à¦¬à¦¾à¦‚à¦²à¦¾ Voice':
      case 'Festival Alert':
        pushPage(const ReminderScreen());
        return;

      case 'Favourite Day':
        pushPage(const FavouriteDayScreen());
        return;

      case 'Date Converter':
        pushPage(const DateConverterScreen());
        return;

      case 'à¦†à¦œ à¦•à§€ à¦­à¦¾à¦²à§‹':
      case 'Panchang Timeline':
        pushPage(const TodaySmartScreen());
        return;

      case 'Month Summary':
        pushPage(const MonthSummaryScreen());
        return;

      case 'Puja Checklist':
        pushPage(const PujaChecklistScreen());
        return;

      case 'à¦œà¦ª à¦•à¦¾à¦‰à¦¨à§à¦Ÿà¦¾à¦°':
        pushPage(const JapaCounterScreen());
