class _BengaliCalendarScreenState extends State<BengaliCalendarScreen> {
  DateTime _anchor = DateTime.now();
  String _tab = 'à¦¸à¦®à§à¦ªà§‚à¦°à§à¦£ à¦®à¦¾à¦¸';
  String? _selectedKey;

  static const _tabs = [
