    'à¦¬à¦¿à¦¶à§‡à¦· à¦¦à¦¿à¦¨ à¦¸à¦®à§‚à¦¹',
    'à¦¬à¦¿à¦¬à¦¾à¦¹',
    'à¦…à¦¨à§à¦¨à¦ªà§à¦°à¦¾à¦¶à¦¨',
    'à¦—à§ƒà¦¹à¦ªà§à¦°à¦¬à§‡à¦¶',
    'à¦¬à§à¦¯à¦¬à¦¸à¦¾ à¦¶à§à¦°à§',
    'à¦¨à¦¾à¦®à¦•à¦°à¦£',
  ];
  static const _weekDays = [
    'à¦°à¦¬à¦¿',
    'à¦¸à§‹à¦®',
    'à¦®à¦™à§à¦—à¦²',
    'à¦¬à§à¦§',
    'à¦¬à§ƒà¦¹à¦ƒ',
    'à¦¶à§à¦•à§à¦°',
    'à¦¶à¦¨à¦¿',
  ];
  static const _engAbbrev = [
    'JAN',
    'FEB',
    'MAR',
    'APR',
    'MAY',
    'JUN',
    'JUL',
    'AUG',
    'SEP',
    'OCT',
    'NOV',
    'DEC',
  ];
  // à¦°à§‡à¦«à¦¾à¦°à§‡à¦¨à§à¦¸ à¦›à¦¾à¦ªà¦¾ à¦•à§à¦¯à¦¾à¦²à§‡à¦¨à§à¦¡à¦¾à¦°à§‡à¦° à¦®à¦¤à§‹ à¦®à¦¾à¦¸ à¦¨à§‡à¦­à¦¿à¦—à§‡à¦¶à¦¨à§‡ à¦ªà§à¦°à§‹ à¦‡à¦‚à¦°à§‡à¦œà¦¿ à¦®à¦¾à¦¸à§‡à¦° à¦¨à¦¾à¦®
  static const _engMonthFull = [
    'JANUARY',
    'FEBRUARY',
    'MARCH',
    'APRIL',
    'MAY',
    'JUNE',
    'JULY',
    'AUGUST',
    'SEPTEMBER',
    'OCTOBER',
    'NOVEMBER',
    'DECEMBER',
  ];
  static const _bnDigits = [
    'à§¦',
    'à§§',
    'à§¨',
    'à§©',
    'à§ª',
    'à§«',
    'à§¬',
    'à§­',
    'à§®',
    'à§¯',
  ];

  String _bn(int n) =>
      n.toString().split('').map((c) => _bnDigits[int.parse(c)]).join();
  String _key(DateTime d) =>
      '${d.year}-${d.month.toString().padLeft(2, "0")}-${d.day.toString().padLeft(2, "0")}';

  String _tabCategory(String tab) {
    switch (tab) {
      case 'à¦¬à¦¿à¦¬à¦¾à¦¹':
        return 'marriage';
      case 'à¦…à¦¨à§à¦¨à¦ªà§à¦°à¦¾à¦¶à¦¨':
        return 'annaprashan';
      case 'à¦—à§ƒà¦¹à¦ªà§à¦°à¦¬à§‡à¦¶':
        return 'griha';
      case 'à¦¬à§à¦¯à¦¬à¦¸à¦¾ à¦¶à§à¦°à§':
        return 'byabosha';
      case 'à¦¨à¦¾à¦®à¦•à¦°à¦£':
        return 'namakaran';
      default:
        return '';
    }
  }

  void _changeMonth(int delta) {
    setState(() {
      final info = BengaliDateUtil.monthInfoFor(_anchor);
      _anchor = delta > 0
          ? info.end.add(const Duration(days: 5))
          : info.start.subtract(const Duration(days: 5));
      _selectedKey = null;
    });
  }

  void _goToday() {
    setState(() {
      _anchor = DateTime.now();
      _selectedKey = null;
    });
  }

  void _reset() {
    setState(() {
      _tab = 'à¦¸à¦®à§à¦ªà§‚à¦°à§à¦£ à¦®à¦¾à¦¸';
      _selectedKey = null;
    });
  }

  // ---- à¦ªà§à¦°à¦¥à¦¾à¦—à¦¤ à¦ªà¦žà§à¦œà¦¿à¦•à¦¾à¦° à¦°à¦‚-à¦•à§‹à¦¡à¦¿à¦‚ â€” à¦ªà§à¦°à¦¤à¦¿à¦Ÿà¦¾ à¦¦à¦¿à¦¨à§‡à¦° à¦˜à¦°à§‡ à¦à¦• à¦¨à¦œà¦°à§‡ à¦¬à§‹à¦à¦¾à¦° à¦œà¦¨à§à¦¯ ----
  static const Color _purnimaColor = Color(
    0xFFFFD36E,
  ); // à¦¸à§‹à¦¨à¦¾à¦²à¦¿ â€” à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾
  static const Color _amabasyaColor = Color(
    0xFFA285E8,
  ); // à¦—à¦¾à¦¢à¦¼ à¦¬à§‡à¦—à§à¦¨à¦¿ â€” à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾
  static const Color _ekadashiColor = Color(
    0xFFFF9A3E,
  ); // à¦œà¦¾à¦«à¦°à¦¾à¦¨ â€” à¦à¦•à¦¾à¦¦à¦¶à§€
  static const Color _sankrantiColor = Color(
    0xFF2FBFA3,
  ); // à¦Ÿà¦¿à¦² â€” à¦¸à¦‚à¦•à§à¦°à¦¾à¦¨à§à¦¤à¦¿ (à¦®à¦¾à¦¸ à¦¶à§à¦°à§)
  static const Color _festivalColor = Color(
    0xFFE0384A,
  ); // à¦²à¦¾à¦² â€” à¦‰à§Žà¦¸à¦¬/à¦¶à§à¦­ à¦¦à¦¿à¦¨/à¦°à¦¬à¦¿à¦¬à¦¾à¦°

  bool _hasCategory(List<CalendarEvent> events, String cat) =>
      events.any((e) => e.category == cat);

  /// à¦¦à¦¿à¦¨à§‡à¦° à¦˜à¦°à§‡à¦° à¦ªà§à¦°à¦§à¦¾à¦¨ (à¦¸à¦¬à¦šà§‡à¦¯à¦¼à§‡ à¦—à§à¦°à§à¦¤à§à¦¬à¦ªà§‚à¦°à§à¦£) à¦°à¦‚ â€” à¦à¦•à¦¾à¦§à¦¿à¦• à¦ªà§à¦°à¦¯à§‹à¦œà§à¦¯ à¦¹à¦²à§‡
  /// à¦ªà§à¦°à¦¥à¦¾à¦—à¦¤ à¦ªà¦žà§à¦œà¦¿à¦•à¦¾à¦° à¦…à¦—à§à¦°à¦¾à¦§à¦¿à¦•à¦¾à¦° à¦…à¦¨à§à¦¯à¦¾à¦¯à¦¼à§€: à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾ > à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾ > à¦à¦•à¦¾à¦¦à¦¶à§€ >
  /// à¦¸à¦‚à¦•à§à¦°à¦¾à¦¨à§à¦¤à¦¿ > à¦‰à§Žà¦¸à¦¬/à¦¶à§à¦­ à¦¦à¦¿à¦¨ > à¦°à¦¬à¦¿à¦¬à¦¾à¦°
  Color? _primaryCategoryColor(
    List<CalendarEvent> events,
    bool isSankranti,
    bool isSunday,
  ) {
    if (_hasCategory(events, 'purnima')) return _purnimaColor;
    if (_hasCategory(events, 'amabasya')) return _amabasyaColor;
    if (_hasCategory(events, 'ekadashi')) return _ekadashiColor;
    if (isSankranti) return _sankrantiColor;
    if (events.isNotEmpty) return _festivalColor;
    if (isSunday) return _festivalColor;
    return null;
  }

  Widget _legendDot(Color color, String label) {
    return Row(
      mainAxisSize: MainAxisSize.min,
