/// à¦ªà§à¦°à¦¤à¦¿à¦Ÿà¦¾ à¦˜à¦° à¦¨à¦¿à¦œà§‡à¦° à¦¬à¦¾à¦‚à¦²à¦¾ à¦¤à¦¾à¦°à¦¿à¦– à¦…à¦¨à§à¦¯à¦¾à¦¯à¦¼à§€ à¦¸à¦¾à¦®à¦¾à¦¨à§à¦¯ à¦­à¦¿à¦¨à§à¦¨ à¦¬à¦¿à¦²à¦®à§à¦¬à§‡ à¦¶à§à¦°à§ à¦¹à¦¯à¦¼,
/// à¦¯à¦¾à¦¤à§‡ à¦ªà§à¦°à§‹ à¦—à§à¦°à¦¿à¦¡à§‡à¦° à¦¸à¦¬ à¦˜à¦° à¦à¦•à¦¸à¦¾à¦¥à§‡ à¦¨à¦¾ à¦¬à¦¦à¦²à§‡ à¦¸à§à¦¬à¦¾à¦­à¦¾à¦¬à¦¿à¦•/à¦œà§€à¦¬à¦¨à§à¦¤ à¦¦à§‡à¦–à¦¾à¦¯à¦¼à¥¤
class _MonthlyPanjikaSlider extends StatefulWidget {
  final BengaliMonthInfo info;

  const _MonthlyPanjikaSlider({required this.info});

  @override
  State<_MonthlyPanjikaSlider> createState() => _MonthlyPanjikaSliderState();
}

class _MonthlyPanjikaSliderState extends State<_MonthlyPanjikaSlider> {
  int _index = 0;
  Timer? _timer;

  @override
  void initState() {
    super.initState();
    _startSlider();
  }

  @override
  void didUpdateWidget(covariant _MonthlyPanjikaSlider oldWidget) {
    super.didUpdateWidget(oldWidget);

    if (oldWidget.info.start != widget.info.start) {
      _index = 0;
      _startSlider();
    }
  }

  void _startSlider() {
    _timer?.cancel();

    _timer = Timer.periodic(const Duration(seconds: 4), (_) {
      if (!mounted) return;

      final items = _monthItems();

      if (items.length > 1) {
        setState(() {
          _index = (_index + 1) % items.length;
        });
      }
    });
  }

  List<Map<String, dynamic>> _monthItems() {
    final result = <Map<String, dynamic>>[];

    final total = widget.info.end.difference(widget.info.start).inDays + 1;

    for (var i = 0; i < total; i++) {
      final date = widget.info.start.add(Duration(days: i));

      final events = BengaliCalendarData.eventsFor(date);

      for (final event in events) {
        result.add({
          'date': date,
          'bengaliDay': i + 1,
          'label': event.label,
          'icon': event.icon,
          'category': event.category,
        });
      }
    }

    return result;
  }

  String _bn(int value) {
    const d = [
      'à§¦',
      'à§§',
      'à§¨',
      'à§©',
      'à§ª',
      'à§«',
      'à§¬',
      'à§­',
      'à§®',
      'à§¯',
    ];

    return value.toString().split('').map((e) => d[int.parse(e)]).join();
  }

  String _typeName(String category) {
    switch (category) {
      case 'ekadashi':
        return 'à¦à¦•à¦¾à¦¦à¦¶à§€';
      case 'purnima':
        return 'à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾';
      case 'amabasya':
        return 'à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾';
      case 'marriage':
        return 'à¦¬à¦¿à¦¬à¦¾à¦¹à§‡à¦° à¦¶à§à¦­ à¦¦à¦¿à¦¨';
      case 'annaprashan':
        return 'à¦…à¦¨à§à¦¨à¦ªà§à¦°à¦¾à¦¶à¦¨à§‡à¦° à¦¶à§à¦­ à¦¦à¦¿à¦¨';
      case 'griha':
        return 'à¦—à§ƒà¦¹à¦ªà§à¦°à¦¬à§‡à¦¶à§‡à¦° à¦¶à§à¦­ à¦¦à¦¿à¦¨';
      case 'byabosha':
        return 'à¦¬à§à¦¯à¦¬à¦¸à¦¾à¦° à¦¶à§à¦­ à¦¦à¦¿à¦¨';
      case 'namakaran':
        return 'à¦¨à¦¾à¦®à¦•à¦°à¦£à§‡à¦° à¦¶à§à¦­ à¦¦à¦¿à¦¨';
      default:
        return 'à¦ªà§‚à¦œà¦¾ â€¢ à¦‰à§Žà¦¸à¦¬ â€¢ à¦¬à¦¿à¦¶à§‡à¦· à¦¦à¦¿à¦¨';
    }
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final items = _monthItems();

    if (items.isEmpty) {
      return const SizedBox.shrink();
    }

    final item = items[_index % items.length];

    final date = item['date'] as DateTime;
    final bengaliDay = item['bengaliDay'] as int;
    final label = item['label'] as String;
    final icon = item['icon'] as String;
    final category = item['category'] as String;

    return Container(
      width: double.infinity,
      height: 76,
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(16),
        color: const Color(0xFF2B0E45).withValues(alpha: 0.68),
        border: Border.all(
          color: const Color(0xFFFFD36E).withValues(alpha: 0.55),
          width: 1.2,
        ),
      ),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
        child: AnimatedSwitcher(
          duration: const Duration(milliseconds: 500),
          transitionBuilder: (child, animation) {
            return SlideTransition(
              position: Tween<Offset>(
                begin: const Offset(0.25, 0),
                end: Offset.zero,
              ).animate(animation),
              child: FadeTransition(opacity: animation, child: child),
            );
          },
          child: Row(
            key: ValueKey('$label-${date.toIso8601String()}-$_index'),
            children: [
              Container(
                width: 48,
                height: 48,
                alignment: Alignment.center,
                decoration: BoxDecoration(
                  color: Colors.white.withValues(alpha: 0.13),
                  borderRadius: BorderRadius.circular(12),
                ),
                child: Text(icon, style: const TextStyle(fontSize: 25)),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      label,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: Colors.white,
                        fontSize: 14,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    const SizedBox(height: 3),
                    Text(
                      '${_bn(bengaliDay)} ${widget.info.name} â€¢ ${_typeName(category)}',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: Color(0xFFFFD467),
                        fontSize: 10,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                    const SizedBox(height: 2),
                    Text(
                      '${date.day}/${date.month}/${date.year}',
                      style: TextStyle(
                        color: Colors.white.withValues(alpha: 0.65),
                        fontSize: 8.8,
                      ),
                    ),
                  ],
                ),
              ),
              Text(
                '${_index + 1}/${items.length}',
                style: TextStyle(
                  color: Colors.white.withValues(alpha: 0.55),
                  fontSize: 8,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _CalendarDayCell extends StatefulWidget {
  final DateTime greg;
  final int bengaliDay;
  final String bnDay;
  final String secondaryDateText;
  final String tithiName;
  final List<CalendarEvent> events;
  final bool isToday;
  final bool isSelected;
  final bool isSankranti;
  final bool isSunday;
  final bool dim;
  final bool highlightTint;
  final Color? Function(
    List<CalendarEvent> events,
    bool isSankranti,
    bool isSunday,
  )
  primaryCategoryColor;
  final VoidCallback onTap;

  const _CalendarDayCell({
    required this.greg,
    required this.bengaliDay,
    required this.bnDay,
    required this.secondaryDateText,
    required this.tithiName,
    required this.events,
    required this.isToday,
    required this.isSelected,
    required this.isSankranti,
    required this.isSunday,
    required this.dim,
    required this.highlightTint,
    required this.primaryCategoryColor,
    required this.onTap,
  });

  @override
  State<_CalendarDayCell> createState() => _CalendarDayCellState();
}

class _CalendarDayCellState extends State<_CalendarDayCell> {
  int _infoIndex = 0;
  Timer? _timer;

  @override
  void initState() {
    super.initState();
    _startInfoCycle();
  }

  @override
  void didUpdateWidget(covariant _CalendarDayCell oldWidget) {
    super.didUpdateWidget(oldWidget);

    if (oldWidget.greg != widget.greg ||
        oldWidget.events.length != widget.events.length ||
        oldWidget.isToday != widget.isToday) {
      _infoIndex = 0;
      _startInfoCycle();
    }
  }

  void _startInfoCycle() {
    _timer?.cancel();

    // Only today's box moves.
    if (!widget.isToday) {
      _infoIndex = 0;
      return;
    }

    _timer = Timer.periodic(const Duration(seconds: 3), (_) {
      if (!mounted) return;

      setState(() {
        _infoIndex++;
      });
    });
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  Widget _specialIcon(CalendarEvent event) {
    switch (event.category) {
      case 'amabasya':
        return Container(
          width: 10,
          height: 10,
          decoration: const BoxDecoration(
            color: Color(0xFF111111),
            shape: BoxShape.circle,
          ),
        );

      case 'purnima':
        return Container(
          width: 11,
          height: 11,
          decoration: BoxDecoration(
            color: const Color(0xFFFFFEF7),
            shape: BoxShape.circle,
            border: Border.all(color: const Color(0xFF333333), width: 1),
          ),
        );

      case 'ekadashi':
        return const Icon(Icons.eco, size: 13, color: Color(0xFF278D4F));

      default:
        if (event.icon.trim().isEmpty || event.icon == 'âœ¦') {
          return const Icon(
            Icons.celebration,
            size: 12,
            color: Color(0xFFC62828),
          );
        }

        return Text(
          event.icon,
          style: const TextStyle(fontSize: 11, height: 1),
        );
    }
  }

  @override
  Widget build(BuildContext context) {
    final events = widget.events;
    final primaryEvent = events.isNotEmpty ? events.first : null;

    final categoryColor = widget.primaryCategoryColor(
      events,
      widget.isSankranti,
      widget.isSunday,
    );

    final numberColor =
        categoryColor ??
        (widget.isSunday ? const Color(0xFFFF8A80) : Colors.white);

    final sun = PanchangCalculator.sunTimes(
      widget.greg,
      lat: AppLocation.lat,
      lon: AppLocation.lon,
    );

    final tithi = PanchangCalculator.tithiFor(sun.sunrise);

    final nakIndex = PanchangCalculator.nakshatraIndexFor(sun.sunrise);

    final rashiIndex = PanchangCalculator.rashiIndexFor(sun.sunrise);

    final nakshatra = PanchangCalculator.nakshatraNames[nakIndex];

    final rashi = PanchangCalculator.rashiNames[rashiIndex];

    final monthShort = const [
      '',
      'JAN',
      'FEB',
      'MAR',
      'APR',
      'MAY',
      'JUN',
      'JUL',
      'AUG',
      'SEP',
      'OCT',
      'NOV',
      'DEC',
    ][widget.greg.month];

    // TODAY box only:
    // Nakshatra/Rashi -> Sunrise -> Event
    // No "à¦†à¦œ" / "à¦•à¦¾à¦²" text.
    final movingItems = <String>[
      '$nakshatra \u2022 $rashi',
      '\u2600 ${bnTime12(sun.sunrise)}',
      ...events.map((e) => '${e.icon} ${e.label}'),
    ];

    final movingText = movingItems[_infoIndex % movingItems.length];

    final staticInfo = '$nakshatra \u2022 $rashi';

    return GestureDetector(
      onTap: widget.onTap,
      child: Opacity(
        opacity: widget.dim ? 0.35 : 1,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 220),
          decoration: BoxDecoration(
            color: widget.highlightTint
                ? const Color(0xFF6A2D72).withValues(alpha: 0.42)
                : widget.isToday
                ? const Color(0xFFFFD36E).withValues(alpha: 0.18)
                : const Color(0xFF07182E).withValues(alpha: 0.62),
            borderRadius: BorderRadius.circular(5),
            border: Border.all(
              color: widget.isSelected
                  ? const Color(0xFFFFD36E)
                  : widget.isToday
                  ? const Color(0xFFFFD36E)
                  : Colors.white.withValues(alpha: 0.14),
              width: widget.isSelected || widget.isToday ? 1.5 : 0.8,
            ),
            boxShadow: widget.isToday
                ? [
                    BoxShadow(
                      color: const Color(0xFFFFD36E).withValues(alpha: 0.22),
                      blurRadius: 5,
                    ),
                  ]
                : null,
          ),
          child: ClipRect(
            child: Stack(
              children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(2, 3, 2, 3),
                  child: Column(
                    children: [
                      Align(
                        alignment: Alignment.topRight,
                        child: Text(
                          '${widget.greg.day} $monthShort',
                          maxLines: 1,
                          style: TextStyle(
                            fontSize: 6.5,
                            height: 1,
                            fontWeight: FontWeight.w800,
                            color: widget.isSunday
                                ? const Color(0xFFFF8A80)
                                : Colors.white70,
                          ),
                        ),
                      ),

                      const SizedBox(height: 1),

                      Expanded(
                        child: Center(
                          child: FittedBox(
                            fit: BoxFit.scaleDown,
                            child: Text(
                              widget.bnDay,
                              style: TextStyle(
                                fontSize: 36,
                                height: 0.90,
                                fontWeight: FontWeight.w900,
                                color: numberColor,
                              ),
                            ),
                          ),
                        ),
                      ),

                      FittedBox(
                        fit: BoxFit.scaleDown,
                        child: Text(
                          '${tithi.paksha} ${tithi.name}',
                          maxLines: 1,
                          style: const TextStyle(
                            fontSize: 8.8,
                            height: 1,
                            fontWeight: FontWeight.w800,
                            color: Colors.white,
                          ),
                        ),
                      ),

                      const SizedBox(height: 2),

                      SizedBox(
                        height: 11,
                        width: double.infinity,
                        child: widget.isToday
                            ? AnimatedSwitcher(
                                duration: const Duration(milliseconds: 400),
                                transitionBuilder: (child, animation) {
                                  final slide = Tween<Offset>(
                                    begin: const Offset(0.25, 0),
                                    end: Offset.zero,
                                  ).animate(animation);

                                  return ClipRect(
                                    child: SlideTransition(
                                      position: slide,
                                      child: FadeTransition(
                                        opacity: animation,
                                        child: child,
                                      ),
                                    ),
                                  );
                                },
                                child: Center(
                                  key: ValueKey('$movingText-$_infoIndex'),
                                  child: FittedBox(
                                    fit: BoxFit.scaleDown,
                                    child: Text(
                                      movingText,
                                      maxLines: 1,
                                      style: const TextStyle(
                                        fontSize: 7.4,
                                        height: 1,
                                        fontWeight: FontWeight.w600,
                                        color: Colors.white70,
                                      ),
                                    ),
                                  ),
                                ),
                              )
                            : Center(
                                child: FittedBox(
                                  fit: BoxFit.scaleDown,
                                  child: Text(
                                    staticInfo,
                                    maxLines: 1,
                                    style: const TextStyle(
                                      fontSize: 7.4,
                                      height: 1,
                                      fontWeight: FontWeight.w600,
                                      color: Colors.white70,
                                    ),
                                  ),
                                ),
                              ),
                      ),
                    ],
                  ),
                ),

                // Special-day icon only.
                // Normal days stay clean.
                if (primaryEvent != null)
                  Positioned(
                    left: 3,
                    top: 3,
                    child: SizedBox(
                      width: 14,
                      height: 14,
                      child: Center(child: _specialIcon(primaryEvent)),
                    ),
                  ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

class ReminderItem {
  String text;
  DateTime when;

  /// à¦¨à§‹à¦Ÿà¦¿à¦«à¦¿à¦•à§‡à¦¶à¦¨ à¦¬à¦¾à¦¤à¦¿à¦²/à¦ªà§à¦¨à¦°à¦¾à¦¯à¦¼ à¦¸à§‡à¦Ÿ à¦•à¦°à¦¾à¦° à¦œà¦¨à§à¦¯ à¦¸à§à¦¥à¦¾à¦¯à¦¼à§€ à¦†à¦‡à¦¡à¦¿
  final int id;
  ReminderItem(this.text, this.when, {int? id})
    : id = id ?? DateTime.now().microsecondsSinceEpoch.remainder(0x7FFFFFFF);
}

// =====================================================================
// à¦­à¦¯à¦¼à§‡à¦¸ à¦°à¦¿à¦®à¦¾à¦‡à¦¨à§à¦¡à¦¾à¦° â€” à¦¬à¦Ÿà¦® à¦¶à§€à¦Ÿà¥¤ à¦®à¦¾à¦‡à¦•à§‡ à¦¬à¦²à¦¾ à¦•à¦¥à¦¾ à¦²à¦¾à¦‡à¦­ à¦¦à§‡à¦–à¦¾à¦¯à¦¼, à¦¤à¦¾à¦°à¦ªà¦°
// VoiceReminderParser à¦¦à¦¿à¦¯à¦¼à§‡ à¦¤à¦¾à¦°à¦¿à¦–/à¦¸à¦®à¦¯à¦¼/à¦Ÿà§‡à¦•à§à¦¸à¦Ÿ à¦¬à§‡à¦° à¦•à¦°à§‡ à¦ªà§à¦°à¦¿à¦­à¦¿à¦‰ à¦¦à§‡à¦–à¦¾à¦¯à¦¼à¥¤
// à¦¬à§à¦¯à¦¬à¦¹à¦¾à¦°à¦•à¦¾à¦°à§€ "à¦«à¦°à§à¦®à§‡ à¦¬à¦¸à¦¾à¦“" à¦šà¦¾à¦ªà¦²à§‡à¦‡ à¦«à¦²à¦¾à¦«à¦² à¦«à§‡à¦°à¦¤ à¦¯à¦¾à¦¯à¦¼ â€” à¦†à¦¸à¦² à¦¸à§‡à¦­ existing
// _addReminder()/ReminderStore.instance.add() à¦¦à¦¿à¦¯à¦¼à§‡à¦‡ à¦¹à¦¯à¦¼, à¦à¦–à¦¾à¦¨à§‡ à¦¨à¦¤à§à¦¨ à¦•à§‹à¦¨à§‹
// à¦¸à§‡à¦­-à¦²à¦œà¦¿à¦• à¦¨à§‡à¦‡à¥¤
// =====================================================================

class _VoiceReminderSheet extends StatefulWidget {
  const _VoiceReminderSheet();
  @override
  State<_VoiceReminderSheet> createState() => _VoiceReminderSheetState();
}

class _VoiceReminderSheetState extends State<_VoiceReminderSheet> {
  final stt.SpeechToText _speech = stt.SpeechToText();
  bool _available = false;
  bool _initializing = true;
  bool _listening = false;
  String _liveText = '';
  String? _error;
  VoiceReminderParseResult? _result;

  @override
  void initState() {
    super.initState();
    _init();
  }

  Future<void> _init() async {
    try {
      final ok = await _speech.initialize(
        onStatus: (status) {
          if ((status == 'done' || status == 'notListening') && mounted) {
            setState(() => _listening = false);
            if (_liveText.trim().isNotEmpty && _result == null) {
              _finalize(_liveText);
            }
          }
        },
        onError: (err) {
          if (mounted) {
            setState(() {
              _listening = false;
              _error =
                  'à¦­à¦¯à¦¼à§‡à¦¸ à¦šà§‡à¦¨à¦¾ à¦¯à¦¾à¦šà§à¦›à§‡ à¦¨à¦¾ â€” à¦†à¦¬à¦¾à¦° à¦šà§‡à¦·à§à¦Ÿà¦¾ à¦•à¦°à§à¦¨';
            });
          }
        },
      );
      if (!mounted) return;
      setState(() {
        _available = ok;
        _initializing = false;
      });
      if (ok) _startListening();
    } catch (_) {
      if (!mounted) return;
      setState(() {
        _available = false;
        _initializing = false;
        _error =
            'à¦à¦‡ à¦«à§‹à¦¨à§‡ à¦­à¦¯à¦¼à§‡à¦¸ à¦‡à¦¨à¦ªà§à¦Ÿ à¦šà¦¾à¦²à§ à¦•à¦°à¦¾ à¦¯à¦¾à¦¯à¦¼à¦¨à¦¿';
      });
    }
  }

  Future<void> _startListening() async {
    setState(() {
      _listening = true;
      _liveText = '';
      _result = null;
      _error = null;
    });
    void onResult(dynamic result) {
      if (!mounted) return;
      setState(() => _liveText = result.recognizedWords as String);
      if (result.finalResult == true) {
        _finalize(_liveText);
      }
    }

    try {
      // à¦¬à¦¾à¦‚à¦²à¦¾ à¦²à§‹à¦•à§‡à¦² à¦¦à¦¿à¦¯à¦¼à§‡ à¦†à¦—à§‡ à¦šà§‡à¦·à§à¦Ÿà¦¾ â€” à¦¨à¦¾ à¦¥à¦¾à¦•à¦²à§‡ à¦¡à¦¿à¦­à¦¾à¦‡à¦¸à§‡à¦° à¦¡à¦¿à¦«à¦²à§à¦Ÿ à¦­à¦¾à¦·à¦¾à¦¤à§‡à¦‡
      await _speech.listen(
        onResult: onResult,
        localeId: 'bn_IN',
        listenFor: const Duration(seconds: 12),
        pauseFor: const Duration(seconds: 3),
      );
    } catch (_) {
      try {
        await _speech.listen(
          onResult: onResult,
          listenFor: const Duration(seconds: 12),
          pauseFor: const Duration(seconds: 3),
        );
      } catch (_) {
        if (mounted) {
          setState(() {
            _listening = false;
            _error =
                'à¦­à¦¯à¦¼à§‡à¦¸ à¦‡à¦¨à¦ªà§à¦Ÿ à¦¶à§à¦°à§ à¦•à¦°à¦¾ à¦¯à¦¾à¦¯à¦¼à¦¨à¦¿';
          });
        }
      }
    }
  }

  void _finalize(String text) {
    if (text.trim().isEmpty) return;
    setState(() {
      _result = VoiceReminderParser.parse(text);
      _listening = false;
    });
  }

  @override
  void dispose() {
    _speech.stop();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: EdgeInsets.fromLTRB(
        20,
        20,
        20,
        MediaQuery.of(context).viewInsets.bottom + 24,
      ),
      decoration: const BoxDecoration(
        color: Color(0xFF0B1C38),
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Row(
            children: [
              Icon(Icons.mic, color: Color(0xFFFFD36E)),
              SizedBox(width: 8),
              Text(
                'à¦­à¦¯à¦¼à§‡à¦¸ à¦°à¦¿à¦®à¦¾à¦‡à¦¨à§à¦¡à¦¾à¦°',
                style: TextStyle(
                  color: Colors.white,
                  fontSize: 17,
                  fontWeight: FontWeight.bold,
                ),
              ),
            ],
          ),
          const SizedBox(height: 6),
          const Text(
