        : 'à¦†à¦° ${bnNum(days)} à¦¦à¦¿à¦¨ à¦¬à¦¾à¦•à¦¿';
    final years = m.upcomingYears;
    if (m.occasion == 'à¦œà¦¨à§à¦®à¦¦à¦¿à¦¨' && years > 0) {
      return '$whenTxt â€¢ ${bnNum(years)} à¦¬à¦›à¦° à¦ªà§‚à¦°à§à¦£ à¦¹à¦¬à§‡';
    }
    if (m.occasion == 'à¦¬à¦¿à¦¬à¦¾à¦¹à¦¬à¦¾à¦°à§à¦·à¦¿à¦•à§€' && years > 0) {
      return '$whenTxt â€¢ ${bnNum(years)} à¦¤à¦® à¦¬à¦¾à¦°à§à¦·à¦¿à¦•à§€';
