      await Share.shareXFiles(
        [
          XFile.fromData(
            bytes,
            name: 'ajker_panchang.png',
            mimeType: 'image/png',
          ),
        ],
        text: shareText,
        subject: 'à¦†à¦œà¦•à§‡à¦° à¦ªà¦žà§à¦šà¦¾à¦™à§à¦—',
      );
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'à¦•à¦¾à¦°à§à¦¡ à¦¶à§‡à¦¯à¦¼à¦¾à¦° à¦•à¦°à¦¾ à¦¯à¦¾à¦¯à¦¼à¦¨à¦¿ â€” à¦†à¦¬à¦¾à¦° à¦šà§‡à¦·à§à¦Ÿà¦¾ à¦•à¦°à§à¦¨',
