class PremiumScreen extends StatefulWidget {
  const PremiumScreen({super.key});
  @override
  State<PremiumScreen> createState() => _PremiumScreenState();
}

class _PremiumScreenState extends State<PremiumScreen> {
  Razorpay? _razorpay;
  String? _selectedPlan;
  bool _processing = false;

  @override
  void initState() {
    super.initState();
    if (!kIsWeb) {
      _razorpay = Razorpay()
        ..on(Razorpay.EVENT_PAYMENT_SUCCESS, _onPaymentSuccess)
        ..on(Razorpay.EVENT_PAYMENT_ERROR, _onPaymentError)
        ..on(Razorpay.EVENT_EXTERNAL_WALLET, _onExternalWallet);
    }
    PaymentService.instance.refreshStatus();
  }

  @override
  void dispose() {
    _razorpay?.clear();
    super.dispose();
  }

  Future<void> _startPayment(PremiumPlan plan) async {
    setState(() {
      _selectedPlan = plan.id;
      _processing = true;
    });
    try {
      final order = await PaymentService.instance.createOrder(plan.id);
      _razorpay?.open({
        'key': order['key'],
        'amount': order['amount'],
        'currency': order['currency'],
        'order_id': order['order_id'],
        'name': 'à¦¬à¦¾à¦‚à¦²à¦¾ à¦ªà¦žà§à¦œà¦¿à¦•à¦¾',
        'description': order['plan_label'],
        'prefill': {'contact': '', 'email': ''},
        'theme': {'color': '#FFD36E'},
      });
    } catch (e) {
      if (!mounted) return;
      setState(() => _processing = false);
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(e.toString().replaceFirst('Exception: ', ''))),
      );
    }
  }

  Future<void> _onPaymentSuccess(PaymentSuccessResponse response) async {
    try {
      final expiresAt = await PaymentService.instance.verify(
        orderId: response.orderId ?? '',
        paymentId: response.paymentId ?? '',
        signature: response.signature ?? '',
      );
      await AppSettings.instance.activatePremium(expiresAt);
      if (!mounted) return;
      setState(() => _processing = false);
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'ðŸŽ‰ à¦ªà§à¦°à¦¿à¦®à¦¿à¦¯à¦¼à¦¾à¦® à¦¸à¦•à§à¦°à¦¿à¦¯à¦¼ à¦¹à¦¯à¦¼à§‡à¦›à§‡!',
          ),
        ),
      );
    } catch (e) {
      if (!mounted) return;
      setState(() => _processing = false);
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            'à¦¯à¦¾à¦šà¦¾à¦‡ à¦¬à§à¦¯à¦°à§à¦¥: ${e.toString().replaceFirst('Exception: ', '')}',
          ),
        ),
      );
    }
  }

  void _onPaymentError(PaymentFailureResponse response) {
    if (!mounted) return;
    setState(() => _processing = false);
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          'à¦ªà§‡à¦®à§‡à¦¨à§à¦Ÿ à¦¬à§à¦¯à¦°à§à¦¥ à¦¹à¦¯à¦¼à§‡à¦›à§‡: ${response.message ?? ''}',
        ),
      ),
    );
  }

  void _onExternalWallet(ExternalWalletResponse response) {
    if (!mounted) return;
    setState(() => _processing = false);
  }

  void _showLockedMessage(AppSettings s) {
    final msg = !s.trialActivated
        ? 'ðŸ”’ à¦†à¦—à§‡ à¦‰à¦ªà¦°à§‡à¦° à§©à§¦ à¦¦à¦¿à¦¨à§‡à¦° à¦«à§à¦°à¦¿ à¦Ÿà§à¦°à¦¾à¦¯à¦¼à¦¾à¦² à¦¶à§à¦°à§ à¦•à¦°à§à¦¨à¥¤'
        : (s.inTrialPeriod
              ? 'ðŸ”’ à¦à¦‡ Premium feature à¦à¦–à¦¨ à¦–à§‹à¦²à¦¾ à¦¥à¦¾à¦•à¦¾à¦° à¦•à¦¥à¦¾ â€” à¦†à¦¬à¦¾à¦° à¦šà§‡à¦·à§à¦Ÿà¦¾ à¦•à¦°à§à¦¨à¥¤'
              : 'ðŸ”’ à¦«à§à¦°à¦¿ à¦Ÿà§à¦°à¦¾à¦¯à¦¼à¦¾à¦² à¦¶à§‡à¦·à¥¤ à¦‰à¦ªà¦°à§‡à¦° Premium plan à¦¸à¦•à§à¦°à¦¿à¦¯à¦¼ à¦•à¦°à§à¦¨à¥¤');
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(msg), duration: const Duration(seconds: 2)),
    );
  }

  void _openPremiumPage(
    AppSettings s,
    String title,
    Widget Function() builder,
  ) {
    if (!s.hasPremiumAccess) {
