  Widget _festivalPrepView() {
    final now = DateTime.now();
    DateTime? festivalDate;
    List<CalendarEvent> events = [];
    for (int i = 0; i <= 120; i++) {
      final d = DateTime(now.year, now.month, now.day).add(Duration(days: i));
      final ev = BengaliCalendarData.eventsFor(d)
          .where(
            (e) => ![
              'purnima',
              'amabasya',
              'ekadashi',
              'sankranti',
            ].contains(e.category),
          )
          .toList();
      if (ev.isNotEmpty) {
        festivalDate = d;
        events = ev;
        break;
      }
    }
    if (festivalDate == null) {
      return _glass(
        const Text(
          'à¦†à¦—à¦¾à¦®à§€ à§§à§¨à§¦ à¦¦à¦¿à¦¨à§‡à¦° saved festival data-à¦¤à§‡ à¦•à§‹à¦¨à§‹ à¦¬à§œ à¦‰à§Žà¦¸à¦¬ à¦ªà¦¾à¦“à§Ÿà¦¾ à¦¯à¦¾à§Ÿà¦¨à¦¿à¥¤',
          style: TextStyle(color: Colors.white70),
