class _Phase14DynamicHomeCard extends StatefulWidget {
  const _Phase14DynamicHomeCard();
  @override
  State<_Phase14DynamicHomeCard> createState() =>
      _Phase14DynamicHomeCardState();
}

class _Phase14DynamicHomeCardState extends State<_Phase14DynamicHomeCard> {
  Timer? _timer;
  @override
  void initState() {
    super.initState();
    _timer = Timer.periodic(const Duration(seconds: 30), (_) {
      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  String _period(int h) {
    if (h < 10) return 'à¦¸à¦•à¦¾à¦²à§‡à¦° à¦«à§‹à¦•à¦¾à¦¸';
    if (h < 15) return 'à¦¦à§à¦ªà§à¦°à§‡à¦° à¦«à§‹à¦•à¦¾à¦¸';
    if (h < 19) return 'à¦¸à¦¨à§à¦§à§à¦¯à¦¾à¦° à¦ªà§à¦°à¦¸à§à¦¤à§à¦¤à¦¿';
    return 'à¦†à¦—à¦¾à¦®à§€à¦•à¦¾à¦²à§‡à¦° à¦ªà§à¦°à¦¸à§à¦¤à§à¦¤à¦¿';
  }

  @override
  Widget build(BuildContext context) {
    final now = DateTime.now();
    final sun = PanchangCalculator.sunTimes(
      now,
      lat: AppLocation.lat,
      lon: AppLocation.lon,
    );
    final tithi = PanchangCalculator.tithiFor(now);
    final rahu = PanchangCalculator.rahuKalam(
      now,
      lat: AppLocation.lat,
      lon: AppLocation.lon,
    );
    final nextFestival = BengaliCalendarData.upcomingFestivals(count: 1);
    final isRahu = now.isAfter(rahu['start']!) && now.isBefore(rahu['end']!);
    String focus;
    if (now.hour < 10) {
      focus =
          'à¦†à¦œ ${tithi.name} â€¢ à¦¸à§‚à¦°à§à¦¯à§‹à¦¦à¦¯à¦¼ ${bnTime12(sun.sunrise)}';
    } else if (now.hour < 15) {
      focus = isRahu
          ? 'à¦°à¦¾à¦¹à§à¦•à¦¾à¦² à¦šà¦²à¦›à§‡ â€¢ à¦¶à§‡à¦· ${bnTime12(rahu['end']!)}'
          : 'à¦¬à¦°à§à¦¤à¦®à¦¾à¦¨ à¦ªà¦žà§à¦œà¦¿à¦•à¦¾ à¦¦à§à¦°à§à¦¤ à¦¦à§‡à¦–à§‡ à¦•à¦¾à¦œ à¦ªà¦°à¦¿à¦•à¦²à§à¦ªà¦¨à¦¾ à¦•à¦°à§à¦¨';
    } else if (now.hour < 19) {
      focus =
          'à¦¸à§‚à¦°à§à¦¯à¦¾à¦¸à§à¦¤ ${bnTime12(sun.sunset)} â€¢ à¦¸à¦¨à§à¦§à§à¦¯à¦¾à¦° à¦ªà§‚à¦œà¦¾/à¦ªà§à¦°à¦¦à§€à¦ª à¦ªà§à¦°à¦¸à§à¦¤à§à¦¤à¦¿';
    } else {
      focus = nextFestival.isEmpty
          ? 'à¦†à¦—à¦¾à¦®à§€à¦•à¦¾à¦²à§‡à¦° à¦¤à¦¿à¦¥à¦¿ à¦“ à¦•à¦¾à¦œ à¦†à¦—à§‡ à¦¦à§‡à¦–à§‡ à¦¨à¦¿à¦¨'
          : 'à¦ªà¦°à¦¬à¦°à§à¦¤à§€: ${nextFestival.first['icon']} ${nextFestival.first['title']}';
    }
    return _P14GlassCard(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Text('ðŸ§­', style: TextStyle(fontSize: 23)),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                  'Dynamic Home 2.0 â€¢ ${_period(now.hour)}',
                  style: TextStyle(
                    color: Phase14Prefs.accent,
                    fontSize: 13.2,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
              Text(
                bnTime12(now),
                style: const TextStyle(color: Colors.white70, fontSize: 10.5),
              ),
            ],
          ),
          const SizedBox(height: 7),
          Text(
            focus,
            style: const TextStyle(
              color: Colors.white,
              fontSize: 12.2,
              height: 1.4,
              fontWeight: FontWeight.w700,
            ),
          ),
          const SizedBox(height: 9),
          Row(
            children: [
              Expanded(
                child: OutlinedButton.icon(
                  onPressed: () => Navigator.push(
                    context,
                    MaterialPageRoute(
                      builder: (_) => const Phase14AdvancedMoonCenterScreen(),
                    ),
                  ),
                  icon: const Icon(Icons.dark_mode_rounded, size: 16),
                  label: const Text('Moon'),
                ),
              ),
              const SizedBox(width: 8),
              Expanded(
                child: OutlinedButton.icon(
                  onPressed: () => Navigator.push(
                    context,
                    MaterialPageRoute(
                      builder: (_) =>
                          const Phase14FestivalSmartDashboardScreen(),
                    ),
                  ),
                  icon: const Icon(Icons.celebration_rounded, size: 16),
                  label: const Text('Festival'),
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }
}

