class Phase14AdvancedMoonCenterScreen extends StatefulWidget {
  const Phase14AdvancedMoonCenterScreen({super.key});
  @override
  State<Phase14AdvancedMoonCenterScreen> createState() =>
      _Phase14AdvancedMoonCenterScreenState();
}

class _Phase14AdvancedMoonCenterScreenState
    extends State<Phase14AdvancedMoonCenterScreen> {
  Timer? _timer;
  @override
  void initState() {
    super.initState();
    _timer = Timer.periodic(const Duration(seconds: 30), (_) {
      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  DateTime? _nextTithi(String word) {
    final now = DateTime.now();
    for (int i = 0; i < 40; i++) {
      final d = DateTime(now.year, now.month, now.day).add(Duration(days: i));
      final sun = PanchangCalculator.sunTimes(
        d,
        lat: AppLocation.lat,
        lon: AppLocation.lon,
      );
      if (PanchangCalculator.tithiFor(sun.sunrise).name.contains(word))
        return d;
    }
    return null;
  }

  String _phase(double age) {
    if (age < 1.5 || age > 28.0)
      return 'à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾à¦° à¦•à¦¾à¦›à¦¾à¦•à¦¾à¦›à¦¿';
    if (age < 7.4) return 'à¦¶à§à¦•à§à¦²à¦ªà¦•à§à¦· â€¢ à¦¬à¦¾à§œà¦›à§‡';
    if (age < 9.0) return 'à¦ªà§à¦°à¦¥à¦®à¦¾à¦°à§à¦§';
    if (age < 14.0) return 'à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾à¦° à¦¦à¦¿à¦•à§‡';
    if (age < 16.0)
      return 'à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾à¦° à¦•à¦¾à¦›à¦¾à¦•à¦¾à¦›à¦¿';
    if (age < 22.0) return 'à¦•à§ƒà¦·à§à¦£à¦ªà¦•à§à¦· â€¢ à¦•à¦®à¦›à§‡';
    return 'à¦¶à§‡à¦·à¦¾à¦°à§à¦§';
  }

  @override
  Widget build(BuildContext context) {
    final now = DateTime.now();
    final age = PanchangCalculator.moonAgeDays(now);
    final illumination = ((1 - math.cos(2 * math.pi * age / 29.530588)) / 2)
        .clamp(0.0, 1.0);
    final sun = PanchangCalculator.sunTimes(
      now,
      lat: AppLocation.lat,
      lon: AppLocation.lon,
    );
    final moonrise = sun.sunrise.add(Duration(minutes: (age * 48.8).round()));
    final moonset = moonrise.add(const Duration(hours: 12, minutes: 25));
    final full = _nextTithi('à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾');
    final newMoon = _nextTithi('à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾');
    final rashi =
        PanchangCalculator.rashiNames[PanchangCalculator.rashiIndexFor(now)];
    return CosmicBackground(
      child: Column(
        children: [
          const _ScreenHeader(title: 'ðŸŒ™ Advanced Moon Center'),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.all(14),
              children: [
                _P14GlassCard(
                  child: Row(
                    children: [
                      Container(
                        width: 86,
                        height: 86,
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          gradient: RadialGradient(
                            colors: [
                              Colors.white.withValues(alpha: 0.95),
                              Colors.blueGrey.withValues(alpha: 0.35),
                              Colors.transparent,
                            ],
                          ),
                        ),
                        child: Center(
                          child: Text(
                            '${(illumination * 100).round()}%',
                            style: const TextStyle(
                              color: Color(0xFF071428),
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                        ),
                      ),
                      const SizedBox(width: 14),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              _phase(age),
                              style: TextStyle(
                                color: Phase14Prefs.accent,
                                fontSize: 16,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                            const SizedBox(height: 5),
                            Text(
                              'à¦šà¦¨à§à¦¦à§à¦° à¦°à¦¾à¦¶à¦¿: $rashi',
                              style: const TextStyle(color: Colors.white),
                            ),
                            Text(
                              'Moon age: ${age.toStringAsFixed(1)} à¦¦à¦¿à¦¨',
                              style: const TextStyle(
                                color: Colors.white60,
                                fontSize: 11,
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: 12),
                _P14GlassCard(
                  child: Wrap(
                    spacing: 12,
                    runSpacing: 10,
                    children: [
                      _moonFact(
                        'ðŸŒ™ à¦šà¦¨à§à¦¦à§à¦°à§‹à¦¦à§Ÿ',
                        bnTime12(moonrise),
                      ),
                      _moonFact(
                        'ðŸŒ— à¦šà¦¨à§à¦¦à§à¦°à¦¾à¦¸à§à¦¤',
                        bnTime12(moonset),
                      ),
                      _moonFact(
                        'ðŸŒ• à¦ªà¦°à§‡à¦° à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾',
                        full == null
                            ? 'â€”'
                            : '${bnNum(full.day)} ${gregMonthBn(full.month)}',
                      ),
                      _moonFact(
                        'ðŸŒ‘ à¦ªà¦°à§‡à¦° à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾',
                        newMoon == null
                            ? 'â€”'
                            : '${bnNum(newMoon.day)} ${gregMonthBn(newMoon.month)}',
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: 12),
                const _P14GlassCard(
                  child: Text(
                    'à¦šà¦¾à¦à¦¦à§‡à¦° illumination à¦“ rise/set à¦à¦–à¦¾à¦¨à§‡ app-à¦à¦° existing astronomical approximation à¦¥à§‡à¦•à§‡ à¦¦à§‡à¦–à¦¾à¦¨à§‹ à¦¹à§Ÿà¥¤ à¦‰à¦šà§à¦š-à¦¨à¦¿à¦°à§à¦­à§à¦² à¦ªà¦°à§à¦¯à¦¬à§‡à¦•à§à¦·à¦£/à¦¨à§‡à¦­à¦¿à¦—à§‡à¦¶à¦¨à§‡à¦° à¦œà¦¨à§à¦¯ à¦¬à¦¿à¦¶à§‡à¦· astronomical source à¦¬à§à¦¯à¦¬à¦¹à¦¾à¦° à¦•à¦°à§à¦¨à¥¤',
                    style: TextStyle(
                      color: Colors.white54,
                      fontSize: 10.5,
                      height: 1.45,
                    ),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _moonFact(String a, String b) => Container(
    width: 145,
    padding: const EdgeInsets.all(10),
    decoration: BoxDecoration(
      color: Colors.white.withValues(alpha: 0.05),
      borderRadius: BorderRadius.circular(12),
    ),
    child: Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(a, style: const TextStyle(color: Colors.white60, fontSize: 10)),
        const SizedBox(height: 3),
        Text(
          b,
          style: const TextStyle(
            color: Colors.white,
            fontWeight: FontWeight.w800,
            fontSize: 12,
          ),
        ),
      ],
    ),
  );
}

