class Phase14NotificationRulesScreen extends StatefulWidget {
  const Phase14NotificationRulesScreen({super.key});
  @override
  State<Phase14NotificationRulesScreen> createState() =>
      _Phase14NotificationRulesScreenState();
}

class _Phase14NotificationRulesScreenState
    extends State<Phase14NotificationRulesScreen> {
  bool festival = true;
  bool ekadashi = true;
  bool purnima = true;
  int lead = 1;
  bool applying = false;

  Future<void> _apply() async {
    setState(() => applying = true);
    await ReminderStore.instance.load();
    final now = DateTime.now();
    int added = 0;
    for (int i = 1; i <= 60 && added < 12; i++) {
      final d = DateTime(now.year, now.month, now.day).add(Duration(days: i));
      final ev = BengaliCalendarData.eventsFor(d);
      for (final e in ev) {
        final match =
            (festival && e.category == 'general') ||
            (ekadashi && e.category == 'ekadashi') ||
            (purnima && (e.category == 'purnima' || e.category == 'amabasya'));
        if (!match) continue;
        final when = DateTime(
          d.year,
          d.month,
          d.day,
          19,
        ).subtract(Duration(days: lead));
        if (when.isAfter(now)) {
          await ReminderStore.instance.add(
            ReminderItem(
              '${e.icon} ${e.label} â€” à¦†à¦° ${bnNum(lead)} à¦¦à¦¿à¦¨',
              when,
            ),
          );
          added++;
        }
        if (added >= 12) break;
      }
    }
    if (!mounted) return;
    setState(() => applying = false);
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          '${bnNum(added)}à¦Ÿà¦¿ upcoming alert à¦ªà§à¦°à¦¸à§à¦¤à§à¦¤ à¦¹à§Ÿà§‡à¦›à§‡',
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return CosmicBackground(
      child: Column(
        children: [
          const _ScreenHeader(title: 'ðŸ”” Intelligent Notification Rules'),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.all(14),
              children: [
                _P14GlassCard(
                  child: Column(
                    children: [
                      SwitchListTile(
                        value: festival,
                        onChanged: (v) => setState(() => festival = v),
                        title: const Text(
                          'à¦‰à§Žà¦¸à¦¬ Alert',
                          style: TextStyle(color: Colors.white),
                        ),
                      ),
                      SwitchListTile(
                        value: ekadashi,
                        onChanged: (v) => setState(() => ekadashi = v),
                        title: const Text(
                          'à¦à¦•à¦¾à¦¦à¦¶à§€ Alert',
                          style: TextStyle(color: Colors.white),
                        ),
                      ),
                      SwitchListTile(
                        value: purnima,
                        onChanged: (v) => setState(() => purnima = v),
                        title: const Text(
                          'à¦ªà§‚à¦°à§à¦£à¦¿à¦®à¦¾/à¦…à¦®à¦¾à¦¬à¦¸à§à¦¯à¦¾ Alert',
                          style: TextStyle(color: Colors.white),
                        ),
                      ),
                      DropdownButtonFormField<int>(
                        value: lead,
                        dropdownColor: const Color(0xFF07172F),
                        style: const TextStyle(color: Colors.white),
                        decoration: const InputDecoration(
                          labelText: 'à¦•à¦¤ à¦¦à¦¿à¦¨ à¦†à¦—à§‡',
                          labelStyle: TextStyle(color: Colors.white70),
                        ),
                        items: [1, 3, 7]
                            .map(
                              (n) => DropdownMenuItem(
                                value: n,
                                child: Text('${bnNum(n)} à¦¦à¦¿à¦¨ à¦†à¦—à§‡'),
                              ),
                            )
                            .toList(),
                        onChanged: (v) {
                          if (v != null) setState(() => lead = v);
                        },
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: 12),
                FilledButton.icon(
                  onPressed: applying ? null : _apply,
                  icon: const Icon(Icons.notifications_active_rounded),
                  label: Text(
                    applying
                        ? 'à¦ªà§à¦°à¦¸à§à¦¤à§à¦¤ à¦¹à¦šà§à¦›à§‡...'
                        : 'à¦†à¦—à¦¾à¦®à§€ à§¬à§¦ à¦¦à¦¿à¦¨à§‡à¦° rules Apply à¦•à¦°à§à¦¨',
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

