    return CosmicBackground(
      child: Column(
        children: [
          const _ScreenHeader(title: 'ðŸ“± Widget Pack Pro'),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.all(14),
              children: [
                ...modes.map(
                  (m) => Padding(
                    padding: const EdgeInsets.only(bottom: 8),
                    child: RadioListTile<String>(
