      _Phase14UniversalSearchScreenState();
}

class _Phase14UniversalSearchScreenState
    extends State<Phase14UniversalSearchScreen> {
  final c = TextEditingController();
  String q = '';

  @override
  void initState() {
    super.initState();
    FamilyMemberStore.instance.load().then((_) {
      if (mounted) setState(() {});
    });
    ReminderStore.instance.load().then((_) {
      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    c.dispose();
    super.dispose();
  }

  List<Map<String, String>> _results() {
    if (q.trim().isEmpty) return [];
    final query = q.trim().toLowerCase();
    final out = <Map<String, String>>[];
    for (final f in _phase14Features()) {
      if ('${f.title} ${f.subtitle}'.toLowerCase().contains(query)) {
        out.add({'icon': f.icon, 'title': f.title, 'sub': 'Feature'});
      }
    }
    for (final f in BengaliCalendarData.upcomingFestivals(count: 30)) {
      if ('${f['title']} ${f['date']}'.toLowerCase().contains(query)) {
        out.add({
          'icon': f['icon'] ?? 'ðŸŽŠ',
          'title': f['title'] ?? '',
          'sub': f['date'] ?? '',
        });
      }
    }
    for (final m in FamilyMemberStore.instance.items) {
      if ('${m.name} ${m.occasion}'.toLowerCase().contains(query)) {
        out.add({
          'icon': 'ðŸ‘¨â€ðŸ‘©â€ðŸ‘§',
          'title': m.name,
          'sub': m.occasion,
        });
      }
    }
    for (final r in ReminderStore.instance.items.take(50)) {
      if (r.text.toLowerCase().contains(query)) {
        out.add({'icon': 'ðŸ””', 'title': r.text, 'sub': 'Reminder'});
      }
    }
    return out.take(40).toList();
  }

  @override
  Widget build(BuildContext context) {
    final r = _results();
    return CosmicBackground(
      child: Column(
        children: [
          const _ScreenHeader(title: 'ðŸ”Ž Universal Search 2.0'),
          Padding(
            padding: const EdgeInsets.all(14),
            child: TextField(
              controller: c,
              autofocus: true,
              onChanged: (v) => setState(() => q = v),
              style: const TextStyle(color: Colors.white),
              decoration: InputDecoration(
                prefixIcon: const Icon(Icons.search, color: Colors.white70),
                hintText:
                    'à¦…à¦·à§à¦Ÿà¦®à§€ / festival / family / feature / reminder',
                hintStyle: const TextStyle(color: Colors.white38),
                filled: true,
                fillColor: const Color(0xFF07172F).withValues(alpha: 0.65),
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(16),
                  borderSide: BorderSide.none,
                ),
              ),
            ),
          ),
          Expanded(
            child: q.isEmpty
                ? const Center(
                    child: Text(
                      'à¦à¦• search-à¦ app-à¦à¦° à¦—à§à¦°à§à¦¤à§à¦¬à¦ªà§‚à¦°à§à¦£ à¦œà¦¿à¦¨à¦¿à¦¸ à¦–à§à¦à¦œà§à¦¨',
                      style: TextStyle(color: Colors.white54),
                    ),
                  )
                : ListView.builder(
                    padding: const EdgeInsets.fromLTRB(14, 0, 14, 20),
                    itemCount: r.length,
                    itemBuilder: (context, i) {
                      final x = r[i];
                      return Padding(
                        padding: const EdgeInsets.only(bottom: 7),
                        child: _P14GlassCard(
                          child: Row(
                            children: [
                              Text(
                                x['icon']!,
