class Phase14ShareStudioScreen extends StatefulWidget {
  const Phase14ShareStudioScreen({super.key});
  @override
  State<Phase14ShareStudioScreen> createState() =>
      _Phase14ShareStudioScreenState();
}

class _Phase14ShareStudioScreenState extends State<Phase14ShareStudioScreen> {
  String type = 'à¦†à¦œà¦•à§‡à¦° à¦ªà¦žà§à¦œà¦¿à¦•à¦¾';
  static const types = [
    'à¦†à¦œà¦•à§‡à¦° à¦ªà¦žà§à¦œà¦¿à¦•à¦¾',
    'Moon Card',
    'Next Festival',
    'à¦¬à¦¾à¦‚à¦²à¦¾ à¦¤à¦¾à¦°à¦¿à¦–',
  ];

  String _text() {
    final now = DateTime.now();
    final info = BengaliDateUtil.monthInfoFor(now);
    final bd = now.difference(info.start).inDays + 1;
    final t = PanchangCalculator.tithiFor(now);
    if (type == 'Moon Card') {
      final age = PanchangCalculator.moonAgeDays(now);
      final illum = ((1 - math.cos(2 * math.pi * age / 29.530588)) / 2 * 100)
          .round();
      return 'ðŸŒ™ à¦†à¦œà¦•à§‡à¦° à¦šà¦¾à¦à¦¦\nIllumination: $illum%\nà¦šà¦¨à§à¦¦à§à¦° à¦°à¦¾à¦¶à¦¿: ${PanchangCalculator.rashiNames[PanchangCalculator.rashiIndexFor(now)]}';
    }
    if (type == 'Next Festival') {
      final f = BengaliCalendarData.upcomingFestivals(count: 1);
      if (f.isEmpty)
        return 'ðŸŽŠ à¦¸à¦¾à¦®à¦¨à§‡ à¦•à§‹à¦¨à§‹ à¦‰à§Žà¦¸à¦¬ à¦ªà¦¾à¦“à§Ÿà¦¾ à¦¯à¦¾à§Ÿà¦¨à¦¿';
      final days = int.tryParse(f.first['daysLeft'] ?? '0') ?? 0;
      return 'ðŸŽŠ ${f.first['title']}\nðŸ“… ${f.first['date']}\nâ³ à¦†à¦° ${bnNum(days)} à¦¦à¦¿à¦¨';
    }
    if (type == 'à¦¬à¦¾à¦‚à¦²à¦¾ à¦¤à¦¾à¦°à¦¿à¦–') {
      return 'ðŸ“… ${bnNum(bd)} ${info.name} ${bnNum(info.year)}\n${bnNum(now.day)} ${gregMonthBn(now.month)} ${bnNum(now.year)}';
    }
    return 'ðŸª· à¦†à¦œà¦•à§‡à¦° à¦ªà¦žà§à¦œà¦¿à¦•à¦¾\n${bnNum(bd)} ${info.name} ${bnNum(info.year)}\n${t.paksha} à¦ªà¦•à§à¦· â€¢ ${t.name}\nðŸ“ ${AppLocation.district}';
  }

  @override
  Widget build(BuildContext context) {
    final txt = _text();
    return CosmicBackground(
      child: Column(
        children: [
          const _ScreenHeader(title: 'ðŸ“¤ Premium Share Studio'),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.all(14),
              children: [
                DropdownButtonFormField<String>(
                  value: type,
                  dropdownColor: const Color(0xFF07172F),
                  style: const TextStyle(color: Colors.white),
                  decoration: const InputDecoration(
                    labelText: 'Card type',
                    labelStyle: TextStyle(color: Colors.white70),
                  ),
                  items: types
                      .map((t) => DropdownMenuItem(value: t, child: Text(t)))
                      .toList(),
                  onChanged: (v) {
                    if (v != null) setState(() => type = v);
                  },
                ),
                const SizedBox(height: 14),
                _P14GlassCard(
                  child: Padding(
                    padding: const EdgeInsets.symmetric(vertical: 20),
                    child: Text(
                      txt,
                      textAlign: TextAlign.center,
                      style: TextStyle(
                        color: Phase14Prefs.accent,
                        fontSize: 17,
                        height: 1.7,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ),
                ),
                const SizedBox(height: 12),
                FilledButton.icon(
                  onPressed: () => Share.share(txt),
                  icon: const Icon(Icons.share_rounded),
                  label: const Text('Share'),
                ),
                const SizedBox(height: 8),
                OutlinedButton(
                  onPressed: () => Navigator.push(
                    context,
                    MaterialPageRoute(
                      builder: (_) => const FestivalPosterScreen(),
                    ),
                  ),
                  child: const Text('Poster Maker à¦–à§à¦²à§à¦¨'),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class Phase14FamilyVaultScreen extends StatefulWidget {
  const Phase14FamilyVaultScreen({super.key});
  @override
  State<Phase14FamilyVaultScreen> createState() =>
      _Phase14FamilyVaultScreenState();
}

class _Phase14FamilyVaultScreenState extends State<Phase14FamilyVaultScreen> {
  bool unlocked = false;
  String? savedPin;
  final pin = TextEditingController();
  final note = TextEditingController();
  List<String> notes = [];

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final p = await SharedPreferences.getInstance();
    savedPin = p.getString('p14_vault_pin');
    notes = p.getStringList('p14_vault_notes') ?? [];
    if (mounted) setState(() {});
  }

  Future<void> _savePin() async {
    final v = pin.text.trim();
    if (v.length < 4) return;
    final p = await SharedPreferences.getInstance();
    await p.setString('p14_vault_pin', v);
    savedPin = v;
    unlocked = true;
    pin.clear();
    setState(() {});
  }

  void _unlock() {
    if (pin.text.trim() == savedPin) {
      setState(() => unlocked = true);
      pin.clear();
    } else {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('PIN à¦®à¦¿à¦²à¦›à§‡ à¦¨à¦¾')),
      );
    }
  }

  Future<void> _add() async {
    if (note.text.trim().isEmpty) return;
    notes.insert(0, note.text.trim());
    note.clear();
    final p = await SharedPreferences.getInstance();
    await p.setStringList('p14_vault_notes', notes);
    setState(() {});
  }

  Future<void> _delete(int index) async {
    notes.removeAt(index);
    final p = await SharedPreferences.getInstance();
    await p.setStringList('p14_vault_notes', notes);
    setState(() {});
  }

  @override
  void dispose() {
    pin.dispose();
    note.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return CosmicBackground(
      child: Column(
        children: [
          const _ScreenHeader(title: 'ðŸ” Private Family Vault'),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.all(14),
              children: [
                if (savedPin == null || !unlocked)
                  _P14GlassCard(
                    child: Column(
                      children: [
                        Text(
                          savedPin == null
                              ? 'à¦¨à¦¤à§à¦¨ à§ª+ digit PIN à¦¸à§‡à¦Ÿ à¦•à¦°à§à¦¨'
                              : 'PIN à¦¦à¦¿à§Ÿà§‡ Vault à¦–à§à¦²à§à¦¨',
                          style: TextStyle(
                            color: Phase14Prefs.accent,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                        const SizedBox(height: 10),
                        TextField(
                          controller: pin,
                          obscureText: true,
                          keyboardType: TextInputType.number,
                          style: const TextStyle(color: Colors.white),
                          decoration: const InputDecoration(
                            hintText: 'PIN',
                            hintStyle: TextStyle(color: Colors.white38),
                          ),
                        ),
                        const SizedBox(height: 10),
                        FilledButton(
                          onPressed: savedPin == null ? _savePin : _unlock,
                          child: Text(savedPin == null ? 'PIN Save' : 'Unlock'),
                        ),
                      ],
                    ),
                  )
                else ...[
                  _P14GlassCard(
                    child: Column(
                      children: [
                        TextField(
                          controller: note,
                          maxLines: 3,
                          style: const TextStyle(color: Colors.white),
                          decoration: const InputDecoration(
                            hintText: 'Private family note',
                            hintStyle: TextStyle(color: Colors.white38),
                          ),
                        ),
                        const SizedBox(height: 8),
                        FilledButton.icon(
                          onPressed: _add,
                          icon: const Icon(Icons.lock_rounded),
                          label: const Text('Save note'),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(height: 10),
                  ...notes.asMap().entries.map(
                    (e) => Padding(
                      padding: const EdgeInsets.only(bottom: 7),
                      child: _P14GlassCard(
                        child: Row(
                          children: [
                            Expanded(
                              child: Text(
                                e.value,
                                style: const TextStyle(color: Colors.white70),
                              ),
                            ),
                            IconButton(
                              onPressed: () => _delete(e.key),
                              icon: const Icon(
                                Icons.delete_outline,
                                color: Colors.white38,
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                ],
                const SizedBox(height: 10),
                const Text(
                  'Privacy note: à¦à¦‡ version local PIN gate à¦¬à§à¦¯à¦¬à¦¹à¦¾à¦° à¦•à¦°à§‡; cryptographic encryption/biometric vault à¦¨à§Ÿà¥¤ à¦…à¦¤à§à¦¯à¦¨à§à¦¤ à¦¸à¦‚à¦¬à§‡à¦¦à¦¨à¦¶à§€à¦² à¦—à§‹à¦ªà¦¨ à¦¤à¦¥à§à¦¯ à¦à¦–à¦¾à¦¨à§‡ à¦¨à¦¾ à¦°à¦¾à¦–à¦¾à¦‡ à¦­à¦¾à¦²à§‹à¥¤',
                  style: TextStyle(
                    color: Colors.white54,
                    fontSize: 10.2,
                    height: 1.45,
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

